(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9139",module:"changshi",prompt:"中国漆器中著名的脱胎漆器产于哪里？",options:["福州", "扬州", "北京", "成都"],answer:0,explanation:"福州脱胎漆器以轻巧坚固著称，与北京景泰蓝、江西景德镇瓷器并称中国传统工艺三宝。"},{id:"cs-9140",module:"changshi",prompt:"青花瓷烧制的窑口以哪个城市最为著名？",options:["景德镇", "龙泉", "德化", "磁州"],answer:0,explanation:"江西景德镇自元代起成为青花瓷中心，明清御窑厂所产瓷器代表了中国制瓷业的最高水平。"},{id:"cs-9141",module:"changshi",prompt:"刺绣中的双面绣技艺是指什么？",options:["正反两面图案同样精美", "两层布叠加", "两次染色", "双线刺绣"],answer:0,explanation:"双面绣在透明底料上正反两面同时刺绣，两面图案同样工整精美，代表苏绣的顶尖技艺。"},{id:"cs-9142",module:"changshi",prompt:"中国传统印染工艺蜡染的主要原料是？",options:["蜂蜡", "桐油", "生漆", "石灰"],answer:0,explanation:"蜡染用蜂蜡在布上绘花后浸染，去蜡后呈现蓝底白花，贵州苗族蜡染最为著名。"},{id:"cs-9143",module:"changshi",prompt:"竹编工艺发达的地区主要分布在？",options:["南方竹资源丰富地区", "西北草原", "东北林区", "青藏高原"],answer:0,explanation:"竹编以南方竹产区最为发达，四川青神、浙江东阳等地的竹编技艺被列入非物质文化遗产。"},{id:"cs-9144",module:"changshi",prompt:"木版年画中著名的杨柳青年画产于哪个城市？",options:["天津", "苏州", "潍坊", "开封"],answer:0,explanation:"天津杨柳青木版年画与苏州桃花坞、潍坊杨家埠、开封朱仙镇并称中国四大木版年画产地。"},{id:"cs-9145",module:"changshi",prompt:"中国传统建筑中的榫卯结构是指什么？",options:["不用钉子的木构件凹凸咬合结构", "砖石砌筑方法", "彩绘技法", "地基处理技术"],answer:0,explanation:"榫卯通过木构件的凹凸咬合连接建筑，柔韧抗震，是中国木构建筑和家具的核心技术。"},{id:"cs-9146",module:"changshi",prompt:"苗族银饰锻制技艺主要流传于哪个省份？",options:["贵州", "云南", "湖南", "广西"],answer:0,explanation:"贵州黔东南苗族银饰锻制技艺精湛，银饰是苗族盛装的重要组成部分，被列入国家级非遗。"},{id:"cs-9147",module:"changshi",prompt:"中国传统缂丝技艺的特点是？",options:["通经断纬，图案如雕刻", "双面同色", "蜡防染色", "针绣"],answer:0,explanation:"缂丝采用通经断纬技法，图案与底色交界如刀刻，有刻丝之称，苏州缂丝最为著名。"},{id:"cs-9148",module:"changshi",prompt:"中国古琴艺术被列入人类非物质文化遗产的时间是？",options:["二零零三年", "一九九零年", "二零一零年", "一九九八年"],answer:0,explanation:"二零零三年中国古琴艺术被联合国教科文组织列入人类口头和非物质遗产代表作名录。"},{id:"cs-9149",module:"changshi",prompt:"龙泉青瓷以什么釉色著称？",options:["粉青和梅子青", "霁蓝", "郎红", "茶叶末"],answer:0,explanation:"浙江龙泉青瓷的粉青和梅子青釉色温润如玉，代表青瓷烧制的最高成就。"},{id:"cs-9150",module:"changshi",prompt:"中国传统手工艺中，点翠工艺使用的材料是？",options:["翠鸟羽毛", "孔雀石", "翡翠", "绿松石"],answer:0,explanation:"点翠以翠鸟羽毛贴饰金银底胎，色泽艳丽，因保护动物需要，现代多用染色鹅毛或仿翠材料替代。"},{id:"cs-9151",module:"changshi",prompt:"泥人张彩塑是哪个城市的传统工艺？",options:["天津", "北京", "济南", "西安"],answer:0,explanation:"天津泥人张彩塑创始于清代张明山，以写实传神著称，是中国彩塑艺术的代表。"},{id:"cs-9152",module:"changshi",prompt:"中国传统织锦中，云锦产于哪个城市？",options:["南京", "成都", "杭州", "苏州"],answer:0,explanation:"南京云锦织造技艺华贵精美，与成都蜀锦、苏州宋锦、广西壮锦并称中国四大名锦。"},{id:"cs-9153",module:"changshi",prompt:"中国传统工艺中，錾刻主要用于什么材料？",options:["金属", "木材", "竹材", "布料"],answer:0,explanation:"錾刻是用錾子在金属表面刻出花纹图案的技艺，金银器錾刻历史悠久，工艺精细。"},{id:"cs-9154",module:"changshi",prompt:"中国传统风筝制作技艺中，潍坊风筝以什么著称？",options:["造型多样、放飞性能好", "纯观赏", "微型化", "金属骨架"],answer:0,explanation:"山东潍坊是国际风筝之都，风筝扎制技艺精湛，每年举办国际风筝节。"},{id:"cs-9155",module:"changshi",prompt:"中国传统刺绣中，粤绣的特点是？",options:["构图饱满、色彩浓艳", "素雅淡净", "针法单一", "以黑白为主"],answer:0,explanation:"粤绣包括广绣和潮绣，构图饱满、色彩浓艳、金线运用广泛，富有装饰性。"},{id:"cs-9156",module:"changshi",prompt:"中国传统建筑彩画中的和玺彩画多用于什么建筑？",options:["皇家宫殿", "民居", "园林亭榭", "寺庙山门"],answer:0,explanation:"和玺彩画以龙凤纹样为主，等级最高，用于皇家宫殿如故宫的主要殿宇。"},{id:"cs-9157",module:"changshi",prompt:"中国剪纸被列入人类非物质文化遗产名录的时间是？",options:["二零零九年", "一九九九年", "二零一五年", "二零零零年"],answer:0,explanation:"二零零九年中国剪纸入选联合国教科文组织人类非物质文化遗产代表作名录。"},{id:"cs-9158",module:"changshi",prompt:"中国传统工艺中，漆线雕是哪个城市的特色工艺？",options:["厦门", "福州", "广州", "潮州"],answer:0,explanation:"厦门漆线雕以漆线盘结成浮雕纹样贴于器身，是闽南地区独特的传统工艺。"},{id:"cs-9159",module:"changshi",prompt:"中国传统手工艺中，绒花的主要原料是？",options:["蚕丝绒", "棉线", "羊毛", "麻线"],answer:0,explanation:"南京绒花以蚕丝绒和铜丝制成，谐音荣华，曾是宫廷和民间喜爱的头饰，现为非遗项目。"},{id:"cs-9160",module:"changshi",prompt:"中国传统木雕中，东阳木雕以什么闻名？",options:["浮雕层次丰富", "圆雕人物", "根雕", "建筑构件"],answer:0,explanation:"浙江东阳木雕以多层次浮雕著称，题材丰富，广泛用于建筑装饰和家具。"},{id:"cs-9161",module:"changshi",prompt:"汽车仪表盘上发动机水温报警灯亮起，正确做法是？",options:["立即停车熄火降温", "继续行驶", "加速到修理厂", "打开暖风降温"],answer:0,explanation:"水温过高可能损坏发动机，应立即靠边停车熄火，待发动机冷却后检查冷却液，切勿立即打开水箱盖。"},{id:"cs-9162",module:"changshi",prompt:"汽车轮胎气压过低会导致什么后果？",options:["油耗增加、轮胎磨损加剧", "转向更轻", "制动更灵", "油耗降低"],answer:0,explanation:"胎压过低使轮胎变形增大、滚动阻力增加，油耗上升且胎侧过热易爆胎，应定期检查胎压。"},{id:"cs-9163",module:"changshi",prompt:"高速公路上发生故障停车，应将警示牌放置在车后多少米？",options:["五十米", "一百五十米", "十米", "三百米"],answer:1,explanation:"高速公路故障停车应开启危险报警闪光灯，并在车后一百五十米外设置三角警示牌，人员撤到护栏外。"},{id:"cs-9164",module:"changshi",prompt:"汽车安全气囊弹出需要配合什么使用才有效？",options:["安全带", "儿童座椅", "头枕", "脚垫"],answer:0,explanation:"安全气囊与安全带配合使用才能有效保护乘员，不系安全带时气囊弹出反而可能造成伤害。"},{id:"cs-9165",module:"changshi",prompt:"汽车发动机机油的主要作用不包括？",options:["润滑", "冷却", "密封", "增加动力"],answer:3,explanation:"机油起润滑、冷却、清洁、密封和防锈作用，不能增加发动机动力，应按周期更换。"},{id:"cs-9166",module:"changshi",prompt:"夜间会车时，正确使用灯光的方法是？",options:["距对向来车一百五十米内改用近光灯", "一直用远光灯", "交替闪远光灯", "关闭所有灯光"],answer:0,explanation:"夜间会车应在距对向来车一百五十米内改用近光灯，避免远光灯使对方眩目引发事故。"},{id:"cs-9167",module:"changshi",prompt:"汽车刹车油一般多久更换一次？",options:["每两年或四万公里", "每月", "每十年", "不需要更换"],answer:0,explanation:"刹车油具有吸水性，含水量超标会降低沸点影响制动性能，一般每两年或四万公里更换。"},{id:"cs-9168",module:"changshi",prompt:"车辆涉水熄火后，正确的做法是？",options:["不要再次启动，等待救援", "立即重新启动", "挂挡推车", "踩油门排水"],answer:0,explanation:"涉水熄火后再次启动可能使水进入气缸造成发动机严重损坏，应保持熄火状态等待救援。"},{id:"cs-9169",module:"changshi",prompt:"汽车轮胎的花纹磨损到什么程度必须更换？",options:["磨损至磨损标记处", "花纹变浅即可", "轮胎变硬", "使用三年"],answer:0,explanation:"轮胎花纹深度低于一点六毫米或磨至磨损标记时，排水和抓地能力显著下降，必须更换。"},{id:"cs-9170",module:"changshi",prompt:"驾驶机动车变道前应首先做什么？",options:["开启转向灯并观察后视镜", "直接变道", "鸣笛示意", "减速停车"],answer:0,explanation:"变道前应提前开启转向灯，观察后视镜和盲区，确认安全后再平稳变道，不得连续变更两条以上车道。"},{id:"cs-9171",module:"changshi",prompt:"汽车蓄电池亏电无法启动，常用的应急方法是？",options:["搭电启动", "推车启动所有车型都适用", "加水", "摇晃车身"],answer:0,explanation:"搭电启动用另一辆车的电池连接正负极辅助启动，注意先接正极后接负极，防止短路。"},{id:"cs-9172",module:"changshi",prompt:"儿童乘车最安全的做法是？",options:["使用儿童安全座椅", "由大人抱坐", "系成人安全带", "坐副驾驶"],answer:0,explanation:"儿童安全座椅能有效保护儿童，成人安全带不适合儿童体型，抱坐无法在碰撞中提供保护。"},{id:"cs-9173",module:"changshi",prompt:"汽车玻璃起雾时，正确的除雾方法是？",options:["开启空调除雾模式或前挡除霜", "用抹布擦", "开窗吹风即可", "喷水"],answer:0,explanation:"空调除雾模式将冷风吹向玻璃，快速消除雾气；冬季可用暖风除霜，行驶中切勿用手擦玻璃。"},{id:"cs-9174",module:"changshi",prompt:"汽车长期停放不用，应采取的措施是？",options:["断开电瓶负极并适当遮盖", "加满机油", "拆掉轮胎", "放空油箱"],answer:0,explanation:"长期停放应断开电瓶负极防止亏电，适当遮盖防尘，定期启动运转，轮胎可适当充气。"},{id:"cs-9175",module:"changshi",prompt:"汽车行驶中爆胎，正确的操作是？",options:["握紧方向盘，缓慢减速并靠边停车", "急刹车", "猛打方向", "立即换胎"],answer:0,explanation:"爆胎时急刹车或猛打方向极易失控侧翻，应握稳方向盘，松油门缓慢减速，待车速降低后靠边停车。"},{id:"cs-9176",module:"changshi",prompt:"汽车防冻液的作用是什么？",options:["冬季防冻、夏季防沸并防腐蚀", "增加动力", "清洁玻璃", "降低噪音"],answer:0,explanation:"防冻液全年使用，冬季防冻、夏季提高沸点，并具有防腐蚀和防垢作用，应定期检查液位。"},{id:"cs-9177",module:"changshi",prompt:"驾驶车辆通过积水路段的正确做法是？",options:["低挡匀速缓慢通过", "高速冲过", "中途停车", "频繁换挡"],answer:0,explanation:"低挡匀速可防止水进入进气道，避免中途停车和换挡，通过后轻踩刹车排出制动器水分。"},{id:"cs-9178",module:"changshi",prompt:"汽车正时皮带一般多少公里更换？",options:["六至十万公里", "一万公里", "二十万公里", "不需要更换"],answer:0,explanation:"正时皮带一般六至十万公里更换，断裂会导致气门损坏，具体周期以车辆说明书为准。"},{id:"cs-9179",module:"changshi",prompt:"汽车尾气中的主要污染物不包括？",options:["一氧化碳", "氮氧化物", "碳氢化合物", "氧气"],answer:3,explanation:"汽车尾气主要含一氧化碳、氮氧化物、碳氢化合物和颗粒物，氧气不是污染物。"},{id:"cs-9180",module:"changshi",prompt:"汽车加油时，油箱盖未关紧可能造成什么问题？",options:["故障灯亮起", "油耗降低", "动力增强", "无影响"],answer:0,explanation:"油箱盖未关紧使燃油系统压力异常，蒸发排放系统检测到泄漏，发动机故障灯会亮起。"},{id:"cs-9181",module:"changshi",prompt:"冬季汽车启动后立即高速行驶的危害是？",options:["发动机磨损加剧", "油耗降低", "动力增强", "无影响"],answer:0,explanation:"冷车时机油尚未充分润滑，应低速行驶待水温上升后再正常驾驶，避免发动机早期磨损。"},{id:"cs-9182",module:"changshi",prompt:"汽车空调滤芯的作用是？",options:["过滤进入车内的空气", "制冷", "除湿", "增加冷媒"],answer:0,explanation:"空调滤芯过滤灰尘、花粉和异味，应定期更换，堵塞会影响出风量和空气质量。"},{id:"cs-9183",module:"changshi",prompt:"车辆年检的主要目的是？",options:["确保车辆安全性能和排放达标", "收取费用", "限制出行", "检查保险"],answer:0,explanation:"年检对车辆制动、灯光、排放等进行检验，确保上路车辆符合安全和环保要求。"},{id:"cs-9184",module:"changshi",prompt:"汽车在冰雪路面行驶，正确的做法是？",options:["安装防滑链或使用雪地胎，缓踩刹车", "急加速", "猛打方向", "高速行驶"],answer:0,explanation:"冰雪路面附着力低，应降低车速、缓踩刹车和油门，必要时使用防滑链或雪地胎。"},{id:"cs-9185",module:"changshi",prompt:"汽车发动机积碳过多的常见原因是？",options:["长期低速短途行驶和劣质燃油", "高速行驶", "定期保养", "使用合格燃油"],answer:0,explanation:"长期短途低速行驶、燃油品质差会使燃烧不充分形成积碳，定期跑高速和清洗可缓解。"},{id:"cs-9186",module:"changshi",prompt:"汽车倒车影像和雷达的作用是？",options:["辅助观察车后盲区", "增加动力", "省油", "装饰"],answer:0,explanation:"倒车影像和雷达帮助驾驶员观察车后障碍物和距离，减少倒车事故，但不能完全替代目视观察。"},{id:"cs-9187",module:"changshi",prompt:"汽车玻璃水冬季应选用什么类型？",options:["防冻型玻璃水", "普通自来水", "肥皂水", "酒精"],answer:0,explanation:"冬季应使用防冻型玻璃水，防止水箱和喷嘴结冰损坏，自来水会结冰且易堵塞喷嘴。"},{id:"cs-9188",module:"changshi",prompt:"驾驶疲劳的表现不包括？",options:["注意力集中", "反应迟钝", "眼皮沉重", "判断力下降"],answer:0,explanation:"疲劳驾驶表现为反应迟钝、注意力涣散、眼皮沉重等，连续驾驶四小时应停车休息二十分钟以上。"},{id:"cs-9189",module:"changshi",prompt:"人民币纸币上的盲文标记位于什么位置？",options:["票面正面右下角", "背面中央", "左上角", "水印处"],answer:0,explanation:"人民币纸币正面右下角有盲文面额标记，方便视障人士识别面额，体现货币的无障碍设计。"},{id:"cs-9190",module:"changshi",prompt:"银行定期存款提前支取，利息如何计算？",options:["按活期利率计算", "按定期利率计算", "不付利息", "按半年利率计算"],answer:0,explanation:"定期存款提前支取的部分按支取日活期利率计息，会损失定期利息，大额资金可考虑分段存期。"},{id:"cs-9191",module:"changshi",prompt:"银行卡密码连续输错多次被锁，正确的处理方式是？",options:["持本人身份证到银行网点办理解锁", "换一张卡", "等待自动解锁", "重新办卡"],answer:0,explanation:"密码锁定后需持本人有效身份证件到银行柜台办理密码重置或解锁，不同银行规则略有差异。"},{id:"cs-9192",module:"changshi",prompt:"中国人民银行的主要职能是什么？",options:["制定和执行货币政策", "吸收公众存款", "发放商业贷款", "销售理财产品"],answer:0,explanation:"中国人民银行是中央银行，负责制定执行货币政策、维护金融稳定和发行人民币，不直接对公众办理存贷款业务。"},{id:"cs-9193",module:"changshi",prompt:"ATM 机取款时吞卡，正确的做法是？",options:["联系银行客服或网点处理", "强行撬机", "离开不管", "换卡再取"],answer:0,explanation:"ATM 吞卡后应保留凭条并联系银行客服或网点，凭身份证领回卡片，切勿离开以防卡片被盗用。"},{id:"cs-9194",module:"changshi",prompt:"人民币的真伪鉴别方法不包括？",options:["看水印", "摸凹凸感", "听声音", "用火烧"],answer:3,explanation:"鉴别人民币可采用看水印和安全线、摸凹凸手感、倾斜观察变色等办法，用火烧属于违法行为。"},{id:"cs-9195",module:"changshi",prompt:"银行存款保险制度的保障额度是每家银行每存款人多少？",options:["五十万元", "十万元", "一百万元", "二十万元"],answer:0,explanation:"我国存款保险制度规定，同一存款人在同一家银行的存款本息合计最高偿付限额为五十万元。"},{id:"cs-9196",module:"changshi",prompt:"信用卡免息期是指什么期间？",options:["从消费日到还款日之间免收利息", "从开卡日算一年", "取现免息期", "分期免息"],answer:0,explanation:"信用卡消费在到期还款日前全额还清可享受免息待遇，取现和分期不享受免息期。"},{id:"cs-9197",module:"changshi",prompt:"手机收到银行验证码，正确的做法是？",options:["绝不告诉任何人", "告诉客服", "告诉亲友", "发到群里"],answer:0,explanation:"银行验证码等同于交易密码，任何索要验证码的行为都可能是诈骗，应立即拒绝并核实。"},{id:"cs-9198",module:"changshi",prompt:"发现银行卡被盗刷，第一时间应该做什么？",options:["立即挂失并报警", "等待账单", "继续消费", "注销手机号"],answer:0,explanation:"发现盗刷应立即致电银行挂失止付、报警并保留证据，及时挂失可最大限度减少损失。"},{id:"cs-9199",module:"changshi",prompt:"定期存款到期后未支取，利息如何处理？",options:["按约定转存或转活期，视银行设置而定", "利息翻倍", "不再计息", "按定期利率无限续存"],answer:0,explanation:"定期到期后若办理了自动转存则按新定期计息，否则本息按活期利率计息，具体以银行约定为准。"},{id:"cs-9200",module:"changshi",prompt:"银行理财产品的风险等级通常分为几级？",options:["五级", "三级", "八级", "两级"],answer:0,explanation:"银行理财风险等级一般分为一至五级，从低到高为谨慎型、稳健型、平衡型、进取型和激进型。"},{id:"cs-9201",module:"changshi",prompt:"人民币纸币损坏到什么程度可以到银行兑换？",options:["票面残缺均可按规定兑换", "完全烧毁", "任意撕毁", "涂鸦即可"],answer:0,explanation:"残缺人民币可按规定兑换，票面剩余四分之三以上且图案文字可辨认的可全额兑换，剩余二分之一以上可半额兑换。"},{id:"cs-9202",module:"changshi",prompt:"银行转账时收款人姓名与账号不一致，会怎样？",options:["转账失败退回", "自动匹配", "转账成功", "冻结账户"],answer:0,explanation:"姓名与账号不一致时转账会失败退回，资金一般原路退回，不会造成损失。"},{id:"cs-9203",module:"changshi",prompt:"大额现金存取款登记制度的主要目的是？",options:["防范洗钱和非法资金流动", "限制消费", "增加税收", "方便统计"],answer:0,explanation:"大额现金管理要求登记资金来源和用途，是反洗钱和反恐怖融资的重要措施。"},{id:"cs-9204",module:"changshi",prompt:"信用卡最低还款额未还清会产生什么后果？",options:["产生利息和违约金，影响征信", "无影响", "卡片自动注销", "降低额度但不罚息"],answer:0,explanation:"未按时足额还款将产生利息和违约金，逾期记录可能上传征信系统，影响后续贷款申请。"},{id:"cs-9205",module:"changshi",prompt:"银行定期存款可以质押贷款吗？",options:["可以", "不可以", "视金额而定", "仅限外币"],answer:0,explanation:"定期存款可办理质押贷款，一般可贷存款金额的九成左右，避免提前支取损失利息。"},{id:"cs-9206",module:"changshi",prompt:"网上银行转账时，收款人信息核对的重点是？",options:["姓名、账号和开户行", "备注", "金额", "时间"],answer:0,explanation:"转账前应核对收款人姓名、账号和开户行信息，信息错误会导致转账失败或资金误转。"},{id:"cs-9207",module:"changshi",prompt:"人民币的主要防伪特征之一光变镂空开窗安全线位于？",options:["票面正面偏右", "背面左下角", "水印处", "号码处"],answer:0,explanation:"二零一五年版百元人民币的光变镂空开窗安全线随观察角度变色，是重要防伪特征。"},{id:"cs-9208",module:"changshi",prompt:"银行卡挂失后原卡的状态是？",options:["立即失效", "继续可用", "限额使用", "自动注销"],answer:0,explanation:"挂失后原卡立即失效，防止资金损失，补办新卡后原卡作废。"},{id:"cs-9209",module:"changshi",prompt:"银行柜台办理业务需要出示的有效证件是？",options:["本人身份证", "工作证", "学生证", "医保卡"],answer:0,explanation:"银行办理开户、大额存取等业务需出示本人有效身份证件，代办还需代理人证件和授权。"},{id:"cs-9210",module:"changshi",prompt:"零存整取储蓄方式的特点是？",options:["每月固定存入，到期一次支取本息", "一次存入分期支取", "随时存取", "利息最高"],answer:0,explanation:"零存整取适合每月有固定结余的人群，按月存入固定金额，到期一次性支取本息。"},{id:"cs-9211",module:"changshi",prompt:"银行卡磁条信息损坏后，正确的处理方式是？",options:["到银行网点换卡", "用胶带修补", "继续使用", "自行消磁"],answer:0,explanation:"磁条损坏或消磁后卡片无法正常使用，应携带身份证到银行网点办理换卡。"},{id:"cs-9212",module:"changshi",prompt:"银行存款利率上调后，已存入的定期存款利率会怎样？",options:["维持原利率不变", "自动上调", "按新利率计算", "作废"],answer:0,explanation:"定期存款在存期内利率固定，利率调整不影响已存入的定期存款，到期续存时按新利率执行。"},{id:"cs-9213",module:"changshi",prompt:"接到自称银行的电话要求提供密码，正确的做法是？",options:["拒绝并拨打银行官方客服核实", "提供密码", "提供验证码", "按对方要求操作"],answer:0,explanation:"银行工作人员不会索要密码和验证码，接到此类电话应挂断并拨打官方客服核实，谨防诈骗。"},{id:"cs-9214",module:"changshi",prompt:"银行汇款到账时间通常受什么影响？",options:["收款银行和转账渠道", "天气", "汇率", "节假日无影响"],answer:0,explanation:"跨行转账到账时间与收款银行、转账渠道有关，实时到账、普通到账和次日到账的时效不同。"},{id:"cs-9215",module:"changshi",prompt:"人民币硬币的主要材质不包括？",options:["纸质", "钢芯镀镍", "铜合金", "铝合金"],answer:0,explanation:"我国流通硬币采用钢芯镀镍、铜合金、铝合金等金属材质，纸质用于纸币。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9216",module:"changshi",prompt:"西班牙奔牛节在哪个城市举行？",options:["潘普洛纳", "马德里", "巴塞罗那", "塞维利亚"],answer:0,explanation:"圣费尔明节俗称奔牛节，每年七月在西班牙潘普洛纳举行，人们与公牛沿街道奔跑。"},{id:"cs-9217",module:"changshi",prompt:"巴西狂欢节最著名的举办城市是？",options:["里约热内卢", "圣保罗", "萨尔瓦多", "巴西利亚"],answer:0,explanation:"里约热内卢狂欢节以桑巴舞大游行闻名，每年吸引数百万游客，被称为世界上最大的狂欢节。"},{id:"cs-9218",module:"changshi",prompt:"印度洒红节人们互相抛洒什么？",options:["彩色粉末", "花瓣", "水球", "米粒"],answer:0,explanation:"洒红节又称胡里节，人们互抛彩粉和彩水庆祝春天到来，象征正义战胜邪恶。"},{id:"cs-9219",module:"changshi",prompt:"泰国宋干节俗称什么节？",options:["泼水节", "水灯节", "大象节", "素食节"],answer:0,explanation:"宋干节是泰国新年，每年四月十三至十五日举行，人们互相泼水祝福，寓意洗去不顺。"},{id:"cs-9220",module:"changshi",prompt:"德国慕尼黑啤酒节通常在什么季节举行？",options:["秋季", "春季", "夏季", "冬季"],answer:0,explanation:"慕尼黑啤酒节始于1810年，每年九月末至十月初举行，是世界最大的民间节日之一。"},{id:"cs-9221",module:"changshi",prompt:"墨西哥亡灵节人们用什么装饰祭坛？",options:["万寿菊", "玫瑰", "百合", "向日葵"],answer:0,explanation:"墨西哥亡灵节用万寿菊、糖骷髅和照片布置祭坛迎接逝去亲人，二零零八年列入人类非遗。"},{id:"cs-9222",module:"changshi",prompt:"日本樱花节期间人们常进行什么活动？",options:["赏花聚会", "龙舟比赛", "烟花大会", "庙会"],answer:0,explanation:"日本人在樱花盛开时到公园赏花野餐，称为花见，是日本春季最重要的民俗活动之一。"},{id:"cs-9223",module:"changshi",prompt:"美国感恩节的传统主菜是什么？",options:["烤火鸡", "烤鹅", "火腿", "牛排"],answer:0,explanation:"感恩节定于十一月第四个星期四，家人团聚吃烤火鸡、南瓜派，感谢一年的收获。"},{id:"cs-9224",module:"changshi",prompt:"苏格兰新年除夕人们演唱的传统歌曲是？",options:["友谊地久天长", "欢乐颂", "平安夜", "生日歌"],answer:0,explanation:"苏格兰诗人彭斯填词的友谊地久天长是全球跨年之夜传唱最广的歌曲之一。"},{id:"cs-9225",module:"changshi",prompt:"意大利威尼斯狂欢节最具特色的面具是？",options:["半脸装饰面具", "全脸黑面具", "木面具", "纸糊面具"],answer:0,explanation:"威尼斯狂欢节以华丽面具和古典服饰著称，半脸面具缀满装饰，是城市的象征之一。"},{id:"cs-9226",module:"changshi",prompt:"日本七夕节人们把愿望写在什么上面？",options:["短册纸条", "灯笼", "木牌", "风筝"],answer:0,explanation:"日本七夕人们将愿望写在彩色短册上挂在竹枝上，源于中国乞巧节习俗。"},{id:"cs-9227",module:"changshi",prompt:"英国国庆性质的活动女王官方生日阅兵称为？",options:["皇家军队阅兵仪式", "白金汉宫开放日", "圣乔治日", "盖伊福克斯之夜"],answer:0,explanation:"英国以君主官方生日举行皇家军队阅兵仪式作为国庆活动，通常在六月举行。"},{id:"cs-9228",module:"changshi",prompt:"俄罗斯谢肉节又称送冬节，人们吃什么传统食物？",options:["薄煎饼", "红菜汤", "饺子", "面包"],answer:0,explanation:"谢肉节是俄罗斯送冬迎春的节日，圆形薄煎饼象征太阳，人们连吃一周并焚烧稻草人。"},{id:"cs-9229",module:"changshi",prompt:"万圣节前夜孩子们挨家挨户说的一句话是？",options:["不给糖就捣蛋", "新年快乐", "圣诞快乐", "复活节快乐"],answer:0,explanation:"万圣节前夜十月三十一日，孩子们装扮成鬼怪挨家讨糖，不给糖就捣蛋是经典习俗。"},{id:"cs-9230",module:"changshi",prompt:"澳大利亚国庆日纪念的是什么事件？",options:["第一舰队抵达悉尼", "独立战争", "联邦成立", "发现新大陆"],answer:0,explanation:"一月二十六日是澳大利亚国庆日，纪念一七八八年第一舰队抵达悉尼湾建立殖民地。"},{id:"cs-9231",module:"changshi",prompt:"日本成人节定在哪一天？",options:["一月第二个星期一", "一月一日", "三月三日", "五月五日"],answer:0,explanation:"日本成人节定于一月第二个星期一，年满二十岁的青年穿和服参加庆祝仪式。"},{id:"cs-9232",module:"changshi",prompt:"西班牙番茄节在哪个小镇举行？",options:["布尼奥尔", "托莱多", "格拉纳达", "瓦伦西亚"],answer:0,explanation:"布尼奥尔番茄节每年八月举行，人们互相投掷番茄，是西班牙著名的狂欢活动。"},{id:"cs-9233",module:"changshi",prompt:"越南的春节与中国春节的相同点是？",options:["都过农历新年", "都吃饺子", "都放鞭炮", "都舞龙"],answer:0,explanation:"越南受中华文化影响也过农历新年，贴春联、拜年，但饮食习俗有本地特色。"},{id:"cs-9234",module:"changshi",prompt:"挪威奥斯陆诺贝尔和平奖颁奖仪式在每年什么时间举行？",options:["十二月十日", "十月十日", "一月一日", "六月十日"],answer:0,explanation:"诺贝尔和平奖于每年十二月十日即诺贝尔逝世纪念日在奥斯陆颁发，其他奖项在斯德哥尔摩颁发。"},{id:"cs-9235",module:"changshi",prompt:"中国泼水节是哪个民族的节日？",options:["傣族", "藏族", "蒙古族", "回族"],answer:0,explanation:"傣族泼水节在农历四月中旬，人们互相泼水祝福，与泰国宋干节同源。"},{id:"cs-9236",module:"changshi",prompt:"爱尔兰圣帕特里克节的代表颜色是？",options:["绿色", "红色", "蓝色", "黄色"],answer:0,explanation:"圣帕特里克节是爱尔兰传统节日，三月十七日人们穿绿色服装、戴三叶草庆祝。"},{id:"cs-9237",module:"changshi",prompt:"日本盂兰盆节人们进行什么活动迎接祖先灵魂？",options:["跳盆舞、点灯笼", "放风筝", "赛龙舟", "赏月"],answer:0,explanation:"盂兰盆节在八月中旬，人们点迎魂火、跳盆舞迎接祖先灵魂，类似中国中元节。"},{id:"cs-9238",module:"changshi",prompt:"加拿大国庆日是哪一天？",options:["七月一日", "七月四日", "六月一日", "八月一日"],answer:0,explanation:"七月一日是加拿大国庆日，纪念一八六七年加拿大联邦成立。"},{id:"cs-9239",module:"changshi",prompt:"印度排灯节的象征意义是？",options:["光明战胜黑暗", "丰收", "新年", "团圆"],answer:0,explanation:"排灯节是印度最重要的节日，人们点燃油灯庆祝光明战胜黑暗、善良战胜邪恶。"},{id:"cs-9240",module:"changshi",prompt:"西班牙法雅节人们焚烧什么？",options:["法雅人偶", "稻草人", "篝火堆", "纸灯笼"],answer:0,explanation:"瓦伦西亚法雅节在三月举行，人们焚烧精心制作的法雅人偶迎接春天，纪念圣约瑟夫。"},{id:"cs-9241",module:"changshi",prompt:"蒙古族那达慕大会的三项竞技是？",options:["摔跤、赛马、射箭", "赛马、拔河、摔跤", "射箭、马球、赛马", "摔跤、赛马、马术"],answer:0,explanation:"那达慕是蒙古族传统盛会，男儿三艺为摔跤、赛马和射箭，体现草原文化特色。"},{id:"cs-9242",module:"changshi",prompt:"英国盖伊福克斯之夜人们点燃篝火纪念什么事件？",options:["火药阴谋被粉碎", "工业革命", "王室加冕", "独立战争"],answer:0,explanation:"十一月五日盖伊福克斯之夜纪念一六零五年火药阴谋被挫败，人们燃放烟花焚烧假人。"},{id:"cs-9243",module:"changshi",prompt:"藏族雪顿节的主要活动包括晒佛和什么？",options:["藏戏表演", "赛马", "射箭", "拔河"],answer:0,explanation:"雪顿节意为酸奶宴，拉萨哲蚌寺晒大佛和藏戏演出是主要活动，又称藏戏节。"},{id:"cs-9244",module:"changshi",prompt:"绿茶的基本工艺特点是什么？",options:["不经发酵，杀青后干燥", "全发酵", "半发酵", "后发酵"],answer:0,explanation:"绿茶通过杀青钝化酶活性，不经发酵，保留茶叶的天然绿色和清香味，如龙井、碧螺春。"},{id:"cs-9245",module:"changshi",prompt:"乌龙茶的制作工艺关键步骤是？",options:["做青即摇青与晾青", "渥堆", "杀青前不揉捻", "熏花"],answer:0,explanation:"乌龙茶属半发酵茶，做青使叶缘碰撞氧化形成绿叶红镶边的特色，如铁观音、大红袍。"},{id:"cs-9246",module:"changshi",prompt:"冲泡龙井茶适宜的水温是多少？",options:["八十至八十五度", "一百度", "六十度", "七十度"],answer:0,explanation:"龙井等细嫩绿茶宜用八十至八十五度水冲泡，水温过高会烫熟茶叶，产生苦涩味。"},{id:"cs-9247",module:"changshi",prompt:"中国茶叶按发酵程度分为六大类，不包括？",options:["花茶", "绿茶", "黄茶", "黑茶"],answer:0,explanation:"六大茶类为绿茶、白茶、黄茶、青茶即乌龙茶、红茶和黑茶，花茶属再加工茶。"},{id:"cs-9248",module:"changshi",prompt:"功夫茶冲泡主要流行于哪个地区？",options:["潮汕和闽南", "江南", "四川", "西藏"],answer:0,explanation:"潮汕功夫茶讲究小壶小杯、高冲低斟，是潮汕和闽南地区待客的传统茶俗。"},{id:"cs-9249",module:"changshi",prompt:"白毫银针属于哪类茶？",options:["白茶", "绿茶", "黄茶", "青茶"],answer:0,explanation:"白毫银针以福鼎大白茶单芽制成，不炒不揉，满披白毫，是白茶中的珍品。"},{id:"cs-9250",module:"changshi",prompt:"茶马古道主要运输什么商品？",options:["茶叶和马匹", "丝绸", "瓷器", "盐"],answer:0,explanation:"茶马古道是唐宋以来内地与西藏、云南等地以茶易马的贸易通道，连接川滇藏。"},{id:"cs-9251",module:"changshi",prompt:"中国茶圣陆羽所著的茶学著作是？",options:["茶经", "茶录", "大观茶论", "茶谱"],answer:0,explanation:"唐代陆羽著茶经，系统论述茶的种植、采制和烹饮，是世界上第一部茶学专著。"},{id:"cs-9252",module:"changshi",prompt:"红茶的英文说法源于哪种茶？",options:["正山小种", "祁门红茶", "滇红", "英德红茶"],answer:0,explanation:"红茶英文直译为黑茶，源于武夷山正山小种最早出口欧洲，其干茶乌黑而得名。"},{id:"cs-9253",module:"changshi",prompt:"白酒的香型中，酱香型代表酒是？",options:["茅台酒", "泸州老窖", "汾酒", "桂林三花酒"],answer:0,explanation:"酱香型白酒以贵州茅台为代表，香气幽雅细腻；泸州老窖属浓香型，汾酒属清香型。"},{id:"cs-9254",module:"changshi",prompt:"中国最古老的酒种之一，以糯米酿造的酒是？",options:["黄酒", "白酒", "啤酒", "果酒"],answer:0,explanation:"黄酒以糯米等谷物酿造，酒精度较低，绍兴黄酒最为著名，有三千多年历史。"},{id:"cs-9255",module:"changshi",prompt:"葡萄酒酿造中，红葡萄酒的颜色来自？",options:["葡萄皮", "葡萄籽", "果肉", "橡木桶"],answer:0,explanation:"红葡萄酒带皮发酵，花青素等色素从皮中溶出，白葡萄酒则去皮发酵。"},{id:"cs-9256",module:"changshi",prompt:"啤酒酿造的主要原料是？",options:["大麦芽、啤酒花、水和酵母", "大米", "小麦", "玉米"],answer:0,explanation:"啤酒以大麦芽为主料，啤酒花赋予苦味和香气，酵母发酵糖分产生酒精和二氧化碳。"},{id:"cs-9257",module:"changshi",prompt:"饮酒后不宜立即进行的活动是？",options:["驾驶机动车", "散步", "喝水", "休息"],answer:0,explanation:"饮酒后酒精影响反应和判断力，血液酒精含量超标即属酒驾，切勿驾驶任何机动车。"},{id:"cs-9258",module:"changshi",prompt:"藏族的青稞酒属于什么类型的酒？",options:["发酵酒", "蒸馏酒", "配制酒", "果酒"],answer:0,explanation:"青稞酒以青稞发酵酿制，酒精度低，是藏族节庆待客的传统饮品。"},{id:"cs-9259",module:"changshi",prompt:"绍兴黄酒中的加饭酒属于什么类型？",options:["半干型黄酒", "干型", "甜型", "半甜型"],answer:0,explanation:"加饭酒在酿造时增加糯米投入量，糖分略高，属半干型，酒质醇厚，是绍兴酒的代表。"},{id:"cs-9260",module:"changshi",prompt:"品茶时闻香杯主要用于什么茶？",options:["乌龙茶", "绿茶", "红茶", "白茶"],answer:0,explanation:"闻香杯用于乌龙茶功夫茶泡法，先闻杯中留香再品茶汤，增添品饮乐趣。"},{id:"cs-9261",module:"changshi",prompt:"茶具中的公道杯作用是？",options:["均匀茶汤浓度", "加热茶水", "过滤茶渣", "保温"],answer:0,explanation:"公道杯将茶汤集中后分杯，使每杯茶汤浓度一致，体现待客公平。"},{id:"cs-9262",module:"changshi",prompt:"适量饮茶的健康益处主要是？",options:["茶多酚具有抗氧化作用", "补充蛋白质", "增加脂肪", "提供酒精"],answer:0,explanation:"茶叶中的茶多酚和儿茶素具有抗氧化作用，适量饮茶有益健康，但不宜空腹浓茶。"},{id:"cs-9263",module:"changshi",prompt:"中国白酒的度数一般指什么含量？",options:["酒精体积百分比", "糖分", "水分", "酸度"],answer:0,explanation:"白酒度数指酒精在酒液中的体积百分比，如五十二度表示酒精占百分之五十二。"},{id:"cs-9264",module:"changshi",prompt:"冷泡茶适合用哪类茶叶？",options:["绿茶或乌龙茶", "黑茶", "普洱熟茶", "红茶砖"],answer:0,explanation:"冷泡适合香气高、滋味鲜爽的绿茶和乌龙茶，低温浸泡减少苦涩，口感清甜。"},{id:"cs-9265",module:"changshi",prompt:"酒曲在酿酒中的作用是？",options:["提供糖化和发酵的微生物", "增加颜色", "防腐", "调香"],answer:0,explanation:"酒曲含霉菌和酵母，将淀粉糖化并发酵成酒精，是中国传统酿酒的核心技术。"},{id:"cs-9266",module:"changshi",prompt:"茶艺中温杯烫盏的目的是？",options:["清洁茶具并提高杯温利于茶香", "消毒", "装饰", "降温"],answer:0,explanation:"温杯使茶具达到适宜温度，利于茶叶香气挥发，同时清洁茶具，是茶艺的基本礼仪。"},{id:"cs-9267",module:"changshi",prompt:"日本茶道源于中国哪个时期的茶文化？",options:["宋代", "唐代", "明代", "清代"],answer:0,explanation:"日本茶道源于宋代点茶法，经荣西禅师传入日本，逐渐发展为独特的茶道艺术。"},{id:"cs-9268",module:"changshi",prompt:"适量饮酒的健康建议是？",options:["成年男性每日酒精摄入不超过二十五克", "越多越好", "空腹饮酒", "混饮多种酒"],answer:0,explanation:"过量饮酒损害肝脏和神经系统，建议成年男性每日酒精摄入不超过二十五克，女性更少。"},{id:"cs-9269",module:"changshi",prompt:"茶树原产于中国的哪个地区？",options:["西南地区", "东北地区", "华北平原", "西北地区"],answer:0,explanation:"茶树原产于中国西南地区，云南等地至今有野生古茶树，中国是世界茶文化的发源地。"},{id:"cs-9270",module:"changshi",prompt:"葡萄酒开瓶后未饮完，正确的保存方法是？",options:["塞紧瓶塞冷藏并尽快饮用", "常温敞口存放", "加热保存", "冷冻"],answer:0,explanation:"开瓶后葡萄酒接触空气易氧化，应塞紧瓶塞直立冷藏，三至五天内饮完为佳。"},{id:"cs-9271",module:"changshi",prompt:"高原旅行预防高原反应的正确做法是？",options:["逐步升高海拔并充分休息", "快速登顶", "剧烈运动", "饮酒助眠"],answer:0,explanation:"高原反应因缺氧引起，应阶梯式上升海拔、避免剧烈运动和饮酒，症状严重时吸氧或下撤。"},{id:"cs-9272",module:"changshi",prompt:"野外徒步迷路时，正确的做法是？",options:["原地等待救援并保存体力", "盲目穿越丛林", "沿溪流快速下行", "大声呼喊直到力竭"],answer:0,explanation:"迷路时应停止盲目移动，寻找安全地点、保存体力和手机电量，发出求救信号等待救援。"},{id:"cs-9273",module:"changshi",prompt:"登山时遇到雷雨天气，正确的避险方式是？",options:["远离山顶和大树，蹲低身体", "躲在大树下", "站在开阔高地", "继续攀登"],answer:0,explanation:"雷雨时应远离制高点和孤立大树，双脚并拢蹲低，减少跨步电压伤害，尽快下撤。"},{id:"cs-9274",module:"changshi",prompt:"野外露营时帐篷应选择什么地点？",options:["地势较高、排水良好、远离河道", "河滩低地", "悬崖下方", "风口"],answer:0,explanation:"露营应选地势较高、平坦排水好的地点，避开河道、悬崖下和风口，防止山洪和落石。"},{id:"cs-9275",module:"changshi",prompt:"旅行中预防腹泻的关键措施是？",options:["饮用瓶装水或烧开的水，不吃生冷食物", "多吃路边摊", "喝生水", "吃未洗净水果"],answer:0,explanation:"旅行者腹泻多由饮食不洁引起，应饮用安全水源、食物充分加热，注意手部卫生。"},{id:"cs-9276",module:"changshi",prompt:"海边游泳遇到离岸流，正确的逃生方法是？",options:["平行于海岸游出流区再回岸", "逆流直游回岸", "原地挣扎", "潜水"],answer:0,explanation:"离岸流流速快，逆流游极易力竭，应保持冷静，平行海岸游出流区后再游回岸边。"},{id:"cs-9277",module:"changshi",prompt:"乘坐长途飞机预防下肢深静脉血栓的方法是？",options:["定时活动脚踝并起身走动", "久坐不动", "穿过紧的裤子", "大量饮酒"],answer:0,explanation:"长途飞行久坐增加血栓风险，应定时活动脚踝、起身走动、穿宽松衣物并适量饮水。"},{id:"cs-9278",module:"changshi",prompt:"野外被蛇咬伤后，正确的处理方式是？",options:["保持冷静，限制活动，尽快就医", "用嘴吸出毒液", "奔跑求救", "用绳勒紧伤口上方不放松"],answer:0,explanation:"被蛇咬后应保持冷静减少毒液扩散，记住蛇的特征，用宽布条适度绑扎并尽快就医，切勿用嘴吸毒。"},{id:"cs-9279",module:"changshi",prompt:"旅行证件丢失后的第一件事是？",options:["到当地警方报案并联系使领馆或驻外机构", "继续行程", "购买新票", "不管它"],answer:0,explanation:"护照丢失应到当地警方报案取得证明，再联系中国驻外使领馆申请补办旅行证件。"},{id:"cs-9280",module:"changshi",prompt:"沙漠徒步中暑的预防措施是？",options:["避开正午高温、遮阳并补充水和盐", "穿深色衣服", "不喝水", "正午赶路"],answer:0,explanation:"沙漠徒步应避开正午高温时段，穿浅色透气衣物，遮阳并少量多次补充水和电解质。"},{id:"cs-9281",module:"changshi",prompt:"自驾游出发前对车辆的必要检查不包括？",options:["检查轮胎和刹车", "检查机油和冷却液", "检查灯光", "更换内饰"],answer:3,explanation:"长途自驾前应检查轮胎、刹车、机油、冷却液、灯光等，确保车辆处于良好状态。"},{id:"cs-9282",module:"changshi",prompt:"野外求生中获取饮用水的安全方法是？",options:["煮沸或使用净水片", "直接喝溪水", "喝雨水不处理", "喝露水"],answer:0,explanation:"野外水源可能含病原体，应煮沸一分钟以上或使用净水片、滤水器，避免直接饮用。"},{id:"cs-9283",module:"changshi",prompt:"乘坐邮轮旅行时晕船的处理方法是？",options:["服用晕船药并待在船舱中部低层", "站在船头", "闭眼硬扛", "大量进食"],answer:0,explanation:"晕船可提前服用晕船药，选择船体中部低层、视线看向远处地平线，减少眩晕。"},{id:"cs-9284",module:"changshi",prompt:"境外旅行购买旅游保险的主要作用是？",options:["覆盖医疗和紧急救援费用", "保证不生病", "代替签证", "增加行程"],answer:0,explanation:"境外医疗费用高昂，旅游保险可覆盖意外医疗、紧急救援和行李损失等风险。"},{id:"cs-9285",module:"changshi",prompt:"山区徒步防止失温的关键是？",options:["保持干燥并分层穿衣", "穿棉质衣物", "大量出汗", "迎风休息"],answer:0,explanation:"失温因热量流失过快引起，应穿排汗内层加保暖外层，保持干燥，及时补充热量。"},{id:"cs-9286",module:"changshi",prompt:"旅行中财物保管的正确做法是？",options:["分散存放，重要证件复印备份", "全部放一个包", "随身大量现金", "随意放置酒店房间"],answer:0,explanation:"财物应分散存放，护照和证件复印备份，使用酒店保险箱，避免在公共场所显露贵重物品。"},{id:"cs-9287",module:"changshi",prompt:"户外活动被蚊虫叮咬后红肿严重，应如何处理？",options:["清洁患处并冷敷，必要时就医", "抓挠", "热敷", "涂牙膏"],answer:0,explanation:"叮咬后应清洁患处、冷敷止痒，出现严重过敏反应如呼吸困难需立即就医。"},{id:"cs-9288",module:"changshi",prompt:"潜水时最重要的安全原则是？",options:["绝不憋气上升", "深潜", "快速上升", "单独行动"],answer:0,explanation:"潜水上升时憋气会导致肺气压伤，应保持呼吸并缓慢上升，遵守潜伴制度。"},{id:"cs-9289",module:"changshi",prompt:"旅行中出现水土不服的应对方法是？",options:["饮食清淡、规律作息并逐步适应", "立即吃辛辣食物", "暴饮暴食", "熬夜"],answer:0,explanation:"水土不服多因气候和饮食变化引起，应饮食清淡、规律作息，症状严重时就医。"},{id:"cs-9290",module:"changshi",prompt:"野外遇到熊等大型野生动物，正确的做法是？",options:["保持距离缓慢后退，不奔跑不直视", "大声尖叫", "投喂食物", "快速逃跑"],answer:0,explanation:"遇到熊应保持冷静，缓慢后退拉开距离，不奔跑不直视眼睛，必要时使用防熊喷雾。"},{id:"cs-9291",module:"changshi",prompt:"滑雪时最重要的防护装备是？",options:["头盔和护目镜", "手套", "围巾", "耳机"],answer:0,explanation:"头盔保护头部免受撞击，护目镜防紫外线和风雪，是滑雪必备的防护装备。"},{id:"cs-9292",module:"changshi",prompt:"旅行前查看目的地安全信息的主要渠道是？",options:["外交部领事保护中心和官方旅游警示", "社交媒体传言", "陌生网友", "随机判断"],answer:0,explanation:"出行前应通过外交部领事保护中心等官方渠道了解目的地安全形势和入境要求。"},{id:"cs-9293",module:"changshi",prompt:"户外徒步中水壶冻住，预防方法是？",options:["水壶倒置或贴身存放", "装满水", "放在帐篷外", "用玻璃瓶"],answer:0,explanation:"低温下水从瓶口开始结冰，水壶倒置或贴身存放可防止瓶口冻结，保证饮水。"},{id:"cs-9294",module:"changshi",prompt:"旅行中食物中毒的初步处理是？",options:["停止进食、补充水分并就医", "继续进食", "剧烈运动", "大量饮酒"],answer:0,explanation:"食物中毒应立即停止进食可疑食物，补充水分防止脱水，症状严重如呕吐不止需及时就医。"},{id:"cs-9295",module:"changshi",prompt:"乘坐热气球观光的安全注意事项是？",options:["听从飞行员指挥，不擅自移动", "随意走动", "攀爬吊篮", "携带重物"],answer:0,explanation:"热气球飞行应听从飞行员指挥，站稳吊篮内不攀爬不移动，确保重心稳定和飞行安全。"},{id:"cs-9296",module:"changshi",prompt:"户外活动防晒的正确做法是？",options:["涂抹防晒霜并戴帽子和太阳镜", "只涂一次", "阴天不防晒", "穿深色紧身衣"],answer:0,explanation:"户外应每两小时补涂防晒霜，配合帽子、太阳镜和遮阳衣物，阴天紫外线仍可伤害皮肤。"},{id:"cs-9297",module:"changshi",prompt:"旅行中遇到地震，在酒店内的正确做法是？",options:["躲到坚固家具旁或墙角，远离玻璃", "乘电梯逃生", "跳窗", "站在窗边"],answer:0,explanation:"地震时应就近躲避在坚固家具旁或承重墙角，远离玻璃和悬挂物，震后有序撤离，切勿乘电梯。"},{id:"cs-9298",module:"changshi",prompt:"野外生火的安全原则是？",options:["清理周围可燃物并确保火源完全熄灭", "在帐篷内生火", "大风天生火", "离开不管"],answer:0,explanation:"野外生火应远离帐篷和可燃物，用石块围住，离开前用水浇灭并确认无火星，防止山火。"},{id:"cs-9299",module:"changshi",prompt:"照片的景深由光圈、焦距和什么共同决定？",options:["对焦距离", "快门速度", "感光度", "白平衡"],answer:0,explanation:"景深由光圈、镜头焦距和对焦距离共同决定，光圈越大、焦距越长、对焦越近，景深越浅。"},{id:"cs-9300",module:"changshi",prompt:"相机曝光三要素不包括？",options:["白平衡", "光圈", "快门速度", "感光度"],answer:0,explanation:"曝光三要素为光圈、快门速度和感光度，白平衡影响色彩还原而非曝光量。"},{id:"cs-9301",module:"changshi",prompt:"大光圈拍摄人像的主要效果是？",options:["背景虚化突出主体", "增加景深", "提高快门", "降低噪点"],answer:0,explanation:"大光圈产生浅景深，使背景虚化、主体突出，是人像摄影的常用手法。"},{id:"cs-9302",module:"changshi",prompt:"拍摄运动物体时，应优先调整的参数是？",options:["快门速度", "光圈", "白平衡", "色温"],answer:0,explanation:"高速快门能凝固运动瞬间，拍摄运动物体应优先保证快门速度足够快。"},{id:"cs-9303",module:"changshi",prompt:"感光度ISO过高会导致照片出现什么问题？",options:["噪点增多", "色彩更鲜艳", "更清晰", "曝光更准"],answer:0,explanation:"ISO越高感光元件对信号放大越强，噪点越明显，画质下降，应尽量使用低ISO。"},{id:"cs-9304",module:"changshi",prompt:"黄金时刻是指一天中什么时段？",options:["日出后和日落前一小时内", "正午", "深夜", "上午十点"],answer:0,explanation:"黄金时刻阳光柔和、色温暖、影子长，是风光和人像摄影的最佳光线时段。"},{id:"cs-9305",module:"changshi",prompt:"微距摄影主要用于拍摄什么？",options:["细小物体的特写", "远景", "建筑", "星空"],answer:0,explanation:"微距摄影以高放大倍率拍摄花朵、昆虫等细小物体，展现肉眼不易察觉的细节。"},{id:"cs-9306",module:"changshi",prompt:"手机夜景模式提高画质的原理是？",options:["多帧合成降噪", "增大光圈", "更换镜头", "提高色温"],answer:0,explanation:"夜景模式通过连续拍摄多张不同曝光的照片并合成，降低噪点、提升暗部细节。"},{id:"cs-9307",module:"changshi",prompt:"拍摄逆光人像时，为使面部曝光正常应？",options:["增加曝光补偿或使用反光板补光", "减少曝光", "关闭闪光灯", "降低ISO"],answer:0,explanation:"逆光下面部背光偏暗，应增加曝光补偿或用反光板、闪光灯补光，平衡明暗。"},{id:"cs-9308",module:"changshi",prompt:"RAW格式相比JPEG格式的优势是？",options:["保留更多原始信息，后期调整空间大", "文件更小", "直接可分享", "色彩鲜艳"],answer:0,explanation:"RAW记录传感器原始数据，动态范围大，后期调整白平衡和曝光不易损失画质。"},{id:"cs-9309",module:"changshi",prompt:"拍摄星空时，为避免星星拖尾，快门速度一般不超过？",options:["三十秒", "一分钟", "五秒", "两分钟"],answer:0,explanation:"地球自转使长时间曝光产生星轨，拍摄清晰星点一般快门不超过三十秒，常用五百法则估算。"},{id:"cs-9310",module:"changshi",prompt:"三脚架在摄影中的主要作用是？",options:["稳定相机，支持长曝光", "变焦", "对焦", "测光"],answer:0,explanation:"三脚架提供稳定支撑，是夜景、长曝光和微距摄影的必备工具，可避免手抖模糊。"},{id:"cs-9311",module:"changshi",prompt:"构图中的三分法是指什么？",options:["将主体放在画面三分之一交点处", "三等分色彩", "三次曝光", "三个主体"],answer:0,explanation:"三分法将画面横竖各分为三等份，主体置于交点或线上，使构图更均衡自然。"},{id:"cs-9312",module:"changshi",prompt:"快门优先模式适合拍摄什么题材？",options:["运动或流水等对速度敏感的场景", "静态风景", "静物", "建筑"],answer:0,explanation:"快门优先由用户设定快门速度，相机自动匹配光圈，适合运动、流水等动态场景。"},{id:"cs-9313",module:"changshi",prompt:"镜头防抖功能的作用是？",options:["减少手抖造成的模糊", "自动对焦", "变焦", "改变色温"],answer:0,explanation:"防抖通过移动镜片或传感器补偿手抖，允许更慢的快门速度，但不能凝固高速运动。"},{id:"cs-9314",module:"changshi",prompt:"摄影中高调照片的特点是？",options:["以明亮色调为主，画面简洁", "以暗部为主", "色彩鲜艳", "对比强烈"],answer:0,explanation:"高调照片以白色和浅色调为主，光线柔和，给人明快简洁的感觉，常用于儿童和静物。"},{id:"cs-9315",module:"changshi",prompt:"手机人像模式虚化背景的原理是？",options:["算法模拟景深效果", "物理大光圈", "光学变焦", "长焦镜头"],answer:0,explanation:"手机人像模式通过双摄测距或算法识别主体，对背景进行模糊处理，模拟大光圈效果。"},{id:"cs-9316",module:"changshi",prompt:"拍摄流水丝绢效果应使用什么设置？",options:["慢速快门配合三脚架", "高速快门", "大光圈", "高ISO"],answer:0,explanation:"慢速快门使水流模糊成丝绢状，需配合三脚架和减光镜，是风光摄影的常用手法。"},{id:"cs-9317",module:"changshi",prompt:"摄影中剪影照片的拍摄要点是？",options:["逆光下对亮部测光，主体呈黑色轮廓", "顺光拍摄", "使用闪光灯", "提高ISO"],answer:0,explanation:"剪影利用逆光使主体呈现黑色轮廓，需对背景亮部测光，突出形态和线条美。"},{id:"cs-9318",module:"changshi",prompt:"视频拍摄的帧率二十五fps表示什么？",options:["每秒二十五帧画面", "二十五倍变焦", "二十五秒时长", "二十五兆像素"],answer:0,explanation:"帧率指每秒记录的画面帧数，二十五fps是常见视频标准，帧率越高画面越流畅。"},{id:"cs-9319",module:"changshi",prompt:"摄影中色温的单位是？",options:["开尔文", "流明", "勒克斯", "坎德拉"],answer:0,explanation:"色温以开尔文为单位，日光约五千五百开，钨丝灯约三千二百开，色温影响画面冷暖。"},{id:"cs-9320",module:"changshi",prompt:"长焦镜头的主要特点是？",options:["视角窄，可拉近远处物体", "视角广", "景深大", "畸变大"],answer:0,explanation:"长焦镜头焦距长、视角窄，能拉近远处的物体，常用于野生动物和体育摄影。"},{id:"cs-9321",module:"changshi",prompt:"广角镜头拍摄建筑时容易产生什么问题？",options:["透视畸变", "噪点", "色偏", "对焦慢"],answer:0,explanation:"广角镜头视角大，拍摄建筑时近大远小的透视被夸大，线条易倾斜变形，可用移轴镜头校正。"},{id:"cs-9322",module:"changshi",prompt:"摄影中包围曝光的作用是？",options:["拍摄多张不同曝光照片供选择", "连续对焦", "连拍", "白平衡偏移"],answer:0,explanation:"包围曝光一次拍摄多张不同曝光量的照片，确保至少一张曝光准确，常用于大光比场景。"},{id:"cs-9323",module:"changshi",prompt:"手机摄影中HDR模式的作用是？",options:["平衡明暗细节，扩大动态范围", "增加色彩饱和度", "提高帧率", "变焦"],answer:0,explanation:"HDR通过合成不同曝光的照片，同时保留高光和阴影细节，适合大光比场景。"},{id:"cs-9324",module:"changshi",prompt:"拍摄证件照时，背景通常要求什么颜色？",options:["白色或蓝色纯色背景", "黑色", "红色花纹", "灰色"],answer:0,explanation:"证件照一般要求白色或蓝色纯色背景，光线均匀、面部无阴影，便于识别和打印。"},{id:"cs-9325",module:"changshi",prompt:"摄影中追焦拍摄运动物体的技巧是？",options:["相机跟随物体同速移动并慢速快门", "固定相机高速快门", "关闭对焦", "使用闪光灯"],answer:0,explanation:"追焦即相机与物体同速平移，配合较慢快门，使主体清晰而背景模糊，表现速度感。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9326",module:"changshi",prompt:"设置强密码的基本原则是什么？",options:["长度足够且混合大小写字母、数字和符号", "用生日", "用连续数字", "所有网站同一密码"],answer:0,explanation:"强密码应至少十二位并混合字符类型，不同网站使用不同密码，可借助密码管理器管理。"},{id:"cs-9327",module:"changshi",prompt:"收到自称公检法要求转账的电话，正确做法是？",options:["立即挂断并报警核实", "配合转账", "提供验证码", "按指示操作"],answer:0,explanation:"公检法机关不会通过电话要求转账或提供验证码，此类电话均为诈骗，应挂断并拨打一一零核实。"},{id:"cs-9328",module:"changshi",prompt:"公共WiFi使用时最应注意什么？",options:["避免登录网银等敏感账户", "网速快慢", "信号强弱", "免费时长"],answer:0,explanation:"公共WiFi可能被窃听，应避免在公共网络登录网银、支付等敏感账户，必要时使用流量或VPN。"},{id:"cs-9329",module:"changshi",prompt:"个人信息泄露的主要途径不包括？",options:["正规银行柜台办理业务", "随意扫码", "快递单丢弃", "社交媒体晒图"],answer:0,explanation:"正规渠道办理业务受隐私保护，随意扫码、丢弃快递单和过度晒图是常见的个人信息泄露途径。"},{id:"cs-9330",module:"changshi",prompt:"钓鱼邮件的典型特征是？",options:["伪装官方诱导点击链接或输入密码", "来自熟人", "内容简短", "无附件"],answer:0,explanation:"钓鱼邮件伪装成银行、快递等官方通知，诱导点击假链接或输入账号密码，应核实发件人真伪。"},{id:"cs-9331",module:"changshi",prompt:"手机丢失后第一时间应该做什么？",options:["挂失SIM卡并冻结支付账户", "报警后等待", "换手机", "不管它"],answer:0,explanation:"手机丢失应立即挂失SIM卡、冻结支付宝微信等支付账户，防止验证码被用于盗刷，再报警备案。"},{id:"cs-9332",module:"changshi",prompt:"电脑中勒索病毒后的正确做法是？",options:["断网并求助专业人员，不轻易支付赎金", "支付赎金", "重装系统前不备份数据", "继续使用"],answer:0,explanation:"勒索病毒应立即断网防止扩散，联系安全专业人员，平时应定期备份重要数据，不轻易支付赎金。"},{id:"cs-9333",module:"changshi",prompt:"网购时防范诈骗的关键是？",options:["使用正规平台并核实商家资质", "贪图低价", "私下转账", "点击陌生链接"],answer:0,explanation:"网购应使用正规平台交易，警惕明显低于市场价的商品，不脱离平台私下转账。"},{id:"cs-9334",module:"changshi",prompt:"软件更新补丁的主要作用是？",options:["修复安全漏洞", "增加广告", "降低速度", "收集隐私"],answer:0,explanation:"软件更新常包含安全补丁，及时更新可修复已知漏洞，降低被攻击的风险。"},{id:"cs-9335",module:"changshi",prompt:"社交媒体晒图时应注意什么？",options:["避免暴露住址、行程和证件信息", "越多越好", "标注详细位置", "晒车票"],answer:0,explanation:"晒图应避免暴露家庭住址、车票、证件和实时行程，防止被不法分子利用。"},{id:"cs-9336",module:"changshi",prompt:"什么是网络钓鱼网站？",options:["仿冒真实网站的假网站", "钓鱼爱好者网站", "渔业网站", "新闻网站"],answer:0,explanation:"钓鱼网站外观与真实网站相似，骗取账号密码和支付信息，应核对网址域名是否正确。"},{id:"cs-9337",module:"changshi",prompt:"快递单丢弃前应如何处理？",options:["涂抹或撕毁个人信息", "直接丢弃", "整张保留", "送给他人"],answer:0,explanation:"快递单含姓名、电话和地址，丢弃前应涂抹或撕毁个人信息，防止被不法分子收集利用。"},{id:"cs-9338",module:"changshi",prompt:"二维码扫码支付的安全做法是？",options:["核对收款方信息后再支付", "见码就扫", "先付款后核实", "借给他人扫码"],answer:0,explanation:"扫码前应核对收款方名称和金额，不扫来历不明的二维码，防止被替换收款码诈骗。"},{id:"cs-9339",module:"changshi",prompt:"旧手机出售前应如何处理？",options:["恢复出厂设置并覆盖数据", "直接出售", "删除可见文件即可", "拆掉电池"],answer:0,explanation:"恢复出厂设置后应反复写入无关数据覆盖存储，或使用专业擦除工具，防止数据被恢复。"},{id:"cs-9340",module:"changshi",prompt:"网络诈骗中冒充客服退款的手法是？",options:["谎称商品有问题诱导退款操作", "真的退款", "上门服务", "官方通知"],answer:0,explanation:"冒充客服谎称商品质量问题退款，诱导在假页面输入银行卡信息，实为盗取资金，应通过官方渠道核实。"},{id:"cs-9341",module:"changshi",prompt:"什么是社会工程学攻击？",options:["利用人性弱点骗取信息的手段", "编程攻击", "硬件攻击", "物理入侵"],answer:0,explanation:"社会工程学通过冒充身份、制造紧迫感等心理手段骗取信任和信息，防范关键是核实身份。"},{id:"cs-9342",module:"changshi",prompt:"家庭路由器的安全设置应包括？",options:["修改默认管理密码并使用强加密", "使用默认密码", "开放所有端口", "关闭防火墙"],answer:0,explanation:"路由器应修改默认密码、使用WPA2以上加密、及时更新固件，防止被入侵劫持。"},{id:"cs-9343",module:"changshi",prompt:"收到中奖短信要求先交手续费，这是？",options:["典型诈骗", "正常流程", "官方活动", "银行通知"],answer:0,explanation:"正规中奖不需要事先缴纳手续费或税费，要求先交钱的中奖信息均为诈骗。"},{id:"cs-9344",module:"changshi",prompt:"保护儿童上网安全的措施是？",options:["开启青少年模式并约定上网规则", "放任使用", "共用成人账户", "不闻不问"],answer:0,explanation:"应为儿童开启青少年模式过滤不良内容，约定上网时间和规则，关注其上网行为。"},{id:"cs-9345",module:"changshi",prompt:"网络购物保留消费凭证的作用是？",options:["维权和退换货的依据", "装饰", "报销", "收藏"],answer:0,explanation:"订单截图、聊天记录和发票是消费维权的重要凭证，发生纠纷时可据此投诉或起诉。"},{id:"cs-9346",module:"changshi",prompt:"蹭网软件破解他人WiFi密码的行为属于？",options:["违法行为", "正常使用", "技术分享", "灰色地带"],answer:0,explanation:"未经许可破解他人WiFi密码侵犯他人网络权益，情节严重可能构成犯罪，应通过正规渠道获取网络。"},{id:"cs-9347",module:"changshi",prompt:"手机APP索要权限时应注意什么？",options:["只授予与功能相关的必要权限", "全部允许", "拒绝所有", "随意授权"],answer:0,explanation:"APP索要通讯录、位置、相机等权限时应审查必要性，过度索权可能收集滥用个人信息。"},{id:"cs-9348",module:"changshi",prompt:"防范电信诈骗的核心原则是？",options:["不轻信、不透露、不转账", "多转账", "先转账后核实", "告诉陌生人信息"],answer:0,explanation:"防范电信诈骗应做到不轻信陌生来电、不透露个人信息和验证码、不向陌生账户转账。"},{id:"cs-9349",module:"changshi",prompt:"电脑安装杀毒软件的作用是？",options:["检测和清除恶意程序", "加快网速", "清理灰尘", "提升配置"],answer:0,explanation:"杀毒软件可检测查杀病毒木马，配合防火墙和及时更新系统，构成基础安全防护。"},{id:"cs-9350",module:"changshi",prompt:"网络账号注销的正确做法是？",options:["通过官方渠道申请注销并解绑关联账户", "直接卸载APP", "不管它", "告诉他人密码"],answer:0,explanation:"不再使用的账号应通过官方渠道注销，解绑手机号和银行卡，防止信息泄露和被冒用。"},{id:"cs-9351",module:"changshi",prompt:"中国传统婚礼中新娘穿红色嫁衣的寓意是？",options:["喜庆吉祥", "哀悼", "纯洁", "富贵"],answer:0,explanation:"红色在中国传统文化中象征喜庆吉祥，婚礼、春节等喜庆场合均以红色为主色调。"},{id:"cs-9352",module:"changshi",prompt:"旗袍起源于哪个民族的服饰？",options:["满族", "汉族", "蒙古族", "藏族"],answer:0,explanation:"旗袍由满族旗女袍服演变而来，经民国时期改良成为体现东方女性美的经典服饰。"},{id:"cs-9353",module:"changshi",prompt:"中国古代不同朝代的官服颜色主要区分什么？",options:["官职等级", "籍贯", "年龄", "姓氏"],answer:0,explanation:"唐代以后官服颜色按品级区分，如紫色为高级官员，体现等级制度。"},{id:"cs-9354",module:"changshi",prompt:"中式宴席上主宾应坐在什么位置？",options:["主人右侧", "门口", "角落", "背对门"],answer:0,explanation:"中式宴席以面门为尊，主宾坐主人右侧，体现对客人的尊重。"},{id:"cs-9355",module:"changshi",prompt:"中国传统餐桌礼仪中，筷子不能做什么？",options:["插在米饭上", "夹菜", "放在筷架上", "递给别人"],answer:0,explanation:"筷子插在米饭上形似上香，被视为不吉利，是餐桌大忌。"},{id:"cs-9356",module:"changshi",prompt:"唐装的名称来源于什么？",options:["海外对唐人的称呼", "唐朝官服", "唐氏家族", "唐山路"],answer:0,explanation:"唐装由海外唐人街对华人的称呼而来，实为清代马褂改良的中式服装，并非唐朝服饰。"},{id:"cs-9357",module:"changshi",prompt:"中国古代女子的及笄礼在什么年龄举行？",options:["十五岁", "十二岁", "十八岁", "二十岁"],answer:0,explanation:"女子十五岁行及笄礼，表示成年可以婚嫁；男子二十岁行冠礼。"},{id:"cs-9358",module:"changshi",prompt:"中山装的设计寓意中，五个扣子代表什么？",options:["五权分立", "五行", "五谷丰登", "五湖四海"],answer:0,explanation:"中山装前襟五个扣子代表五权分立，四个口袋代表礼义廉耻，体现孙中山的政治理念。"},{id:"cs-9359",module:"changshi",prompt:"中国传统敬酒礼仪中，晚辈向长辈敬酒时杯口应？",options:["低于长辈杯口", "高于长辈杯口", "平齐", "随意"],answer:0,explanation:"晚辈敬酒时杯口应低于长辈杯口，表示尊敬，是中国传统酒桌礼仪。"},{id:"cs-9360",module:"changshi",prompt:"藏族哈达的颜色以什么最为尊贵？",options:["白色", "红色", "黄色", "蓝色"],answer:0,explanation:"哈达以白色最为普遍尊贵，象征纯洁吉祥，献哈达是藏族最高礼节之一。"},{id:"cs-9361",module:"changshi",prompt:"中国古代成年男子行冠礼的年龄是？",options:["二十岁", "十五岁", "十八岁", "二十五岁"],answer:0,explanation:"男子二十岁行冠礼，加冠表示成年，可以娶妻、入仕、承担社会责任。"},{id:"cs-9362",module:"changshi",prompt:"中式婚礼中交杯酒的含义是？",options:["夫妻合二为一", "庆祝丰收", "敬天地", "纪念祖先"],answer:0,explanation:"交杯酒源于古代合卺礼，新人共饮象征夫妻一体、同甘共苦。"},{id:"cs-9363",module:"changshi",prompt:"中国传统服饰中马面裙的特点是？",options:["前后有光面裙门", "百褶无门", "两侧开衩", "连体设计"],answer:0,explanation:"马面裙前后各有裙门，两侧打褶，是明清时期女子的典型裙式，近年重新流行。"},{id:"cs-9364",module:"changshi",prompt:"中国传统宴席中鱼头应朝向什么位置？",options:["尊贵的客人", "主人自己", "门口", "随意"],answer:0,explanation:"鱼头朝向尊贵客人表示尊敬，是中式宴席的礼仪讲究。"},{id:"cs-9365",module:"changshi",prompt:"中国古代官员上朝穿的朝服主要特点是？",options:["宽袍大袖配朝珠顶戴", "便服", "戎装", "短打"],answer:0,explanation:"朝服是官员参加重大典礼的礼服，形制庄重，配以朝珠、顶戴等，体现等级。"},{id:"cs-9366",module:"changshi",prompt:"中国传统茶礼中，主人斟茶时茶杯应斟几分满？",options:["七分满", "十分满", "三分满", "越满越好"],answer:0,explanation:"茶满欺人，斟茶七分满留三分人情，是传统茶礼的讲究。"},{id:"cs-9367",module:"changshi",prompt:"中国古代女子的头饰中凤冠是？",options:["贵族女性礼服头饰", "日常头饰", "男子头饰", "儿童头饰"],answer:0,explanation:"凤冠是贵族女性在重大场合佩戴的礼服头饰，以凤凰装饰，象征尊贵。"},{id:"cs-9368",module:"changshi",prompt:"中国传统礼仪中拱手礼的正确做法是？",options:["右手抱拳左手包于外", "左手抱拳右手包于外", "双手平举", "鞠躬"],answer:0,explanation:"拱手礼男子右手抱拳、左手包于外，表示善意，是传统见面礼节。"},{id:"cs-9369",module:"changshi",prompt:"中式婚礼中新娘盖红盖头的习俗寓意是？",options:["遮羞辟邪", "保暖", "装饰", "区分身份"],answer:0,explanation:"红盖头寓意遮羞辟邪，由新郎在洞房中揭开，是传统婚礼仪式的一部分。"},{id:"cs-9370",module:"changshi",prompt:"中国传统服饰中龙袍是？",options:["皇帝的礼服", "官员礼服", "平民服饰", "女性服饰"],answer:0,explanation:"龙袍绣有龙纹，是皇帝的专属礼服，他人穿着龙纹服饰属僭越。"},{id:"cs-9371",module:"changshi",prompt:"中国传统餐桌礼仪中，长辈动筷后晚辈才能？",options:["开始用餐", "离席", "说话", "倒茶"],answer:0,explanation:"长辈先动筷表示对长辈的尊重，是中国传统家庭餐桌礼仪的基本要求。"},{id:"cs-9372",module:"changshi",prompt:"苗族服饰以什么工艺最为著名？",options:["银饰和刺绣", "织锦", "蜡染", "扎染"],answer:0,explanation:"苗族服饰以精美银饰和刺绣著称，盛装银饰可达数十斤，是苗族文化的载体。"},{id:"cs-9373",module:"changshi",prompt:"中国传统礼仪中作揖的正确姿势是？",options:["双手抱拳前推并躬身", "单手", "点头", "握手"],answer:0,explanation:"作揖时双手抱拳前推并微微躬身，是中国传统见面礼，表达敬意。"},{id:"cs-9374",module:"changshi",prompt:"中国古代的深衣是指什么？",options:["上下连体的长衣", "短上衣", "裙子", "外套"],answer:0,explanation:"深衣是上下连体的长衣，是古代诸侯、士人居家和庶人礼服，影响深远。"},{id:"cs-9375",module:"changshi",prompt:"中国传统宴席中敬茶的顺序是？",options:["先长辈后晚辈", "先晚辈后长辈", "随意", "先自己"],answer:0,explanation:"敬茶应先长辈后晚辈，体现长幼有序的传统礼仪。"},{id:"cs-9376",module:"changshi",prompt:"中国传统服饰中披肩的主要功能是？",options:["保暖装饰", "防雨", "遮阳", "束腰"],answer:0,explanation:"披肩围于肩颈，兼具保暖和装饰功能，是传统服饰的重要配件。"},{id:"cs-9377",module:"changshi",prompt:"中国古代婚俗中三书六礼的三书指？",options:["聘书、礼书、迎书", "婚书、地契、房契", "书信、遗书、证书", "聘书、婚书、休书"],answer:0,explanation:"三书为聘书、礼书、迎书，六礼为纳采至亲迎的六个环节，是传统婚礼的完整流程。"},{id:"cs-9378",module:"changshi",prompt:"冰箱冷藏室温度设置过高会导致什么问题？",options:["食物易变质", "耗电增加", "结冰", "噪音大"],answer:0,explanation:"冷藏室温度高于四度时细菌繁殖加快，食物易变质，建议设置在零至四度之间。"},{id:"cs-9379",module:"changshi",prompt:"空调制冷时设定温度每调高一度，大约可节电多少？",options:["百分之六至八", "百分之五十", "百分之一", "百分之二十"],answer:0,explanation:"空调制冷设定温度每调高一度可节电约百分之六至八，夏季建议设定在二十六度左右。"},{id:"cs-9380",module:"changshi",prompt:"洗衣机使用后应保持什么状态？",options:["门盖打开通风干燥", "立即关门", "注满水", "断电即可"],answer:0,explanation:"洗衣机用后门盖打开通风，可防止霉菌滋生和异味产生，延长机器寿命。"},{id:"cs-9381",module:"changshi",prompt:"电热水器长期不清洗会导致什么问题？",options:["水垢积累影响加热效率", "漏电", "水温过高", "无影响"],answer:0,explanation:"电热水器内胆水垢积累会降低加热效率、增加耗电，建议每年清洗一次。"},{id:"cs-9382",module:"changshi",prompt:"微波炉加热食物的原理是？",options:["微波使水分子振动产生热量", "红外加热", "电阻加热", "热传导"],answer:0,explanation:"微波使食物中的水分子高速振动摩擦生热，由内而外加热，金属容器会反射微波产生火花。"},{id:"cs-9383",module:"changshi",prompt:"空调滤网多久清洗一次为宜？",options:["一至两个月", "一年", "三年", "不需要清洗"],answer:0,explanation:"空调滤网积尘会降低制冷效果、增加耗电并滋生细菌，建议一至两个月清洗一次。"},{id:"cs-9384",module:"changshi",prompt:"电视机长期待机的耗电情况是？",options:["仍有待机功耗", "完全无耗电", "耗电与开机相同", "自动断电"],answer:0,explanation:"电器待机仍有功耗，长期累积不小，建议不使用时关闭电源或使用带开关的插排。"},{id:"cs-9385",module:"changshi",prompt:"电冰箱放置时应注意什么？",options:["四周留出散热空间", "紧贴墙壁", "放在阳光直射处", "靠近热源"],answer:0,explanation:"冰箱四周应留出十厘米以上散热空间，远离热源和阳光直射，有利于散热和节电。"},{id:"cs-9386",module:"changshi",prompt:"电饭煲煮饭后不及时拔插头的后果是？",options:["保温耗电并可能烧干", "无影响", "米饭更香", "省电"],answer:0,explanation:"电饭煲保温状态持续耗电，长时间保温可能使米饭变干变黄，应及时断电。"},{id:"cs-9387",module:"changshi",prompt:"空调冬季制热时出风口方向应如何调整？",options:["风向朝下", "朝上", "水平", "随意"],answer:0,explanation:"热空气上升，制热时风向朝下可使热量均匀分布，提高制热效率。"},{id:"cs-9388",module:"changshi",prompt:"节能灯相比白炽灯的优点是？",options:["发光效率高、耗电少", "更亮", "更便宜", "寿命更短"],answer:0,explanation:"节能灯发光效率高，同亮度下耗电仅为白炽灯的五分之一左右，寿命更长。"},{id:"cs-9389",module:"changshi",prompt:"电风扇配合空调使用的节能方法是？",options:["空调温度调高配合风扇循环", "只开空调", "只开风扇", "同时开多台空调"],answer:0,explanation:"风扇促进空气循环，使体感温度降低，可将空调温度调高一到两度，显著节电。"},{id:"cs-9390",module:"changshi",prompt:"电水壶水垢的清理方法是？",options:["用白醋或柠檬酸煮洗", "用钢丝球刷", "用洗洁精", "不清理"],answer:0,explanation:"白醋或柠檬酸中的酸能溶解水垢，煮洗后冲洗干净即可，避免用硬物刮擦内壁。"},{id:"cs-9391",module:"changshi",prompt:"冰箱存放食物的原则是？",options:["生熟分开、留有空隙", "塞满", "生熟混放", "越满越好"],answer:0,explanation:"生熟分开防止交叉污染，食物间留空隙利于冷气循环，保持制冷效果。"},{id:"cs-9392",module:"changshi",prompt:"空调频繁开关机的后果是？",options:["耗电增加并缩短压缩机寿命", "省电", "制冷更好", "无影响"],answer:0,explanation:"空调启动时电流大、耗电高，频繁开关反而费电且损伤压缩机，短时间外出不必关机。"},{id:"cs-9393",module:"changshi",prompt:"洗衣机洗涤剂投放过多会导致什么问题？",options:["残留和漂洗不净", "洗得更干净", "省水", "保护衣物"],answer:0,explanation:"洗涤剂过多难以漂洗干净，残留在衣物上刺激皮肤，还可能滋生细菌，应按说明适量投放。"},{id:"cs-9394",module:"changshi",prompt:"电磁炉使用的锅具要求是？",options:["铁磁性材质如铁锅、不锈钢锅", "玻璃锅", "陶瓷锅", "铝锅"],answer:0,explanation:"电磁炉通过磁场感应加热，需要铁磁性锅具才能产生涡流发热，玻璃和陶瓷锅不适用。"},{id:"cs-9395",module:"changshi",prompt:"冰箱冷冻室温度应设置在多少度？",options:["零下十八度", "零度", "零下五度", "五度"],answer:0,explanation:"冷冻室标准温度为零下十八度，可有效抑制细菌繁殖，长期保存食物。"},{id:"cs-9396",module:"changshi",prompt:"空调外机安装位置的要求是？",options:["通风良好、便于散热", "密闭空间", "阳光直射", "靠近卧室窗户"],answer:0,explanation:"空调外机需要良好通风散热，密闭或阳光直射会降低效率、增加耗电。"},{id:"cs-9397",module:"changshi",prompt:"电吹风使用时应注意什么？",options:["不要长时间近距离吹同一部位", "开最大档", "吹湿头发前不擦干", "靠近纸张"],answer:0,explanation:"电吹风功率大、温度高，长时间近距离吹同一部位易烫伤头发和头皮，应保持距离并不断移动。"},{id:"cs-9398",module:"changshi",prompt:"冰箱除霜的正确方法是？",options:["断电自然融化或用专用铲刀", "用刀硬撬", "用热水浇", "用吹风机吹"],answer:0,explanation:"冰箱结霜过厚影响制冷效率，应断电自然融化，避免用尖锐工具撬刮损伤内壁。"},{id:"cs-9399",module:"changshi",prompt:"家电待机功耗最大的通常是？",options:["机顶盒和路由器", "台灯", "充电器", "风扇"],answer:0,explanation:"机顶盒和路由器长期待机功耗较大，不用时应关闭电源，可节省电费。"},{id:"cs-9400",module:"changshi",prompt:"空调匹数与房间面积的关系是？",options:["匹数应与房间面积匹配", "越大越好", "越小越省电", "无关"],answer:0,explanation:"空调匹数应与房间面积匹配，一匹约适用十至十五平方米，过大浪费电、过小制冷不足。"},{id:"cs-9401",module:"changshi",prompt:"微波炉加热带壳鸡蛋会怎样？",options:["可能爆炸", "更易熟", "更营养", "无影响"],answer:0,explanation:"带壳鸡蛋内部水蒸气积聚压力升高，加热可能爆炸，应去壳或切开后再加热。"},{id:"cs-9402",module:"changshi",prompt:"家电使用寿命到期后应如何处理？",options:["通过正规渠道回收", "随意丢弃", "继续使用", "卖给废品站拆解"],answer:0,explanation:"废旧家电含重金属和有害物质，应通过正规回收渠道处理，避免污染环境。"},{id:"cs-9403",module:"changshi",prompt:"冰箱门封条老化的后果是？",options:["冷气泄漏增加耗电", "制冷更好", "更安静", "无影响"],answer:0,explanation:"门封条老化密封不严，冷气泄漏使压缩机频繁启动，增加耗电，应及时更换。"},{id:"cs-9404",module:"changshi",prompt:"电熨斗使用后应如何处理？",options:["冷却后立放收纳", "立即收起", "放在衣物上", "水洗"],answer:0,explanation:"电熨斗使用后应冷却后立放收纳，避免烫伤和火灾，切勿放在易燃物上。"},{id:"cs-9405",module:"changshi",prompt:"智能家电远程控制的安全措施是？",options:["修改默认密码并定期更新固件", "使用默认密码", "关闭更新", "共享账户"],answer:0,explanation:"智能家电应修改默认密码、开启加密、定期更新固件，防止被远程入侵控制。"},{id:"cs-9406",module:"changshi",prompt:"世界上海拔最高的山峰是？",options:["珠穆朗玛峰", "乔戈里峰", "乞力马扎罗山", "富士山"],answer:0,explanation:"珠穆朗玛峰海拔八千八百四十八点八六米，位于中国与尼泊尔边界，是世界第一高峰。"},{id:"cs-9407",module:"changshi",prompt:"世界上面积最大的海洋是？",options:["太平洋", "大西洋", "印度洋", "北冰洋"],answer:0,explanation:"太平洋面积约一点八亿平方公里，是世界上面积最大、深度最深的海洋。"},{id:"cs-9408",module:"changshi",prompt:"世界上面积最大的平原是？",options:["亚马逊平原", "东欧平原", "西西伯利亚平原", "华北平原"],answer:0,explanation:"亚马逊平原位于南美洲北部，面积约五百六十万平方公里，是世界最大的冲积平原。"},{id:"cs-9409",module:"changshi",prompt:"世界上最深的湖泊是？",options:["贝加尔湖", "里海", "苏必利尔湖", "坦噶尼喀湖"],answer:0,explanation:"贝加尔湖位于俄罗斯西伯利亚，最深处约一千六百三十七米，是世界上最深的湖泊。"},{id:"cs-9410",module:"changshi",prompt:"世界上面积最大的岛屿是？",options:["格陵兰岛", "马达加斯加岛", "加里曼丹岛", "本州岛"],answer:0,explanation:"格陵兰岛面积约二百一十六万平方公里，是世界上最大的岛屿，位于北美洲东北部。"},{id:"cs-9411",module:"changshi",prompt:"世界上最热的地方通常在哪里？",options:["伊朗卢特沙漠", "撒哈拉沙漠", "死海", "吐鲁番"],answer:0,explanation:"伊朗卢特沙漠地表温度曾达七十点七度，被认为是世界上最热的地方之一。"},{id:"cs-9412",module:"changshi",prompt:"世界上最冷的城市是？",options:["雅库茨克", "莫斯科", "渥太华", "哈尔滨"],answer:0,explanation:"俄罗斯雅库茨克冬季平均气温约零下四十度，是世界上最冷的大城市。"},{id:"cs-9413",module:"changshi",prompt:"世界上海拔最低的湖泊是？",options:["死海", "里海", "贝加尔湖", "青海湖"],answer:0,explanation:"死海湖面海拔约负四百三十米，是世界陆地最低点，含盐量极高，人可漂浮其上。"},{id:"cs-9414",module:"changshi",prompt:"世界上最大的瀑布是？",options:["安赫尔瀑布", "尼亚加拉瀑布", "黄果树瀑布", "维多利亚瀑布"],answer:0,explanation:"安赫尔瀑布位于委内瑞拉，落差约九百七十九米，是世界上落差最大的瀑布。"},{id:"cs-9415",module:"changshi",prompt:"世界上最大的热带雨林是？",options:["亚马逊雨林", "刚果雨林", "东南亚雨林", "澳洲雨林"],answer:0,explanation:"亚马逊雨林面积约五百五十万平方公里，被称为地球之肺，是世界最大的热带雨林。"},{id:"cs-9416",module:"changshi",prompt:"世界上面积最大的湖泊是？",options:["里海", "苏必利尔湖", "维多利亚湖", "休伦湖"],answer:0,explanation:"里海面积约三十八万平方公里，虽为咸水湖但是世界上面积最大的湖泊。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9417",module:"changshi",prompt:"中国四大名亭中醉翁亭位于哪个省份？",options:["安徽", "湖南", "浙江", "北京"],answer:0,explanation:"醉翁亭位于安徽滁州琅琊山，因欧阳修醉翁亭记而闻名，与爱晚亭、陶然亭、湖心亭并称四大名亭。"},{id:"cs-9418",module:"changshi",prompt:"中国四大名楼中黄鹤楼位于哪座城市？",options:["武汉", "岳阳", "南昌", "南京"],answer:0,explanation:"黄鹤楼位于湖北武汉长江边，与岳阳楼、滕王阁并称江南三大名楼，崔颢李白均有名篇。"},{id:"cs-9419",module:"changshi",prompt:"中国四大石窟中云冈石窟位于哪个省份？",options:["山西", "河南", "甘肃", "四川"],answer:0,explanation:"云冈石窟位于山西大同，开凿于北魏，以大型石雕佛像著称，与龙门、莫高窟、麦积山并称四大石窟。"},{id:"cs-9420",module:"changshi",prompt:"中国古代书院中岳麓书院位于哪座城市？",options:["长沙", "庐山", "衡阳", "商丘"],answer:0,explanation:"岳麓书院位于湖南长沙岳麓山，创建于北宋，朱熹曾在此讲学，现为湖南大学一部分。"},{id:"cs-9421",module:"changshi",prompt:"中国古代四大名桥中卢沟桥位于哪座城市？",options:["北京", "泉州", "潮州", "赵县"],answer:0,explanation:"卢沟桥位于北京永定河上，以卢沟晓月闻名，一九三七年卢沟桥事变在此爆发。"},{id:"cs-9422",module:"changshi",prompt:"中国四大名园中拙政园位于哪座城市？",options:["苏州", "北京", "承德", "扬州"],answer:0,explanation:"拙政园位于江苏苏州，是江南园林代表作，与颐和园、避暑山庄、留园并称中国四大名园。"},{id:"cs-9423",module:"changshi",prompt:"中国古代书院制度中，山长是指什么？",options:["书院主持人", "山名", "学生", "教师"],answer:0,explanation:"山长是古代书院的主讲和行政负责人，因多建于山中而得名，负责教学和管理工作。"},{id:"cs-9424",module:"changshi",prompt:"中国古代科举考试中殿试的第一名称为什么？",options:["状元", "榜眼", "探花", "进士"],answer:0,explanation:"殿试由皇帝主持，第一名状元、第二名榜眼、第三名探花，均称进士及第。"},{id:"cs-9425",module:"changshi",prompt:"中国古代的连中三元是指什么？",options:["乡试、会试、殿试均得第一", "三次中举", "三个状元", "三代进士"],answer:0,explanation:"连中三元指乡试解元、会试会元、殿试状元均获第一，是科举时代的最高荣誉。"},{id:"cs-9426",module:"changshi",prompt:"中国古代的秀才相当于科举考试的什么级别？",options:["通过院试的生员", "通过乡试", "通过会试", "通过殿试"],answer:0,explanation:"秀才是通过院试的生员，取得参加乡试资格，是科举功名的起点。"},{id:"cs-9427",module:"changshi",prompt:"中国古代的举人是指通过什么考试的人？",options:["乡试", "院试", "会试", "殿试"],answer:0,explanation:"举人是通过省级乡试的考生，取得做官资格，第一名称解元。"},{id:"cs-9428",module:"changshi",prompt:"中国古代的进士是指通过什么考试的人？",options:["殿试", "乡试", "会试", "院试"],answer:0,explanation:"进士是通过殿试的考生，由皇帝亲自主持，是科举最高级别的功名。"},{id:"cs-9429",module:"changshi",prompt:"中国古代的八股文盛行于哪个朝代？",options:["明清", "唐宋", "汉唐", "魏晋"],answer:0,explanation:"八股文是明清科举考试的标准文体，格式僵化，限制了思想自由，清末废除。"},{id:"cs-9430",module:"changshi",prompt:"中国古代的太学始建于哪个朝代？",options:["汉武帝时期", "秦始皇时期", "隋朝", "唐朝"],answer:0,explanation:"汉武帝采纳董仲舒建议设立太学，是中国古代最高学府，培养官吏。"},{id:"cs-9431",module:"changshi",prompt:"中国古代的国子监是？",options:["最高学府和教育管理机构", "军事机构", "财政机构", "监察机构"],answer:0,explanation:"国子监是隋唐以后的最高学府和教育管理机构，监生可参加科举或直接授官。"},{id:"cs-9432",module:"changshi",prompt:"中国古代的武举制度创立于哪个朝代？",options:["唐代", "汉代", "宋代", "清代"],answer:0,explanation:"武则天时期创立武举，考试武艺和兵法，为武官选拔开辟了通道。"},{id:"cs-9433",module:"changshi",prompt:"中国古代的恩贡和岁贡的区别是？",options:["恩贡因庆典特设，岁贡按年例选送", "无区别", "恩贡更高级", "岁贡更高级"],answer:0,explanation:"岁贡是按年例定期选送生员入国子监，恩贡是遇皇家庆典特设的名额。"},{id:"cs-9434",module:"changshi",prompt:"中国古代的翰林院是？",options:["文学侍从和修史机构", "军事机构", "地方行政机构", "监察机构"],answer:0,explanation:"翰林院是古代文学侍从和修史机构，翰林多为进士中的优秀者，接近权力中枢。"},{id:"cs-9435",module:"changshi",prompt:"中国古代的东宫是指什么？",options:["太子居所", "东边的宫殿", "皇帝寝宫", "太后居所"],answer:0,explanation:"东宫是太子的居所和官署，太子也称东宫，属储君的象征。"},{id:"cs-9436",module:"changshi",prompt:"中国古代的六部不包括？",options:["军部", "吏部", "户部", "礼部"],answer:0,explanation:"六部为吏、户、礼、兵、刑、工，军部不属于六部，兵部掌军事。"},{id:"cs-9437",module:"changshi",prompt:"中国古代的御史台是？",options:["监察机构", "行政机构", "军事机构", "司法审判机构"],answer:0,explanation:"御史台是古代中央监察机构，负责纠察百官、弹劾违法，明清改为都察院。"},{id:"cs-9438",module:"changshi",prompt:"中国古代的枢密院是？",options:["最高军事机构", "财政机构", "教育机构", "监察机构"],answer:0,explanation:"枢密院是唐宋最高军事机构，掌管军国机务，与中书省并称二府。"},{id:"cs-9439",module:"changshi",prompt:"中国古代的行省制度创立于哪个朝代？",options:["元代", "唐代", "宋代", "明代"],answer:0,explanation:"元朝创立行省制度，中书省下设行中书省，是现代省制的起源。"},{id:"cs-9440",module:"changshi",prompt:"中国古代的锦衣卫是哪个朝代的机构？",options:["明代", "唐代", "宋代", "清代"],answer:0,explanation:"锦衣卫是明朝的特务机构，直接听命于皇帝，负责侦察、缉捕和刑狱。"},{id:"cs-9441",module:"changshi",prompt:"中国古代的军机处设立于哪个朝代？",options:["清代", "明代", "元代", "唐代"],answer:0,explanation:"军机处设立于清朝雍正年间，是皇帝的机要秘书机构，标志着君主专制达到顶峰。"},{id:"cs-9442",module:"changshi",prompt:"中国古代的科举制度废除于哪一年？",options:["一九零五年", "一八九八年", "一九一一年", "一九二零年"],answer:0,explanation:"科举制度于一九零五年即清光绪三十一年废除，历时一千三百年的选官制度终结。"},{id:"cs-9443",module:"changshi",prompt:"中国古代的察举制盛行于哪个朝代？",options:["汉代", "唐代", "宋代", "明代"],answer:0,explanation:"察举制是汉代选官制度，由地方官员推荐人才，以孝廉为主要科目。"},{id:"cs-9444",module:"changshi",prompt:"中国古代的九品中正制创立于哪个朝代？",options:["魏晋", "汉代", "唐代", "隋代"],answer:0,explanation:"九品中正制由曹魏创立，由中正官品评人才，后期被门阀士族垄断。"},{id:"cs-9445",module:"changshi",prompt:"人体血液中运输氧气的细胞是？",options:["红细胞", "白细胞", "血小板", "淋巴细胞"],answer:0,explanation:"红细胞含血红蛋白，负责运输氧气和二氧化碳，是血液中数量最多的细胞。"},{id:"cs-9446",module:"changshi",prompt:"人体正常的血压范围是多少？",options:["收缩压九十至一百三十九，舒张压六十至八十九毫米汞柱", "收缩压一百五十以上", "舒张压一百以上", "收缩压六十以下"],answer:0,explanation:"正常血压为收缩压九十至一百三十九、舒张压六十至八十九毫米汞柱，超过一百四十/九十为高血压。"},{id:"cs-9447",module:"changshi",prompt:"人体内含量最多的物质是？",options:["水", "蛋白质", "脂肪", "糖类"],answer:0,explanation:"水占成人体重的百分之六十左右，是人体内含量最多的物质，参与代谢和体温调节。"},{id:"cs-9448",module:"changshi",prompt:"人体消化食物和吸收营养的主要器官是？",options:["小肠", "胃", "大肠", "食道"],answer:0,explanation:"小肠长约五至七米，内壁有绒毛增大吸收面积，是消化和吸收的主要场所。"},{id:"cs-9449",module:"changshi",prompt:"人体产生胰岛素的器官是？",options:["胰腺", "肝脏", "甲状腺", "肾上腺"],answer:0,explanation:"胰腺中的胰岛β细胞分泌胰岛素，调节血糖，胰岛素分泌不足会导致糖尿病。"},{id:"cs-9450",module:"changshi",prompt:"人体呼吸系统的起点是？",options:["鼻腔", "咽喉", "气管", "肺"],answer:0,explanation:"鼻腔是呼吸系统起点，具有加温、加湿和过滤空气的作用。"},{id:"cs-9451",module:"changshi",prompt:"人体骨骼共有多少块？",options:["二百零六块", "一百五十块", "三百块", "一百块"],answer:0,explanation:"成人骨骼共二百零六块，新生儿骨骼较多，随发育部分骨骼融合。"},{id:"cs-9452",module:"changshi",prompt:"人体肌肉约有六百多块，最大的肌肉是？",options:["臀大肌", "肱二头肌", "胸大肌", "股四头肌"],answer:0,explanation:"臀大肌是人体最大的肌肉，主要功能是伸髋，在站立和行走中起重要作用。"},{id:"cs-9453",module:"changshi",prompt:"人体心脏共有几个腔？",options:["四个", "两个", "三个", "五个"],answer:0,explanation:"心脏分左右心房和左右心室四个腔，保证动脉血和静脉血不混合。"},{id:"cs-9454",module:"changshi",prompt:"人体正常心跳范围是多少？",options:["每分钟六十至一百次", "每分钟一百二十次", "每分钟四十次", "每分钟一百五十次"],answer:0,explanation:"成人安静时心率正常范围为每分钟六十至一百次，运动员心率可能偏慢。"},{id:"cs-9455",module:"changshi",prompt:"人体内负责过滤血液、生成尿液的器官是？",options:["肾脏", "肝脏", "脾脏", "膀胱"],answer:0,explanation:"肾脏由约一百万个肾单位组成，过滤血液生成尿液，排出代谢废物。"},{id:"cs-9456",module:"changshi",prompt:"人体内最大的内分泌腺是？",options:["甲状腺", "垂体", "肾上腺", "性腺"],answer:0,explanation:"甲状腺是最大的内分泌腺，分泌甲状腺激素调节代谢和生长发育。"},{id:"cs-9457",module:"changshi",prompt:"人体内维生素D的主要来源是？",options:["皮肤经紫外线照射合成", "食物", "饮水", "药物"],answer:0,explanation:"皮肤中的7-脱氢胆固醇经紫外线照射转化为维生素D，促进钙吸收，适量晒太阳有益。"},{id:"cs-9458",module:"changshi",prompt:"人体内血糖的正常范围是多少？",options:["空腹三点九至六点一毫摩尔每升", "空腹十毫摩尔每升以上", "空腹一点零毫摩尔每升", "空腹十五毫摩尔每升"],answer:0,explanation:"空腹血糖正常范围为三点九至六点一毫摩尔每升，超过七点零提示糖尿病可能。"},{id:"cs-9459",module:"changshi",prompt:"人体内负责免疫的细胞主要是？",options:["白细胞", "红细胞", "血小板", "上皮细胞"],answer:0,explanation:"白细胞包括淋巴细胞、中性粒细胞等，负责识别和清除病原体，是免疫系统的主要成分。"},{id:"cs-9460",module:"changshi",prompt:"人体内负责凝血的成分是？",options:["血小板", "红细胞", "白细胞", "血浆蛋白"],answer:0,explanation:"血小板在血管破损时聚集形成血栓，配合凝血因子止血，数量过少易出血。"},{id:"cs-9461",module:"changshi",prompt:"人体内最大的动脉是？",options:["主动脉", "肺动脉", "颈动脉", "股动脉"],answer:0,explanation:"主动脉从心脏左心室发出，是人体最大的动脉，将血液输送到全身。"},{id:"cs-9462",module:"changshi",prompt:"人体内负责平衡的内耳结构是？",options:["半规管", "耳蜗", "鼓膜", "听小骨"],answer:0,explanation:"半规管和前庭感受头部位置变化，维持身体平衡，耳蜗负责听觉。"},{id:"cs-9463",module:"changshi",prompt:"人体内负责嗅觉的感受器位于？",options:["鼻腔上部", "口腔", "咽喉", "气管"],answer:0,explanation:"嗅觉感受器位于鼻腔上部黏膜，能识别数千种气味分子，与味觉共同构成风味感知。"},{id:"cs-9464",module:"changshi",prompt:"中国四大发明中造纸术的改进对世界的主要影响是？",options:["促进文化传播", "提高军事力量", "增加税收", "改善交通"],answer:0,explanation:"造纸术使知识记录和传播成本大幅降低，推动了世界文明进程，经阿拉伯传入欧洲。"},{id:"cs-9465",module:"changshi",prompt:"活字印刷术相比雕版印刷的主要优势是？",options:["可重复使用，效率高", "更美观", "更便宜", "更耐用"],answer:0,explanation:"活字可重复排版使用，不必每书刻版，大幅提高印刷效率，是印刷史的重大革命。"},{id:"cs-9466",module:"changshi",prompt:"火药传入欧洲后对世界历史的影响是？",options:["改变战争形态", "促进贸易", "推动航海", "传播宗教"],answer:0,explanation:"火药武器传入欧洲后改变了战争形态，加速了封建城堡制度的衰落。"},{id:"cs-9467",module:"changshi",prompt:"指南针传入欧洲后直接推动了什么活动？",options:["大航海时代", "工业革命", "文艺复兴", "宗教改革"],answer:0,explanation:"指南针应用于航海使远洋航行成为可能，直接推动了欧洲大航海时代的到来。"},{id:"cs-9468",module:"changshi",prompt:"中国古代四大发明传入欧洲的途径主要是？",options:["丝绸之路和阿拉伯人", "海上直接贸易", "传教士", "战争掠夺"],answer:0,explanation:"四大发明经丝绸之路由阿拉伯人传入欧洲，对欧洲文明发展产生深远影响。"},{id:"cs-9469",module:"changshi",prompt:"中国古代的天文观测中，哈雷彗星的最早记录见于？",options:["春秋时期", "汉代", "唐代", "宋代"],answer:0,explanation:"春秋左传记载公元前六一三年哈雷彗星，是世界最早的彗星记录之一。"},{id:"cs-9470",module:"changshi",prompt:"中国古代的地震记录中，最早见于哪部典籍？",options:["竹书纪年", "史记", "汉书", "诗经"],answer:0,explanation:"竹书纪年记载了夏朝时期的地震，是中国最早的地震记录之一。"},{id:"cs-9471",module:"changshi",prompt:"中国古代的数学著作中，周髀算经主要记载什么？",options:["天文学和数学", "医学", "农学", "建筑"],answer:0,explanation:"周髀算经是古代天文学和数学著作，记载勾股定理和天文历法。"},{id:"cs-9472",module:"changshi",prompt:"中国古代的医学著作中，伤寒杂病论的作者是？",options:["张仲景", "华佗", "孙思邈", "李时珍"],answer:0,explanation:"东汉张仲景著伤寒杂病论，确立辨证论治原则，被尊为医圣。"},{id:"cs-9473",module:"changshi",prompt:"中国古代的农业著作中，农政全书的作者是？",options:["徐光启", "贾思勰", "氾胜之", "王祯"],answer:0,explanation:"明代徐光启著农政全书，系统总结农业技术并强调农政，是古代农学集大成之作。"},{id:"cs-9474",module:"changshi",prompt:"中国古代的地理著作中，徐霞客游记的价值是？",options:["实地考察记录地理和岩溶地貌", "虚构故事", "军事地图", "航海日志"],answer:0,explanation:"明代徐霞客实地考察中国山川，详细记录岩溶地貌，是世界岩溶地貌学的先驱。"},{id:"cs-9475",module:"changshi",prompt:"中国古代的冶金技术中，灌钢法出现在哪个朝代？",options:["南北朝", "汉代", "唐代", "宋代"],answer:0,explanation:"南北朝时期发明灌钢法，将生铁和熟铁配合冶炼，提高了钢的质量和产量。"},{id:"cs-9476",module:"changshi",prompt:"中国古代的造船技术中，水密隔舱技术的作用是？",options:["提高船只抗沉性", "增加载重", "提高速度", "美观"],answer:0,explanation:"水密隔舱将船体分隔成多个密封舱室，一处破损不影响整体，是中国古代造船的重大发明。"},{id:"cs-9477",module:"changshi",prompt:"中国古代的桥梁技术中，洛阳桥的特点是？",options:["筏形基础和种蛎固基法", "石拱", "铁索", "木结构"],answer:0,explanation:"宋代洛阳桥首创筏形基础和种蛎固基法，利用牡蛎加固桥基，是桥梁工程的创举。"},{id:"cs-9478",module:"changshi",prompt:"中国古代的纺织技术中，提花机的发明意义是？",options:["可织出复杂图案", "提高速度", "降低成本", "节省人力"],answer:0,explanation:"提花机通过花本控制经线，可织出复杂图案，是古代纺织技术的重大成就。"},{id:"cs-9479",module:"changshi",prompt:"中国古代的陶瓷技术中，宋代五大名窑不包括？",options:["景德镇窑", "汝窑", "官窑", "哥窑"],answer:0,explanation:"宋代五大名窑为汝、官、哥、钧、定，景德镇窑在元代以后才成为瓷都。"},{id:"cs-9480",module:"changshi",prompt:"中国古代的水利工程中，灵渠连接哪两条河流？",options:["湘江和漓江", "长江和黄河", "淮河和汉江", "珠江和赣江"],answer:0,explanation:"秦代灵渠连接湘江和漓江，沟通长江和珠江水系，是世界上最古老的运河之一。"},{id:"cs-9481",module:"changshi",prompt:"中国古代的军事著作中，孙子兵法的作者是？",options:["孙武", "孙膑", "吴起", "诸葛亮"],answer:0,explanation:"春秋末期孙武著孙子兵法十三篇，是世界上最早的军事理论著作之一。"},{id:"cs-9482",module:"changshi",prompt:"中国古代的建筑著作中，营造法式的作者是？",options:["李诫", "鲁班", "样式雷", "姚承祖"],answer:0,explanation:"宋代李诫著营造法式，系统规定建筑形制、材料和工艺，是古代建筑标准的经典。"},{id:"cs-9483",module:"changshi",prompt:"中国古代的天文仪器中，浑仪的主要功能是？",options:["测量天体位置", "计时", "观测气象", "记录地震"],answer:0,explanation:"浑仪通过多个环圈测量天体的坐标位置，是古代重要的天文观测仪器。"},{id:"cs-9484",module:"changshi",prompt:"中国古代的计时工具中，日晷的原理是？",options:["利用太阳影子计时", "利用水滴", "利用沙漏", "利用机械"],answer:0,explanation:"日晷通过太阳照射晷针在晷面上的影子位置确定时刻，是古代常用的计时工具。"},{id:"cs-9485",module:"changshi",prompt:"中国古代的航海技术中，牵星术的作用是？",options:["利用星辰定位导航", "测量水深", "预测天气", "计算航速"],answer:0,explanation:"牵星术通过观测星辰高度确定船位纬度，是明代航海的重要导航技术。"},{id:"cs-9486",module:"changshi",prompt:"中国古代的医药著作中，千金方的作者是？",options:["孙思邈", "张仲景", "华佗", "李时珍"],answer:0,explanation:"唐代孙思邈著千金方，强调医德和临床经验，被尊为药王。"},{id:"cs-9487",module:"changshi",prompt:"中国古代的数学成就中，算盘的发明意义是？",options:["提高计算效率", "简化书写", "便于携带", "美观"],answer:0,explanation:"算盘和珠算口诀使复杂计算快速完成，是古代重要的计算工具，明代广泛使用。"},{id:"cs-9488",module:"changshi",prompt:"中国古代的地理成就中，郑和航海图的价值是？",options:["记录航线和地标", "绘制世界地图", "预测天气", "军事部署"],answer:0,explanation:"郑和航海图记录了航线、地标和罗盘指向，是世界上现存最早的航海图集之一。"},{id:"cs-9489",module:"changshi",prompt:"中国古代的农业技术中，代田法的发明者是？",options:["赵过", "氾胜之", "贾思勰", "王祯"],answer:0,explanation:"汉代赵过推行代田法，沟垄轮换耕作，提高了土地利用率。"},{id:"cs-9490",module:"changshi",prompt:"中国古代的冶金技术中，生铁冶炼技术的意义是？",options:["降低成本、提高产量", "提高纯度", "增加韧性", "美观"],answer:0,explanation:"中国最早掌握生铁冶炼技术，使铁器大规模生产成为可能，推动了农业发展。"},{id:"cs-9491",module:"changshi",prompt:"中国古代的医学技术中，人痘接种法的意义是？",options:["预防天花", "治疗疟疾", "麻醉", "外科手术"],answer:0,explanation:"人痘接种法预防天花，明代已广泛应用，后传入欧洲，是免疫学的先驱。"},{id:"cs-9492",module:"changshi",prompt:"冬季运动中自由式滑雪空中技巧的评分依据是？",options:["动作难度和完成质量", "滑行速度", "装备重量", "身高"],answer:0,explanation:"空中技巧根据动作难度系数和空中姿态、落地稳定性评分，是中国雪上优势项目。"},{id:"cs-9493",module:"changshi",prompt:"短道速滑比赛中，运动员超越时允许的规则是？",options:["在不犯规的前提下超越", "任何方式", "只能外侧超越", "禁止超越"],answer:0,explanation:"短道速滑允许超越，但不得推搡、阻挡或横切他人路线，违者判罚。"},{id:"cs-9494",module:"changshi",prompt:"冰壶比赛中，运动员擦冰的目的是？",options:["控制冰壶速度和方向", "清洁冰面", "取暖", "庆祝"],answer:0,explanation:"擦冰使冰面微融形成水膜，减少摩擦，可延长滑行距离或调整弧线。"},{id:"cs-9495",module:"changshi",prompt:"花样滑冰中，阿克塞尔跳的特点是？",options:["唯一向前起跳的跳跃", "向后起跳", "空中转体四周", "双人跳"],answer:0,explanation:"阿克塞尔跳是唯一向前起跳的花样滑冰跳跃，因多转半圈而难度更大。"},{id:"cs-9496",module:"changshi",prompt:"冬季两项是由哪两个项目组合而成？",options:["越野滑雪和射击", "跳台滑雪和滑冰", "雪车和冰球", "滑雪和登山"],answer:0,explanation:"冬季两项要求运动员越野滑雪后立即射击，心率稳定性和射击精度缺一不可。"},{id:"cs-9497",module:"changshi",prompt:"极限运动中蹦极的起源与什么有关？",options:["瓦努阿图成人礼", "希腊神话", "罗马竞技", "北欧传说"],answer:0,explanation:"蹦极源于瓦努阿图彭特科斯特岛的成人礼跳台仪式，后发展为现代极限运动。"},{id:"cs-9498",module:"changshi",prompt:"攀岩运动按比赛形式分为难度赛、速度赛和什么？",options:["攀石赛", "接力赛", "团体赛", "耐力赛"],answer:0,explanation:"攀岩三大项目为难度赛、速度赛和攀石赛，二零二零年东京奥运会首次入奥。"},{id:"cs-9499",module:"changshi",prompt:"跳伞运动中，开伞高度一般不低于多少米？",options:["八百米", "一百米", "三千米", "五千米"],answer:0,explanation:"跳伞最低开伞高度一般不低于八百米，确保备用伞有足够时间打开。"},{id:"cs-9500",module:"changshi",prompt:"冲浪运动中，浪高和什么决定冲浪难度？",options:["浪速和浪形", "水温", "天气", "季节"],answer:0,explanation:"冲浪难度取决于浪高、浪速和浪形，大浪和管浪对技术要求更高。"},{id:"cs-9501",module:"changshi",prompt:"滑板运动中，Ollie动作是指什么？",options:["豚跳", "转体", "翻板", "落地"],answer:0,explanation:"Ollie即豚跳，是滑板最基础的动作，通过后脚点板前脚上提使板腾空。"},{id:"cs-9502",module:"changshi",prompt:"电子竞技中，MOBA类游戏的代表作品是？",options:["英雄联盟", "CS:GO", "炉石传说", "FIFA"],answer:0,explanation:"MOBA即多人在线战术竞技，英雄联盟和DOTA2是代表作品，强调团队配合。"},{id:"cs-9503",module:"changshi",prompt:"电子竞技中，FPS类游戏的代表作品是？",options:["CS:GO", "英雄联盟", "DOTA2", "炉石传说"],answer:0,explanation:"FPS即第一人称射击游戏，CS:GO和守望先锋是代表作品，考验反应和瞄准。"},{id:"cs-9504",module:"changshi",prompt:"残奥会田径比赛中，盲人运动员依靠什么参加跑步？",options:["引导员或引导绳", "导盲犬", "助听器", "轮椅"],answer:0,explanation:"盲人跑步比赛由引导员用引导绳陪跑，或使用声音提示，确保公平和安全。"},{id:"cs-9505",module:"changshi",prompt:"残奥会轮椅篮球的场地和规则与普通篮球的区别是？",options:["轮椅碰撞规则类似篮球阻挡", "篮筐更低", "场地更小", "时间更短"],answer:0,explanation:"轮椅篮球场地和篮筐高度与普通篮球相同，轮椅碰撞视为阻挡犯规。"},{id:"cs-9506",module:"changshi",prompt:"冬季残奥会的雪上项目包括越野滑雪和什么？",options:["高山滑雪", "冰球", "滑冰", "雪车"],answer:0,explanation:"冬季残奥会雪上项目包括越野滑雪、高山滑雪、单板滑雪和冬季两项等。"},{id:"cs-9507",module:"changshi",prompt:"马拉松比赛的全长是多少公里？",options:["四十二点一九五公里", "四十公里", "四十五公里", "五十公里"],answer:0,explanation:"马拉松全长四十二点一九五公里，源于古希腊希波战争中传令兵的故事。"},{id:"cs-9508",module:"changshi",prompt:"铁人三项的比赛顺序是？",options:["游泳、自行车、跑步", "跑步、游泳、自行车", "自行车、游泳、跑步", "游泳、跑步、自行车"],answer:0,explanation:"铁人三项按游泳、自行车、跑步顺序进行，考验耐力和转换能力。"},{id:"cs-9509",module:"changshi",prompt:"现代五项包括哪五个项目？",options:["击剑、游泳、马术、跑步、射击", "田径、游泳、举重、摔跤、拳击", "游泳、自行车、跑步、跳高、投掷", "击剑、射击、马术、游泳、越野跑"],answer:0,explanation:"现代五项为击剑、游泳、马术、跑步和射击，源于拿破仑时代的军事训练。"},{id:"cs-9510",module:"changshi",prompt:"冬季奥运会每几年举办一次？",options:["四年", "两年", "三年", "五年"],answer:0,explanation:"冬奥会与夏奥会相间举行，每四年一届，自一九二四年首届以来已举办多届。"},{id:"cs-9511",module:"changshi",prompt:"冰球比赛中，每队上场人数为？",options:["六人", "五人", "七人", "四人"],answer:0,explanation:"冰球每队上场六人，包括一名守门员，比赛节奏快、对抗激烈。"},{id:"cs-9512",module:"changshi",prompt:"雪车比赛中，运动员的姿势是？",options:["坐姿滑行", "站立", "躺卧", "蹲姿"],answer:0,explanation:"雪车运动员坐姿滑行，通过身体重心和舵控制方向，速度可达每小时一百三十公里。"},{id:"cs-9513",module:"changshi",prompt:"越野滑雪的起源与什么有关？",options:["北欧狩猎和交通", "军事训练", "宗教仪式", "庆祝丰收"],answer:0,explanation:"越野滑雪起源于北欧的狩猎和冬季交通，是冬奥会的基础雪上项目。"},{id:"cs-9514",module:"changshi",prompt:"跳台滑雪的评分依据包括距离和什么？",options:["飞行姿态", "装备重量", "起跳速度", "天气"],answer:0,explanation:"跳台滑雪根据飞行距离和姿态、落地稳定性评分，是冬奥会最具观赏性的项目之一。"},{id:"cs-9515",module:"changshi",prompt:"电子竞技成为亚运会正式项目的年份是？",options:["二零二二年杭州亚运会", "二零一零年广州亚运会", "二零一四年仁川亚运会", "二零一八年雅加达亚运会"],answer:0,explanation:"电子竞技在二零一八年雅加达亚运会为表演项目，二零二二年杭州亚运会成为正式项目。"},{id:"cs-9516",module:"changshi",prompt:"冬季运动中冰球运动员的装备不包括？",options:["头盔", "护具", "冰刀鞋", "泳镜"],answer:0,explanation:"冰球装备包括头盔、护具、冰刀鞋和球杆，泳镜不属于冰球装备。"},{id:"cs-9517",module:"changshi",prompt:"攀岩运动中，保护器的功能是？",options:["控制绳索制动力", "增加摩擦", "测量高度", "固定岩石"],answer:0,explanation:"保护器通过摩擦控制绳索，保护攀登者坠落时安全，是攀岩安全装备的核心。"},{id:"cs-9518",module:"changshi",prompt:"极限运动中翼装飞行的特点是？",options:["穿翼装从高处跳下滑翔", "水下运动", "地面竞速", "空中翻滚"],answer:0,explanation:"翼装飞行穿特制翼装从悬崖或飞机跳下，依靠身体控制方向滑翔，危险性极高。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9519",module:"changshi",prompt:"中国八大菜系中川菜的特点是？",options:["麻辣鲜香", "清淡鲜甜", "咸鲜浓重", "酸甜适口"],answer:0,explanation:"川菜以麻辣著称，善用花椒和辣椒，代表菜有麻婆豆腐、回锅肉等。"},{id:"cs-9520",module:"changshi",prompt:"佛跳墙是哪个菜系的代表菜？",options:["闽菜", "川菜", "湘菜", "徽菜"],answer:0,explanation:"佛跳墙是福建闽菜的招牌菜，以鲍鱼、海参、花菇等数十种食材煨制而成。"},{id:"cs-9521",module:"changshi",prompt:"东坡肉的名称与哪位文人有关？",options:["苏东坡", "李白", "杜甫", "陆游"],answer:0,explanation:"东坡肉相传与北宋文学家苏东坡有关，以五花肉慢炖而成，肥而不腻。"},{id:"cs-9522",module:"changshi",prompt:"北京烤鸭的传统吃法是？",options:["配荷叶饼、葱丝和甜面酱", "配米饭", "配面条", "配馒头"],answer:0,explanation:"北京烤鸭片皮后配荷叶饼、葱丝、黄瓜条和甜面酱卷食，皮脆肉嫩。"},{id:"cs-9523",module:"changshi",prompt:"兰州拉面的标准特征是一清二白三红四绿五黄，其中三红指？",options:["辣椒油", "牛肉", "萝卜", "香菜"],answer:0,explanation:"一清指汤清、二白指萝卜白、三红指辣椒油红、四绿指香菜蒜苗绿、五黄指面条黄亮。"},{id:"cs-9524",module:"changshi",prompt:"中国四大菜系不包括？",options:["东北菜", "鲁菜", "川菜", "粤菜"],answer:0,explanation:"四大菜系为鲁、川、苏、粤，东北菜虽有名但不在四大菜系之列。"},{id:"cs-9525",module:"changshi",prompt:"过桥米线起源于哪个省份？",options:["云南", "四川", "贵州", "广西"],answer:0,explanation:"过桥米线源于云南蒙自，以滚烫鸡汤烫熟米线和配料，汤鲜味美。"},{id:"cs-9526",module:"changshi",prompt:"火锅的起源地通常认为是？",options:["重庆", "北京", "成都", "广州"],answer:0,explanation:"重庆火锅以麻辣牛油锅底著称，起源于码头船工的饮食，是中国火锅的代表。"},{id:"cs-9527",module:"changshi",prompt:"中国面食文化中，山西以什么闻名？",options:["面食", "米饭", "海鲜", "烧烤"],answer:0,explanation:"山西面食种类繁多，刀削面、莜面栲栳栳等闻名全国，有面食之乡之称。"},{id:"cs-9528",module:"changshi",prompt:"中国茶点文化中，广式早茶的点心包括？",options:["虾饺、烧卖、肠粉", "煎饼", "肉夹馍", "热干面"],answer:0,explanation:"广式早茶以虾饺、烧卖、肠粉、叉烧包等精致点心著称，配普洱或菊花茶。"},{id:"cs-9529",module:"changshi",prompt:"中国八大菜系中湘菜的特点是？",options:["香辣酸辣", "清淡", "甜", "咸鲜"],answer:0,explanation:"湘菜以香辣、酸辣著称，善用剁椒和腊肉，代表菜有剁椒鱼头。"},{id:"cs-9530",module:"changshi",prompt:"中国饮食文化中，饺子的寓意是？",options:["团圆和财富", "长寿", "健康", "平安"],answer:0,explanation:"饺子形似元宝，寓意团圆和财富，是春节等重要节日的传统食物。"},{id:"cs-9531",module:"changshi",prompt:"中国饮食文化中，年糕的寓意是？",options:["年年高升", "长寿", "团圆", "丰收"],answer:0,explanation:"年糕谐音年高，寓意年年高升，是春节的传统食品。"},{id:"cs-9532",module:"changshi",prompt:"中国饮食文化中，长寿面的寓意是？",options:["长寿", "团圆", "财富", "健康"],answer:0,explanation:"长寿面寓意长寿，生日时吃长寿面是传统习俗，面条越长寓意越好。"},{id:"cs-9533",module:"changshi",prompt:"中国饮食文化中，中秋节的代表食物是？",options:["月饼", "粽子", "汤圆", "饺子"],answer:0,explanation:"中秋节吃月饼寓意团圆，与赏月、提灯笼等习俗共同构成中秋文化。"},{id:"cs-9534",module:"changshi",prompt:"中国饮食文化中，端午节的代表食物是？",options:["粽子", "月饼", "汤圆", "年糕"],answer:0,explanation:"端午节吃粽子纪念屈原，南方咸粽和北方甜粽各有特色。"},{id:"cs-9535",module:"changshi",prompt:"中国饮食文化中，元宵节的代表食物是？",options:["汤圆", "粽子", "月饼", "饺子"],answer:0,explanation:"元宵节吃汤圆寓意团圆美满，南方称汤圆、北方称元宵。"},{id:"cs-9536",module:"changshi",prompt:"中国饮食文化中，腊八粥的由来与什么有关？",options:["佛教传说", "道教", "儒家", "民间故事"],answer:0,explanation:"腊八粥源于佛教传说，相传释迦牟尼在腊八日成道，寺院施粥纪念。"},{id:"cs-9537",module:"changshi",prompt:"中国饮食文化中，豆腐的发明者是？",options:["刘安", "李时珍", "张仲景", "孙思邈"],answer:0,explanation:"相传西汉淮南王刘安发明豆腐，豆腐营养丰富，是中国重要的植物蛋白来源。"},{id:"cs-9538",module:"changshi",prompt:"中国饮食文化中，满汉全席的特点是？",options:["菜肴繁多、集满汉烹饪之大成", "简单", "素食", "快餐"],answer:0,explanation:"满汉全席是清代宫廷宴席，集满族和汉族烹饪精华，菜肴多达百余道。"},{id:"cs-9539",module:"changshi",prompt:"中国饮食文化中，孔府菜的特点是？",options:["讲究礼仪、制作精细", "麻辣", "清淡", "快餐"],answer:0,explanation:"孔府菜是山东曲阜孔府的家菜，讲究礼仪和制作精细，是官府菜的代表。"},{id:"cs-9540",module:"changshi",prompt:"中国饮食文化中，素食文化的兴起与什么有关？",options:["佛教传入", "道教", "儒家", "民间信仰"],answer:0,explanation:"佛教传入后素食文化兴起，寺院素斋和民间素食形成独特的饮食传统。"},{id:"cs-9541",module:"changshi",prompt:"中国饮食文化中，药膳的特点是？",options:["食物与中药结合", "纯西式", "快餐", "生食"],answer:0,explanation:"药膳将中药与食物结合，寓药于食，如当归生姜羊肉汤，是中医饮食养生的体现。"},{id:"cs-9542",module:"changshi",prompt:"中国饮食文化中，八大菜系中浙菜的代表菜是？",options:["西湖醋鱼", "麻婆豆腐", "白切鸡", "佛跳墙"],answer:0,explanation:"浙菜以杭州菜为代表，西湖醋鱼、龙井虾仁是名菜，口味清淡鲜嫩。"},{id:"cs-9543",module:"changshi",prompt:"中国饮食文化中，东北菜的特点是？",options:["量大实惠、炖菜为主", "精致", "清淡", "甜"],answer:0,explanation:"东北菜以量大实惠著称，锅包肉、小鸡炖蘑菇等炖菜体现北方豪放风格。"},{id:"cs-9544",module:"changshi",prompt:"埃菲尔铁塔位于哪个国家？",options:["法国", "英国", "意大利", "德国"],answer:0,explanation:"埃菲尔铁塔位于法国巴黎，建成于一八八九年，高三百三十米，是巴黎的标志。"},{id:"cs-9545",module:"changshi",prompt:"自由女神像位于哪个国家？",options:["美国", "法国", "英国", "加拿大"],answer:0,explanation:"自由女神像位于美国纽约港，是法国赠送给美国的礼物，象征自由和民主。"},{id:"cs-9546",module:"changshi",prompt:"大本钟位于哪个城市？",options:["伦敦", "巴黎", "纽约", "莫斯科"],answer:0,explanation:"大本钟位于英国伦敦威斯敏斯特宫北端，是伦敦的标志性地标。"},{id:"cs-9547",module:"changshi",prompt:"悉尼歌剧院的设计灵感来源于？",options:["帆船和贝壳", "花朵", "山峰", "波浪"],answer:0,explanation:"悉尼歌剧院的白色壳形屋顶设计灵感来自帆船和贝壳，是二十世纪建筑杰作。"},{id:"cs-9548",module:"changshi",prompt:"迪拜哈利法塔的目前高度是？",options:["八百二十八米", "五百米", "一千米", "六百米"],answer:0,explanation:"哈利法塔高八百二十八米，是目前世界上最高的建筑，位于阿联酋迪拜。"},{id:"cs-9549",module:"changshi",prompt:"泰姬陵的建筑风格属于？",options:["莫卧儿伊斯兰建筑", "哥特式", "巴洛克式", "现代主义"],answer:0,explanation:"泰姬陵是莫卧儿建筑代表，融合波斯、伊斯兰和印度风格，以白色大理石著称。"},{id:"cs-9550",module:"changshi",prompt:"克里姆林宫位于哪个国家？",options:["俄罗斯", "乌克兰", "白俄罗斯", "波兰"],answer:0,explanation:"克里姆林宫位于俄罗斯莫斯科，是俄罗斯总统府和历史建筑群，红场相邻。"},{id:"cs-9551",module:"changshi",prompt:"金字塔是哪个古代文明的代表建筑？",options:["古埃及", "古希腊", "古罗马", "古巴比伦"],answer:0,explanation:"金字塔是古埃及法老的陵墓，以吉萨金字塔群最为著名，是古代世界七大奇迹之一。"},{id:"cs-9552",module:"changshi",prompt:"帕特农神庙位于哪个城市？",options:["雅典", "罗马", "开罗", "伊斯坦布尔"],answer:0,explanation:"帕特农神庙位于希腊雅典卫城，是多立克式建筑的巅峰之作。"},{id:"cs-9553",module:"changshi",prompt:"罗马斗兽场建于哪个时期？",options:["古罗马帝国时期", "中世纪", "文艺复兴", "现代"],answer:0,explanation:"罗马斗兽场建于公元一世纪，是古罗马最大的圆形剧场，可容纳五万观众。"},{id:"cs-9554",module:"changshi",prompt:"圣家族大教堂位于哪个城市？",options:["巴塞罗那", "马德里", "巴黎", "罗马"],answer:0,explanation:"圣家族大教堂位于西班牙巴塞罗那，由建筑师高迪设计，至今仍在建造中。"},{id:"cs-9555",module:"changshi",prompt:"帝国大厦位于哪个城市？",options:["纽约", "芝加哥", "洛杉矶", "波士顿"],answer:0,explanation:"帝国大厦位于美国纽约曼哈顿，高三百八十一米，曾是世界最高建筑。"},{id:"cs-9556",module:"changshi",prompt:"金门大桥位于哪个城市？",options:["旧金山", "纽约", "洛杉矶", "西雅图"],answer:0,explanation:"金门大桥位于美国旧金山，是悬索桥的代表作，以橙红色桥身闻名。"},{id:"cs-9557",module:"changshi",prompt:"泰晤士河上的伦敦塔桥属于什么类型？",options:["开合桥", "拱桥", "悬索桥", "斜拉桥"],answer:0,explanation:"伦敦塔桥是开合桥，桥面可升起让大型船只通过，是伦敦的标志。"},{id:"cs-9558",module:"changshi",prompt:"吴哥窟的建筑风格属于？",options:["高棉式", "泰式", "缅式", "印度式"],answer:0,explanation:"吴哥窟是高棉帝国建筑代表，以须弥山布局和回廊浮雕著称。"},{id:"cs-9559",module:"changshi",prompt:"新天鹅堡位于哪个国家？",options:["德国", "奥地利", "瑞士", "法国"],answer:0,explanation:"新天鹅堡位于德国巴伐利亚，是迪士尼城堡的原型，由路德维希二世建造。"},{id:"cs-9560",module:"changshi",prompt:"布达拉宫位于哪座城市？",options:["拉萨", "西宁", "成都", "昆明"],answer:0,explanation:"布达拉宫位于西藏拉萨红山上，是世界上海拔最高的宫殿建筑群。"},{id:"cs-9561",module:"changshi",prompt:"长城的起点和终点分别是？",options:["山海关和嘉峪关", "居庸关和雁门关", "玉门关和阳关", "山海关和玉门关"],answer:0,explanation:"明长城东起山海关，西至嘉峪关，全长约八千八百多公里。"},{id:"cs-9562",module:"changshi",prompt:"兵马俑是哪个朝代的陪葬坑？",options:["秦代", "汉代", "唐代", "明代"],answer:0,explanation:"兵马俑是秦始皇陵的陪葬坑，一九七四年发现，被誉为世界第八大奇迹。"},{id:"cs-9563",module:"changshi",prompt:"都江堰的主要功能是？",options:["防洪灌溉", "军事防御", "交通运输", "观光"],answer:0,explanation:"都江堰是古代水利工程，兼具防洪、灌溉和航运功能，使成都平原成为天府之国。"},{id:"cs-9564",module:"changshi",prompt:"应县木塔的建筑特点是？",options:["全木结构无钉无铆", "石结构", "砖结构", "混凝土"],answer:0,explanation:"应县木塔建于辽代，全木结构不用一钉一铆，是世界上现存最高的木塔。"},{id:"cs-9565",module:"changshi",prompt:"福建土楼的主要功能是？",options:["居住和防御", "祭祀", "储粮", "观景"],answer:0,explanation:"福建土楼是客家人的聚居建筑，环形结构兼具居住和防御功能。"},{id:"cs-9566",module:"changshi",prompt:"开平碉楼融合了什么建筑风格？",options:["中西方风格", "纯中式", "纯西式", "东南亚风格"],answer:0,explanation:"开平碉楼融合中西方建筑风格，是华侨文化的体现，被列入世界文化遗产。"},{id:"cs-9567",module:"changshi",prompt:"新生儿出生后多久开始母乳喂养为宜？",options:["半小时内", "二十四小时后", "三天后", "一周后"],answer:0,explanation:"新生儿出生后半小时内开始母乳喂养，有助于建立哺乳和促进子宫收缩。"},{id:"cs-9568",module:"changshi",prompt:"婴儿添加辅食的适宜时间是？",options:["满六个月", "满三个月", "满一岁", "出生即添加"],answer:0,explanation:"世界卫生组织建议婴儿满六个月开始添加辅食，此前母乳可满足营养需求。"},{id:"cs-9569",module:"changshi",prompt:"婴儿辅食添加的原则是？",options:["由少到多、由稀到稠、由细到粗", "一次多种", "大量添加", "随意添加"],answer:0,explanation:"辅食应一种一种添加，观察过敏反应，由少到多、由稀到稠逐步过渡。"},{id:"cs-9570",module:"changshi",prompt:"婴幼儿发烧三十八点五度以上应如何处理？",options:["遵医嘱使用退烧药并观察", "捂汗", "酒精擦身", "不处理"],answer:0,explanation:"婴幼儿发烧超过三十八点五度可遵医嘱使用退烧药，多喝水，持续高烧应及时就医。"},{id:"cs-9571",module:"changshi",prompt:"幼儿入园前的自理能力不包括？",options:["会开车", "会自己吃饭", "会如厕", "会穿脱简单衣物"],answer:0,explanation:"幼儿入园前应具备基本自理能力，如自己吃饭、如厕、穿脱衣物，开车显然不属于。"},{id:"cs-9572",module:"changshi",prompt:"儿童换牙的年龄通常从几岁开始？",options:["六岁左右", "三岁", "十岁", "十二岁"],answer:0,explanation:"儿童六岁左右开始换牙，乳牙脱落恒牙萌出，至十二岁左右完成。"},{id:"cs-9573",module:"changshi",prompt:"儿童近视预防的有效措施是？",options:["每天户外活动两小时以上", "长时间看电子屏幕", "关灯玩手机", "近距离看书"],answer:0,explanation:"每天两小时以上户外活动可有效预防近视，阳光刺激多巴胺分泌抑制眼轴增长。"},{id:"cs-9574",module:"changshi",prompt:"儿童疫苗接种的目的是？",options:["预防传染病", "增强体力", "促进长高", "改善视力"],answer:0,explanation:"疫苗接种可预防麻疹、脊髓灰质炎等传染病，是国家免疫规划的重要内容。"},{id:"cs-9575",module:"changshi",prompt:"婴幼儿意外窒息的预防措施是？",options:["避免小物件和松软物品靠近口鼻", "喂大块食物", "盖厚被子", "趴睡"],answer:0,explanation:"婴幼儿应避免接触小物件、趴睡和盖厚被子，防止窒息，睡眠环境应安全。"},{id:"cs-9576",module:"changshi",prompt:"儿童安全座椅的使用年龄是？",options:["从出生到十二岁或身高一米四五", "三岁以下", "五岁以下", "七岁以下"],answer:0,explanation:"儿童安全座椅应从出生使用到十二岁或身高一米四五，反向安装适合婴幼儿。"},{id:"cs-9577",module:"changshi",prompt:"儿童语言发展的关键期是？",options:["零至六岁", "七至十岁", "青春期", "成年"],answer:0,explanation:"零至六岁是儿童语言发展关键期，丰富的语言环境有助于语言能力发展。"},{id:"cs-9578",module:"changshi",prompt:"儿童阅读习惯培养的最佳时间是？",options:["越早越好", "上学后", "青春期", "成年"],answer:0,explanation:"阅读习惯应从婴幼儿期开始培养，亲子阅读是有效方式。"},{id:"cs-9579",module:"changshi",prompt:"儿童挑食偏食的纠正方法是？",options:["家长示范、多次尝试、不强迫", "打骂", "放任", "只吃喜欢的"],answer:0,explanation:"家长应以身作则，多次尝试新食物不强迫，营造愉快用餐氛围，逐步纠正挑食。"},{id:"cs-9580",module:"changshi",prompt:"儿童睡眠时间的建议是？",options:["学龄前儿童每天十至十三小时", "六小时", "八小时", "五小时"],answer:0,explanation:"学龄前儿童每天应睡十至十三小时，小学生十小时，充足睡眠有助于生长发育。"},{id:"cs-9581",module:"changshi",prompt:"儿童意外伤害的预防重点是？",options:["家庭安全防护", "减少活动", "限制饮食", "不外出"],answer:0,explanation:"家庭应做好安全防护，如安装护栏、收纳药品和利器，减少儿童意外伤害。"},{id:"cs-9582",module:"changshi",prompt:"儿童发烧时的正确护理是？",options:["多喝水、适当减少衣物", "捂汗", "酒精擦身", "不喝水"],answer:0,explanation:"儿童发烧应多喝水、适当减少衣物帮助散热，体温过高或精神差应及时就医。"},{id:"cs-9583",module:"changshi",prompt:"儿童牙齿保健的正确做法是？",options:["早晚刷牙、定期检查", "只刷一次", "用牙签", "不刷牙"],answer:0,explanation:"儿童应早晚刷牙、使用含氟牙膏、定期口腔检查，预防龋齿。"},{id:"cs-9584",module:"changshi",prompt:"儿童肥胖的预防措施是？",options:["均衡饮食和适量运动", "节食", "只吃零食", "不运动"],answer:0,explanation:"儿童肥胖应通过均衡饮食、控制零食和适量运动预防，不宜盲目节食。"},{id:"cs-9585",module:"changshi",prompt:"儿童情绪管理的培养方法是？",options:["接纳情绪、引导表达", "压抑情绪", "打骂", "忽视"],answer:0,explanation:"家长应接纳儿童情绪，引导其用语言表达，帮助学会情绪管理。"},{id:"cs-9586",module:"changshi",prompt:"儿童独立性培养的正确做法是？",options:["适当放手让其尝试", "包办一切", "过度保护", "放任不管"],answer:0,explanation:"家长应适当放手让儿童尝试力所能及的事，培养独立性，避免包办和过度保护。"},{id:"cs-9587",module:"changshi",prompt:"儿童屏幕时间的建议是？",options:["学龄前每天不超过一小时", "无限制", "每天五小时", "越少越好但完全禁止不现实"],answer:0,explanation:"学龄前儿童每天屏幕时间不超过一小时，学龄儿童应控制并保证户外活动。"},{id:"cs-9588",module:"changshi",prompt:"儿童性教育的正确态度是？",options:["适龄适度、自然坦诚", "回避", "恐吓", "过度"],answer:0,explanation:"儿童性教育应适龄适度、自然坦诚，帮助建立身体界限和自我保护意识。"},{id:"cs-9589",module:"changshi",prompt:"儿童入园焦虑的缓解方法是？",options:["提前适应、正面引导", "强行分离", "威胁", "延迟入园"],answer:0,explanation:"入园焦虑可通过提前适应幼儿园环境、正面引导和建立安全感缓解。"},{id:"cs-9590",module:"changshi",prompt:"儿童多动症的表现是？",options:["注意力缺陷、多动、冲动", "安静", "爱读书", "听话"],answer:0,explanation:"多动症表现为注意力缺陷、过度活动和冲动，需专业评估和干预。"},{id:"cs-9591",module:"changshi",prompt:"儿童贫血的常见原因是？",options:["铁摄入不足", "钙过多", "维生素过多", "蛋白质过多"],answer:0,explanation:"儿童贫血多为缺铁性贫血，应增加富含铁的食物如红肉、动物肝脏。"},{id:"cs-9592",module:"changshi",prompt:"儿童补钙的正确方法是？",options:["食物补钙为主，适量户外活动", "大量补钙剂", "不晒太阳", "只喝饮料"],answer:0,explanation:"儿童补钙应以奶制品等食物为主，配合维生素D和户外活动，不宜盲目补钙剂。"},{id:"cs-9593",module:"changshi",prompt:"儿童安全教育的内容包括？",options:["防拐骗、交通安全、防火防电", "只学知识", "只运动", "只玩"],answer:0,explanation:"儿童安全教育应包括防拐骗、交通安全、防火防电、防溺水等，提高自我保护能力。"},{id:"cs-9594",module:"changshi",prompt:"儿童成长档案的作用是？",options:["记录成长轨迹和发育情况", "装饰", "评比", "奖励"],answer:0,explanation:"成长档案记录身高体重、疫苗接种、发育里程碑等，便于跟踪儿童健康成长。"},{id:"cs-9595",module:"changshi",prompt:"我国生活垃圾分类中，厨余垃圾的颜色标识通常是？",options:["绿色", "红色", "蓝色", "灰色"],answer:0,explanation:"厨余垃圾用绿色标识，可回收物用蓝色，有害垃圾用红色，其他垃圾用灰色或黑色。"},{id:"cs-9596",module:"changshi",prompt:"废旧电池属于哪类垃圾？",options:["有害垃圾", "可回收物", "厨余垃圾", "其他垃圾"],answer:0,explanation:"废旧电池含汞、镉等重金属，属于有害垃圾，应投入专门回收箱。"},{id:"cs-9597",module:"changshi",prompt:"塑料袋属于哪类垃圾？",options:["其他垃圾", "可回收物", "厨余垃圾", "有害垃圾"],answer:0,explanation:"污染的塑料袋难以回收，通常归入其他垃圾；干净的塑料袋部分地区可回收。"},{id:"cs-9598",module:"changshi",prompt:"过期药品的正确处理方式是？",options:["投入有害垃圾或送药店回收", "扔进普通垃圾桶", "冲入下水道", "随意丢弃"],answer:0,explanation:"过期药品属于有害垃圾，应投入有害垃圾桶或送至药店回收点，避免污染环境。"},{id:"cs-9599",module:"changshi",prompt:"玻璃瓶属于哪类垃圾？",options:["可回收物", "有害垃圾", "厨余垃圾", "其他垃圾"],answer:0,explanation:"玻璃瓶可回收再利用，属于可回收物，应清洗后投放。"},{id:"cs-9600",module:"changshi",prompt:"剩菜剩饭属于哪类垃圾？",options:["厨余垃圾", "可回收物", "有害垃圾", "其他垃圾"],answer:0,explanation:"剩菜剩饭属于厨余垃圾，可堆肥处理，应沥干水分后投放。"},{id:"cs-9601",module:"changshi",prompt:"垃圾分类的意义不包括？",options:["增加垃圾总量", "资源回收", "减少污染", "降低处理成本"],answer:0,explanation:"垃圾分类可实现资源回收、减少污染和降低处理成本，不会增加垃圾总量。"},{id:"cs-9602",module:"changshi",prompt:"可回收物的标志颜色是？",options:["蓝色", "绿色", "红色", "黄色"],answer:0,explanation:"可回收物标志为蓝色，包括纸张、塑料、玻璃、金属和织物等。"},{id:"cs-9603",module:"changshi",prompt:"有害垃圾的标志颜色是？",options:["红色", "蓝色", "绿色", "灰色"],answer:0,explanation:"有害垃圾标志为红色，包括电池、灯管、药品、油漆等对人体或环境有害的废弃物。"},{id:"cs-9604",module:"changshi",prompt:"厨余垃圾的处理方式主要是？",options:["堆肥或厌氧发酵", "填埋", "焚烧", "回收"],answer:0,explanation:"厨余垃圾可通过堆肥或厌氧发酵转化为有机肥料或沼气，实现资源化利用。"},{id:"cs-9605",module:"changshi",prompt:"白色污染是指什么污染？",options:["塑料污染", "噪声污染", "光污染", "大气污染"],answer:0,explanation:"白色污染指废弃塑料袋、泡沫餐盒等塑料制品造成的环境污染。"},{id:"cs-9606",module:"changshi",prompt:"减少塑料污染的有效措施是？",options:["自带购物袋、使用可降解制品", "多用一次性制品", "焚烧塑料", "随意丢弃"],answer:0,explanation:"自带购物袋、水杯和使用可降解制品可减少塑料使用，从源头减少污染。"},{id:"cs-9607",module:"changshi",prompt:"节约用水的家庭措施是？",options:["一水多用、使用节水器具", "长流水", "大量用水", "不修漏水"],answer:0,explanation:"家庭应一水多用、使用节水器具、及时修理漏水，养成节水习惯。"},{id:"cs-9608",module:"changshi",prompt:"节约用电的家庭措施是？",options:["随手关灯、使用节能电器", "长明灯", "空调温度过低", "电器常待机"],answer:0,explanation:"随手关灯、使用节能电器、减少待机功耗是节约用电的有效措施。"},{id:"cs-9609",module:"changshi",prompt:"绿色出行的方式包括？",options:["步行、骑行、公共交通", "私家车", "出租车", "网约车"],answer:0,explanation:"步行、骑行和公共交通可减少碳排放，是绿色出行的主要方式。"},{id:"cs-9610",module:"changshi",prompt:"温室气体的主要成分是？",options:["二氧化碳", "氧气", "氮气", "氢气"],answer:0,explanation:"二氧化碳是最主要的温室气体，此外还有甲烷、氧化亚氮等，导致全球变暖。"},{id:"cs-9611",module:"changshi",prompt:"臭氧层破坏的主要原因是？",options:["氟氯烃等消耗臭氧物质", "二氧化碳", "甲烷", "水汽"],answer:0,explanation:"氟氯烃等物质破坏臭氧层，导致紫外线增强，国际社会通过蒙特利尔议定书限制使用。"},{id:"cs-9612",module:"changshi",prompt:"酸雨的pH值范围是？",options:["小于五点六", "大于七", "等于七", "大于八"],answer:0,explanation:"酸雨指pH值小于五点六的降水，由二氧化硫和氮氧化物排放引起。"},{id:"cs-9613",module:"changshi",prompt:"水体富营养化的主要原因是？",options:["氮磷排放过多", "重金属", "石油", "塑料"],answer:0,explanation:"农业化肥和生活污水中的氮磷排入水体，导致藻类疯长、水体缺氧，称为富营养化。"},{id:"cs-9614",module:"changshi",prompt:"噪声污染的标准是白天超过多少分贝？",options:["五十五分贝", "三十分贝", "七十分贝", "九十分贝"],answer:0,explanation:"居住区白天噪声超过五十五分贝、夜间超过四十五分贝即属噪声污染。"},{id:"cs-9615",module:"changshi",prompt:"固体废弃物的处理原则是？",options:["减量化、资源化、无害化", "随意处理", "全部填埋", "全部焚烧"],answer:0,explanation:"固体废弃物处理应遵循减量化、资源化、无害化原则，减少环境影响。"},{id:"cs-9616",module:"changshi",prompt:"生态系统的组成包括生物部分和什么？",options:["非生物部分", "消费者", "生产者", "分解者"],answer:0,explanation:"生态系统由生物部分（生产者、消费者、分解者）和非生物部分（阳光、水、空气等）组成。"},{id:"cs-9617",module:"changshi",prompt:"生物多样性的三个层次是？",options:["基因、物种、生态系统", "动物、植物、微生物", "陆地、海洋、大气", "个体、种群、群落"],answer:0,explanation:"生物多样性包括基因多样性、物种多样性和生态系统多样性三个层次。"},{id:"cs-9618",module:"changshi",prompt:"我国的国家公园体制旨在？",options:["保护自然生态系统和生物多样性", "开发旅游", "农业种植", "城市建设"],answer:0,explanation:"国家公园以保护自然生态系统和生物多样性为主要目的，如三江源、大熊猫国家公园。"},{id:"cs-9619",module:"changshi",prompt:"植树造林的主要生态作用是？",options:["固碳释氧、保持水土", "增加噪声", "减少降水", "污染空气"],answer:0,explanation:"树木通过光合作用吸收二氧化碳、释放氧气，还能保持水土、防风固沙。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9620",module:"changshi",prompt:"中国第一处被列入世界文化遗产的古迹是？",options:["长城", "故宫", "兵马俑", "莫高窟"],answer:0,explanation:"一九八七年长城、故宫、莫高窟、周口店北京人遗址、泰山、秦始皇陵六处首批入选，长城为其中代表。"},{id:"cs-9621",module:"changshi",prompt:"中国被列入世界自然遗产的九寨沟位于哪个省份？",options:["四川", "云南", "贵州", "甘肃"],answer:0,explanation:"九寨沟位于四川阿坝州，以彩色湖泊、瀑布和雪山森林著称，是世界自然遗产。"},{id:"cs-9622",module:"changshi",prompt:"世界文化遗产莫高窟位于哪个省份？",options:["甘肃", "新疆", "陕西", "青海"],answer:0,explanation:"莫高窟位于甘肃敦煌，以精美的壁画和塑像闻名，是世界上现存规模最大的佛教艺术宝库。"},{id:"cs-9623",module:"changshi",prompt:"中国被列入世界文化与自然双重遗产的是？",options:["泰山", "黄山", "峨眉山", "武夷山"],answer:0,explanation:"泰山、黄山、峨眉山-乐山大佛、武夷山均为双重遗产，泰山是中国首个世界遗产之一。"},{id:"cs-9624",module:"changshi",prompt:"世界自然遗产张家界位于哪个省份？",options:["湖南", "湖北", "江西", "贵州"],answer:0,explanation:"张家界武陵源以石英砂岩峰林地貌著称，是中国首个国家森林公园和世界自然遗产。"},{id:"cs-9625",module:"changshi",prompt:"世界文化遗产颐和园位于哪座城市？",options:["北京", "西安", "南京", "洛阳"],answer:0,explanation:"颐和园位于北京，是中国现存规模最大的皇家园林，一九九八年列入世界文化遗产。"},{id:"cs-9626",module:"changshi",prompt:"世界文化遗产天坛位于哪座城市？",options:["北京", "南京", "西安", "开封"],answer:0,explanation:"天坛位于北京南部，是明清皇帝祭天的场所，一九九八年列入世界文化遗产。"},{id:"cs-9627",module:"changshi",prompt:"世界文化遗产丽江古城位于哪个省份？",options:["云南", "四川", "贵州", "广西"],answer:0,explanation:"丽江古城位于云南，以纳西族文化和水巷格局著称，一九九七年列入世界文化遗产。"},{id:"cs-9628",module:"changshi",prompt:"世界文化遗产平遥古城位于哪个省份？",options:["山西", "陕西", "河南", "河北"],answer:0,explanation:"平遥古城位于山西，是中国保存最完整的古代县城之一，城墙、票号和民居保存完好。"},{id:"cs-9629",module:"changshi",prompt:"世界文化遗产皖南古村落代表是？",options:["西递和宏村", "周庄", "乌镇", "同里"],answer:0,explanation:"西递和宏村位于安徽黟县，以徽派建筑和水系布局著称，二零零零年列入世界文化遗产。"},{id:"cs-9630",module:"changshi",prompt:"世界文化遗产明清皇家陵寝包括明十三陵和什么？",options:["清东陵", "唐乾陵", "宋陵", "汉茂陵"],answer:0,explanation:"明清皇家陵寝包括明孝陵、明十三陵、清东陵、清西陵等，体现皇家陵寝制度。"},{id:"cs-9631",module:"changshi",prompt:"世界文化遗产大运河的起点是？",options:["北京", "杭州", "洛阳", "扬州"],answer:0,explanation:"京杭大运河北起北京，南至杭州，全长约一千七百九十四公里，是世界上里程最长的运河。"},{id:"cs-9632",module:"changshi",prompt:"世界文化遗产丝绸之路长安天山廊道路网起点是？",options:["长安", "罗马", "君士坦丁堡", "巴格达"],answer:0,explanation:"丝绸之路长安-天山廊道路网东起汉唐都城长安，西至中亚，是东西方交流的通道。"},{id:"cs-9633",module:"changshi",prompt:"世界自然遗产三江并流的三江指？",options:["怒江、澜沧江、金沙江", "长江、黄河、珠江", "雅鲁藏布江、怒江、澜沧江", "金沙江、雅砻江、大渡河"],answer:0,explanation:"三江并流指怒江、澜沧江、金沙江在云南西北部并行奔流，是世界自然遗产。"},{id:"cs-9634",module:"changshi",prompt:"世界自然遗产四川大熊猫栖息地主要位于哪个山脉？",options:["邛崃山", "秦岭", "大巴山", "武夷山"],answer:0,explanation:"四川大熊猫栖息地包括邛崃山、夹金山等，是大熊猫最主要的栖息地。"},{id:"cs-9635",module:"changshi",prompt:"世界自然遗产中国南方喀斯特不包括？",options:["黄山", "云南石林", "贵州荔波", "重庆武隆"],answer:0,explanation:"中国南方喀斯特包括云南石林、贵州荔波、重庆武隆等，黄山不属于喀斯特地貌。"},{id:"cs-9636",module:"changshi",prompt:"世界文化遗产土司遗址主要分布在哪些省份？",options:["湖南、湖北、贵州", "四川、云南、广西", "山西、陕西、河南", "江苏、浙江、安徽"],answer:0,explanation:"土司遗址包括湖南永顺老司城、湖北唐崖土司城和贵州海龙屯，反映土司制度。"},{id:"cs-9637",module:"changshi",prompt:"世界文化遗产鼓浪屿位于哪个城市？",options:["厦门", "福州", "泉州", "汕头"],answer:0,explanation:"鼓浪屿位于福建厦门，以万国建筑和历史国际社区著称，二零一七年列入世界文化遗产。"},{id:"cs-9638",module:"changshi",prompt:"世界文化遗产良渚古城遗址位于哪个省份？",options:["浙江", "江苏", "上海", "安徽"],answer:0,explanation:"良渚古城遗址位于浙江杭州，距今约五千年，实证了中华五千年文明史。"},{id:"cs-9639",module:"changshi",prompt:"世界文化遗产泉州宋元中国的世界海洋商贸中心体现什么？",options:["海上贸易繁荣", "农业文明", "军事防御", "宗教传播"],answer:0,explanation:"泉州是宋元时期世界海洋商贸中心，二十二处遗产点体现其海上贸易繁荣。"},{id:"cs-9640",module:"changshi",prompt:"世界自然遗产梵净山位于哪个省份？",options:["贵州", "湖南", "重庆", "广西"],answer:0,explanation:"梵净山位于贵州铜仁，是武陵山脉主峰，以黔金丝猴和梵净山冷杉等珍稀物种著称。"},{id:"cs-9641",module:"changshi",prompt:"世界自然与文化遗产武夷山位于哪个省份？",options:["福建", "江西", "浙江", "广东"],answer:0,explanation:"武夷山位于福建北部，以丹霞地貌和茶文化著称，是世界文化与自然双重遗产。"},{id:"cs-9642",module:"changshi",prompt:"世界文化遗产布达拉宫历史建筑群包括？",options:["布达拉宫、大昭寺、罗布林卡", "小昭寺、色拉寺、哲蚌寺", "甘丹寺、扎什伦布寺、塔尔寺", "白居寺、桑耶寺、昌珠寺"],answer:0,explanation:"布达拉宫历史建筑群包括布达拉宫、大昭寺和罗布林卡，是藏式建筑的杰出代表。"},{id:"cs-9643",module:"changshi",prompt:"世界文化遗产曲阜孔庙孔府孔林位于哪个省份？",options:["山东", "河南", "江苏", "河北"],answer:0,explanation:"曲阜孔庙、孔府、孔林位于山东曲阜，是儒家文化的发源地和象征。"},{id:"cs-9644",module:"changshi",prompt:"世界文化遗产长城的主要功能是？",options:["军事防御", "交通运输", "灌溉", "居住"],answer:0,explanation:"长城是古代军事防御工程，由城墙、烽火台、关隘等组成，抵御北方游牧民族入侵。"},{id:"cs-9645",module:"changshi",prompt:"世界文化遗产殷墟位于哪个城市？",options:["安阳", "洛阳", "郑州", "开封"],answer:0,explanation:"殷墟位于河南安阳，是商代晚期都城遗址，出土甲骨文和司母戊鼎等重要文物。"},{id:"cs-9646",module:"changshi",prompt:"世界文化遗产龙门石窟位于哪个省份？",options:["河南", "山西", "甘肃", "四川"],answer:0,explanation:"龙门石窟位于河南洛阳，开凿于北魏至唐代，以卢舍那大佛著称。"},{id:"cs-9647",module:"changshi",prompt:"世界文化遗产大足石刻位于哪个城市？",options:["重庆", "成都", "乐山", "宜宾"],answer:0,explanation:"大足石刻位于重庆大足，以宝顶山和北山摩崖造像著称，是晚期石窟艺术的代表。"},{id:"cs-9648",module:"changshi",prompt:"呐喊的作者是哪位中国现代作家？",options:["鲁迅", "茅盾", "巴金", "老舍"],answer:0,explanation:"鲁迅的呐喊收录狂人日记、阿Q正传等，是新文学运动的奠基之作。"},{id:"cs-9649",module:"changshi",prompt:"家是哪位作家的激流三部曲之一？",options:["巴金", "茅盾", "老舍", "曹禺"],answer:0,explanation:"巴金的激流三部曲包括家、春、秋，家描写封建大家庭的衰落和青年觉醒。"},{id:"cs-9650",module:"changshi",prompt:"穆斯林的葬礼的作者是？",options:["霍达", "张洁", "王安忆", "铁凝"],answer:0,explanation:"霍达的穆斯林的葬礼描写回族玉器世家三代人的命运，获第三届茅盾文学奖。"},{id:"cs-9651",module:"changshi",prompt:"北上徐则臣的作者是？",options:["徐则臣", "梁晓声", "李洱", "陈彦"],answer:0,explanation:"徐则臣的北上以大运河为线索，描写百年历史变迁，获第十届茅盾文学奖。"},{id:"cs-9652",module:"changshi",prompt:"许三观卖血记的作者是？",options:["余华", "莫言", "苏童", "格非"],answer:0,explanation:"余华的许三观卖血记讲述许三观靠卖血度过人生苦难的故事，风格黑色幽默。"},{id:"cs-9653",module:"changshi",prompt:"一句顶一万句的作者是？",options:["刘震云", "莫言", "余华", "王朔"],answer:0,explanation:"刘震云的一句顶一万句描写中原农民的精神孤独，获第八届茅盾文学奖。"},{id:"cs-9654",module:"changshi",prompt:"心理健康的基本标准不包括？",options:["情绪永远稳定无波动", "能正确认识自我", "人际关系和谐", "能适应环境"],answer:0,explanation:"心理健康不等于情绪永远稳定无波动，正常人也会有情绪起伏，关键是能自我调节。"},{id:"cs-9655",module:"changshi",prompt:"应对压力的健康方式是？",options:["运动、倾诉和合理安排时间", "酗酒", "暴饮暴食", "熬夜"],answer:0,explanation:"运动、向亲友倾诉、合理安排时间和放松训练是健康的减压方式。"},{id:"cs-9656",module:"changshi",prompt:"长期失眠的应对建议是？",options:["规律作息并就医评估", "自行长期服用安眠药", "白天补觉", "熬夜后晚起"],answer:0,explanation:"长期失眠应规律作息、睡前放松，必要时就医评估，不宜自行长期服用安眠药。"},{id:"cs-9657",module:"changshi",prompt:"焦虑情绪与焦虑症的区别是？",options:["焦虑症持续时间长且影响正常生活", "没有区别", "焦虑情绪更严重", "焦虑症不常见"],answer:0,explanation:"焦虑情绪是正常反应，焦虑症则持续过度、影响工作生活，需专业诊断和治疗。"},{id:"cs-9658",module:"changshi",prompt:"抑郁症的典型表现是？",options:["持续情绪低落、兴趣丧失超过两周", "偶尔心情不好", "偶尔失眠", "偶尔焦虑"],answer:0,explanation:"抑郁症表现为持续两周以上的情绪低落、兴趣丧失、精力减退，需及时就医。"},{id:"cs-9659",module:"changshi",prompt:"心理危机干预的首要原则是？",options:["确保人身安全", "讲道理", "批评", "忽视"],answer:0,explanation:"心理危机干预首先确保当事人人身安全，移除危险物品，陪伴并寻求专业帮助。"},{id:"cs-9660",module:"changshi",prompt:"情绪管理的第一步是？",options:["觉察和识别情绪", "压抑情绪", "发泄情绪", "否认情绪"],answer:0,explanation:"情绪管理首先觉察和识别自己的情绪，再选择合适的表达和调节方式。"},{id:"cs-9661",module:"changshi",prompt:"深呼吸放松法的原理是？",options:["激活副交感神经，降低心率", "增加氧气", "分散注意力", "催眠"],answer:0,explanation:"深呼吸激活副交感神经系统，降低心率和血压，缓解紧张情绪。"},{id:"cs-9662",module:"changshi",prompt:"人际关系中的有效沟通技巧是？",options:["倾听和表达感受", "指责", "冷战", "回避"],answer:0,explanation:"有效沟通包括积极倾听、表达感受和需求，避免指责和冷战。"},{id:"cs-9663",module:"changshi",prompt:"自信心的培养方法是？",options:["设定小目标并逐步完成", "与他人比较", "自我否定", "等待认可"],answer:0,explanation:"自信心可通过设定小目标并逐步完成、肯定自己的进步来培养。"},{id:"cs-9664",module:"changshi",prompt:"应对挫折的健康心态是？",options:["接受现实并寻找解决方案", "自责", "逃避", "抱怨"],answer:0,explanation:"面对挫折应接受现实、调整心态、寻找解决方案，从失败中学习。"},{id:"cs-9665",module:"changshi",prompt:"社交焦虑的常见表现是？",options:["害怕在他人面前表现", "喜欢社交", "善于表达", "享受关注"],answer:0,explanation:"社交焦虑表现为害怕在他人面前说话、表演或被关注，严重时影响生活。"},{id:"cs-9666",module:"changshi",prompt:"创伤后应激障碍的表现是？",options:["反复回忆创伤事件并回避相关刺激", "遗忘", "兴奋", "平静"],answer:0,explanation:"创伤后应激障碍表现为反复回忆创伤事件、噩梦、回避相关刺激和警觉性增高。"},{id:"cs-9667",module:"changshi",prompt:"青少年叛逆期的应对方式是？",options:["理解和尊重，保持沟通", "强制管教", "放任", "打骂"],answer:0,explanation:"青少年叛逆期应理解和尊重其独立意识，保持沟通，避免强制和打骂。"},{id:"cs-9668",module:"changshi",prompt:"老年人心理健康的关注重点是？",options:["孤独感和价值感", "学习压力", "工作压力", "升学压力"],answer:0,explanation:"老年人面临退休、丧偶等变化，应关注孤独感和价值感，鼓励社交和兴趣爱好。"},{id:"cs-9669",module:"changshi",prompt:"情绪调节的认知策略是？",options:["改变对事件的看法", "压抑情绪", "逃避", "否认"],answer:0,explanation:"认知重评即改变对事件的看法，如将挫折视为学习机会，可有效调节情绪。"},{id:"cs-9670",module:"changshi",prompt:"建立良好亲子关系的关键是？",options:["高质量陪伴和尊重", "物质满足", "严格管教", "放任"],answer:0,explanation:"高质量陪伴、尊重和倾听是建立良好亲子关系的关键，物质满足不能替代情感交流。"},{id:"cs-9671",module:"changshi",prompt:"应对失眠的放松训练包括？",options:["渐进性肌肉放松", "剧烈运动", "喝咖啡", "看手机"],answer:0,explanation:"渐进性肌肉放松、深呼吸和冥想有助于放松身心，改善睡眠质量。"},{id:"cs-9672",module:"changshi",prompt:"拖延症的应对方法是？",options:["分解任务、设定截止时间", "自责", "等待灵感", "逃避"],answer:0,explanation:"拖延症可通过分解任务、设定截止时间、减少干扰和自我奖励来改善。"},{id:"cs-9673",module:"changshi",prompt:"寻求心理帮助的正确态度是？",options:["积极寻求专业帮助是正常的", "羞耻", "隐瞒", "拒绝"],answer:0,explanation:"寻求心理帮助是正常的健康管理行为，如同看感冒一样，不应有病耻感。"},{id:"cs-9674",module:"changshi",prompt:"火灾发生时正确的逃生方法是？",options:["用湿毛巾捂口鼻，低姿弯腰撤离", "乘电梯", "返回取物", "跳楼"],answer:0,explanation:"火灾逃生应用湿毛巾捂住口鼻、低姿弯腰沿疏散通道撤离，切勿乘电梯或返回取物。"},{id:"cs-9675",module:"changshi",prompt:"油锅起火的正确处理方法是？",options:["盖锅盖隔绝空气", "用水浇", "用扇子扇", "倒油"],answer:0,explanation:"油锅起火应立即盖锅盖隔绝空气灭火，切勿用水浇，水会使油飞溅扩大火势。"},{id:"cs-9676",module:"changshi",prompt:"电器起火的正确处理方法是？",options:["先断电再灭火", "直接用水浇", "直接用手拔插头", "不管它"],answer:0,explanation:"电器起火应先切断电源，再用干粉灭火器灭火，切勿用水直接浇，防止触电。"},{id:"cs-9677",module:"changshi",prompt:"灭火器使用的方法是？",options:["拔销、握管、压把、对准火焰根部", "对准火焰上部", "对准人", "随意喷"],answer:0,explanation:"灭火器使用口诀为拔销、握管、压把，对准火焰根部扫射，站在上风方向。"},{id:"cs-9678",module:"changshi",prompt:"燃气泄漏时的正确做法是？",options:["关闭阀门、开窗通风、勿动电器", "开灯检查", "打电话", "用明火测试"],answer:0,explanation:"燃气泄漏应立即关闭阀门、开窗通风，切勿开关电器或使用明火，到室外报警求助。"},{id:"cs-9679",module:"changshi",prompt:"火场中被困房间内的正确做法是？",options:["堵住门缝、窗口呼救等待救援", "强行开门", "跳窗", "躲进衣柜"],answer:0,explanation:"被困房间应用湿布堵住门缝，在窗口挥动鲜艳衣物呼救，等待消防员救援。"},{id:"cs-9680",module:"changshi",prompt:"家庭防火的注意事项不包括？",options:["堆放易燃物", "定期检查电线", "不私拉乱接", "离家断电"],answer:0,explanation:"家庭防火应定期检查电线、不私拉乱接、离家断电，不应堆放易燃物。"},{id:"cs-9681",module:"changshi",prompt:"烟头未熄灭随意丢弃的危险是？",options:["引发火灾", "污染空气", "堵塞下水道", "无影响"],answer:0,explanation:"烟头中心温度可达七百度以上，未熄灭随意丢弃易引燃可燃物引发火灾。"},{id:"cs-9682",module:"changshi",prompt:"高层建筑火灾逃生的原则是？",options:["沿疏散通道向下逃生", "乘电梯", "向上跑", "原地等待"],answer:0,explanation:"高层火灾应沿疏散通道向下逃生，若下方着火无法通过，可退回房间固守待援。"},{id:"cs-9683",module:"changshi",prompt:"森林火灾的报警电话是？",options:["一二一九九", "一一九", "一一零", "一二零"],answer:0,explanation:"森林火灾报警电话为一二一九九，发现火情应及时报警并远离火场。"},{id:"cs-9684",module:"changshi",prompt:"火灾中导致死亡的主要原因是什么？",options:["烟雾窒息", "烧伤", "踩踏", "脱水"],answer:0,explanation:"火灾中约百分之八十的死亡由烟雾窒息引起，因此逃生时应捂住口鼻低姿撤离。"},{id:"cs-9685",module:"changshi",prompt:"家庭应配备的消防器材是？",options:["灭火器和逃生绳", "消防车", "消防栓", "水枪"],answer:0,explanation:"家庭应配备灭火器、逃生绳、防烟面罩等，定期检查有效期。"},{id:"cs-9686",module:"changshi",prompt:"电动车充电的安全注意事项是？",options:["在指定区域充电，不过夜充电", "在楼道充电", "在卧室充电", "飞线充电"],answer:0,explanation:"电动车应在指定充电区域充电，避免过夜充电和飞线充电，防止火灾。"},{id:"cs-9687",module:"changshi",prompt:"火灾逃生时不能携带的物品是？",options:["贵重物品", "湿毛巾", "手机", "钥匙"],answer:0,explanation:"火灾逃生应争分夺秒，不应返回取贵重物品，生命安全最重要。"},{id:"cs-9688",module:"changshi",prompt:"发现火灾后正确的报警顺序是？",options:["先报警再灭火或逃生", "先灭火再报警", "只逃生不报警", "只报警不逃生"],answer:0,explanation:"发现火灾应先拨打一一九报警，再根据火势进行初期扑救或逃生。"},{id:"cs-9689",module:"changshi",prompt:"公共场所的安全出口标识颜色是？",options:["绿色", "红色", "黄色", "蓝色"],answer:0,explanation:"安全出口标识为绿色，指示疏散方向，进入公共场所应先确认位置。"},{id:"cs-9690",module:"changshi",prompt:"液化气罐着火的正确处理方法是？",options:["用湿布覆盖并关阀", "用水浇", "扔出去", "跑开"],answer:0,explanation:"液化气罐着火应用湿布覆盖并关闭阀门，无法关闭时保持稳定并报警。"},{id:"cs-9691",module:"changshi",prompt:"火灾后复燃的原因是？",options:["残留火种未彻底熄灭", "天气", "人为", "自然"],answer:0,explanation:"火灾后残留火种如未彻底熄灭可能复燃，应确认无火星后再离开。"},{id:"cs-9692",module:"changshi",prompt:"家庭用电安全的原则是？",options:["不超负荷用电、人走断电", "多用电器", "私拉乱接", "湿手操作"],answer:0,explanation:"家庭用电应不超负荷、不私拉乱接、湿手不碰电器、人走断电。"},{id:"cs-9693",module:"changshi",prompt:"消防栓的使用方法是？",options:["打开栓门、接水带水枪、开阀出水", "直接开阀", "只接水带", "只开栓门"],answer:0,explanation:"消防栓使用应打开栓门、连接水带和水枪、开阀出水，需两人配合操作。"},{id:"cs-9694",module:"changshi",prompt:"火灾隐患举报电话是？",options:["九六一一九", "一一九", "一二零", "一一零"],answer:0,explanation:"火灾隐患举报电话为九六一一九，发现隐患可及时举报。"},{id:"cs-9695",module:"changshi",prompt:"儿童玩火的预防措施是？",options:["收好打火机并进行安全教育", "放任", "惩罚", "不闻不问"],answer:0,explanation:"应将打火机等火源收好，对儿童进行防火安全教育，防止玩火引发火灾。"},{id:"cs-9696",module:"changshi",prompt:"火灾逃生时正确的开门方式是？",options:["先触摸门板判断温度再决定", "直接开门", "用力撞门", "不管温度"],answer:0,explanation:"开门前应先触摸门板，若烫手说明外部火势大，不应开门，应固守待援。"},{id:"cs-9697",module:"changshi",prompt:"加油站的安全注意事项是？",options:["禁止吸烟和打手机", "可以吸烟", "可以打电话", "可以明火"],answer:0,explanation:"加油站油气浓度高，禁止吸烟、打电话和使用明火，防止爆炸。"},{id:"cs-9698",module:"changshi",prompt:"火灾中湿毛巾的折叠层数建议是？",options:["八层", "两层", "一层", "二十层"],answer:0,explanation:"湿毛巾折叠八层可过滤部分烟雾颗粒，捂住口鼻低姿撤离，但不能完全防毒。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9699",module:"changshi",prompt:"下列文学常识中，骆驼祥子的作者是？",options:["老舍", "巴金", "茅盾", "沈从文"],answer:0,explanation:"老舍的骆驼祥子讲述北平人力车夫祥子的悲剧，是现代文学经典。"},{id:"cs-9700",module:"changshi",prompt:"文学常识考查：子夜的作者是？",options:["茅盾", "鲁迅", "巴金", "老舍"],answer:0,explanation:"茅盾的子夜以二十世纪三十年代上海为背景，描写民族资本家的命运。"},{id:"cs-9701",module:"changshi",prompt:"下列文学常识中，边城的作者是？",options:["沈从文", "鲁迅", "老舍", "巴金"],answer:0,explanation:"沈从文的边城描写湘西茶峒的风土人情，语言优美，是现代抒情小说的代表。"},{id:"cs-9702",module:"changshi",prompt:"中国现当代文学中，雷雨的作者是？",options:["曹禺", "老舍", "郭沫若", "田汉"],answer:0,explanation:"曹禺的雷雨是中国现代话剧的奠基之作，描写封建家庭的悲剧。"},{id:"cs-9703",module:"changshi",prompt:"文学常识考查：平凡世界的作者是？",options:["路遥", "陈忠实", "贾平凹", "莫言"],answer:0,explanation:"路遥的平凡世界描写陕北农村青年的奋斗，获第三届茅盾文学奖。"},{id:"cs-9704",module:"changshi",prompt:"下列文学常识中，白鹿原的作者是？",options:["陈忠实", "路遥", "贾平凹", "莫言"],answer:0,explanation:"陈忠实的白鹿原以陕西关中为背景，描写白鹿两家的恩怨，获第四届茅盾文学奖。"},{id:"cs-9705",module:"changshi",prompt:"中国现当代文学中，红高粱的作者是？",options:["莫言", "余华", "苏童", "贾平凹"],answer:0,explanation:"莫言的红高粱家族描写山东高密抗日故事，获诺贝尔文学奖后影响更大。"},{id:"cs-9706",module:"changshi",prompt:"文学常识考查：活着的主人公是谁？",options:["福贵", "许三观", "孙少平", "白嘉轩"],answer:0,explanation:"余华的活着讲述农民福贵一生的苦难与坚韧，是当代文学的经典。"},{id:"cs-9707",module:"changshi",prompt:"下列文学常识中，围城的作者是？",options:["钱钟书", "杨绛", "张爱玲", "沈从文"],answer:0,explanation:"钱钟书的围城以幽默讽刺的笔调描写知识分子的婚姻和人生困境。"},{id:"cs-9708",module:"changshi",prompt:"中国现当代文学中，倾城之恋的作者是？",options:["张爱玲", "萧红", "丁玲", "冰心"],answer:0,explanation:"张爱玲的倾城之恋描写上海白流苏与范柳原的爱情，风格苍凉精致。"},{id:"cs-9709",module:"changshi",prompt:"文学常识考查：呼兰河传的作者是？",options:["萧红", "萧军", "丁玲", "冰心"],answer:0,explanation:"萧红的呼兰河传以童年回忆描写东北小城的风土人情，语言质朴动人。"},{id:"cs-9710",module:"changshi",prompt:"下列文学常识中，茶馆的作者是？",options:["老舍", "曹禺", "郭沫若", "田汉"],answer:0,explanation:"老舍的茶馆以北京茶馆为舞台，展现清末到民国半个世纪的社会变迁。"},{id:"cs-9711",module:"changshi",prompt:"中国现当代文学中，芙蓉镇的作者是？",options:["古华", "刘心武", "王蒙", "张贤亮"],answer:0,explanation:"古华的芙蓉镇描写湘南小镇的政治变迁和人性，获首届茅盾文学奖。"},{id:"cs-9712",module:"changshi",prompt:"下列文学常识中，长恨歌的作者是？",options:["王安忆", "铁凝", "迟子建", "张洁"],answer:0,explanation:"王安忆的长恨歌描写上海女子王琦瑶的一生，获第五届茅盾文学奖。"},{id:"cs-9713",module:"changshi",prompt:"中国现当代文学中，尘埃落定的作者是？",options:["阿来", "莫言", "余华", "苏童"],answer:0,explanation:"阿来的尘埃落定描写藏族土司制度的衰落，获第五届茅盾文学奖。"},{id:"cs-9714",module:"changshi",prompt:"文学常识考查：秦腔的作者是？",options:["贾平凹", "陈忠实", "路遥", "莫言"],answer:0,explanation:"贾平凹的秦腔描写陕西乡村变迁和秦腔艺术，获第七届茅盾文学奖。"},{id:"cs-9715",module:"changshi",prompt:"下列文学常识中，推拿的作者是？",options:["毕飞宇", "苏童", "余华", "莫言"],answer:0,explanation:"毕飞宇的推拿描写盲人推拿师的生活，获第八届茅盾文学奖。"},{id:"cs-9716",module:"changshi",prompt:"中国现当代文学中，繁花的作者是？",options:["金宇澄", "王安忆", "孙甘露", "张炜"],answer:0,explanation:"金宇澄的繁花以沪语韵味描写上海市民生活，获第九届茅盾文学奖。"},{id:"cs-9717",module:"changshi",prompt:"文学常识考查：人世间的作者是？",options:["梁晓声", "周梅森", "张平", "刘醒龙"],answer:0,explanation:"梁晓声的人世间描写东北普通工人家庭五十年的生活变迁，获第十届茅盾文学奖。"},{id:"cs-9718",module:"changshi",prompt:"下列文学常识中，应物兄的作者是？",options:["李洱", "格非", "苏童", "毕飞宇"],answer:0,explanation:"李洱的应物兄描写知识分子的精神困境，获第十届茅盾文学奖。"},{id:"cs-9719",module:"changshi",prompt:"文学常识考查：主角的作者是？",options:["陈彦", "梁晓声", "李洱", "徐则臣"],answer:0,explanation:"陈彦的主角以秦腔演员为主角，描写戏曲艺人的命运，获第十届茅盾文学奖。"},{id:"cs-9720",module:"changshi",prompt:"中国现当代文学中，黄金时代的作者是？",options:["王小波", "王朔", "刘震云", "余华"],answer:0,explanation:"王小波的黄金时代以黑色幽默描写知青生活，是当代文学的重要作品。"},{id:"cs-9721",module:"changshi",prompt:"文学常识考查：正念冥想的核心是？",options:["专注于当下，不评判", "放空大脑", "回忆过去", "规划未来"],answer:0,explanation:"正念冥想强调专注于当下体验，不评判不执着，有助于减轻焦虑和压力。"},{id:"cs-9722",module:"changshi",prompt:"中国现当代文学中，强迫症的特征是？",options:["反复出现强迫思维和行为", "偶尔担心", "爱干净", "追求完美"],answer:0,explanation:"强迫症表现为反复出现不必要的想法或行为，患者明知不必要但无法控制。"},{id:"cs-9723",module:"changshi",prompt:"文学常识考查：职业倦怠的表现是？",options:["情绪耗竭、去人格化和成就感降低", "工作热情高", "精力充沛", "积极进取"],answer:0,explanation:"职业倦怠表现为情绪耗竭、对工作冷漠和成就感降低，需调整工作节奏和心态。"},{id:"cs-9724",module:"changshi",prompt:"下列文学常识中，网络成瘾的表现是？",options:["无法控制上网时间并影响生活", "偶尔上网", "正常使用", "学习需要"],answer:0,explanation:"网络成瘾表现为无法控制上网时间、优先级失衡和戒断反应，影响学习和生活。"},{id:"cs-9725",module:"changshi",prompt:"中国现当代文学中，心理咨询的作用是？",options:["帮助来访者自我探索和成长", "代替治疗", "开药", "判断对错"],answer:0,explanation:"心理咨询通过专业方法帮助来访者探索自我、解决问题和促进成长，严重精神疾病需就医。"},{id:"cs-9726",module:"changshi",prompt:"中国现当代文学中，自我接纳的含义是？",options:["接受自己的优点和缺点", "自满", "自暴自弃", "否认缺点"],answer:0,explanation:"自我接纳是接受自己的优点和缺点，不苛求完美，是心理健康的基础。"},{id:"cs-9727",module:"changshi",prompt:"下列文学常识中，同理心的含义是？",options:["理解和感受他人情绪", "同情", "怜悯", "认同"],answer:0,explanation:"同理心是设身处地理解和感受他人情绪的能力，是良好人际关系的基础。"},{id:"cs-9728",module:"changshi",prompt:"中国现当代文学中，心理韧性的含义是？",options:["从逆境中恢复和成长的能力", "坚强不屈", "永不失败", "无情绪"],answer:0,explanation:"心理韧性是从逆境、创伤中恢复并成长的能力，可通过经历和支持培养。"},{id:"cs-9729",module:"changshi",prompt:"下列文学常识中，火灾报警电话是？",options:["一一九", "一一零", "一二零", "一二二"],answer:0,explanation:"火灾报警电话为一一九，报警时应说清地址、火势和被困人员情况。"},{id:"cs-9730",module:"changshi",prompt:"文学常识考查：消防通道的作用是？",options:["疏散和救援通道", "停车", "堆物", "晾晒"],answer:0,explanation:"消防通道是火灾时疏散和救援的生命通道，不得占用和堵塞。"},{id:"cs-9731",module:"changshi",prompt:"下列文学常识中，火场逃生的姿势是？",options:["低姿弯腰或匍匐前进", "直立奔跑", "跳跃", "倒退"],answer:0,explanation:"烟雾上升聚集在上层空间，低姿弯腰或匍匐前进可减少吸入有毒烟雾。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9732",module:"changshi",prompt:"中国书法中被称为书圣的是哪位书法家？",options:["王羲之", "颜真卿", "柳公权", "欧阳询"],answer:0,explanation:"东晋王羲之的兰亭序被誉为天下第一行书，他被后世尊称为书圣。"},{id:"cs-9733",module:"changshi",prompt:"中国书法五体不包括下列哪一种？",options:["楷书", "行书", "草书", "瘦金体"],answer:3,explanation:"书法五体为篆、隶、楷、行、草，瘦金体是宋徽宗创造的楷书变体，不单独列为一体。"},{id:"cs-9734",module:"changshi",prompt:"中国画中工笔画的特点是？",options:["线条工整、设色细腻", "写意洒脱", "泼墨", "简笔"],answer:0,explanation:"工笔画以工整细腻的线条和层层渲染著称，与写意画相对，代表画家有宋代院体画家。"},{id:"cs-9735",module:"changshi",prompt:"中国画中写意画的特点是？",options:["笔墨简练、意境深远", "工整细致", "色彩浓艳", "写实逼真"],answer:0,explanation:"写意画以简练笔墨抒发情感，追求意境，代表画家有徐渭、八大山人等。"},{id:"cs-9736",module:"changshi",prompt:"中国画四君子指的是？",options:["梅兰竹菊", "松竹梅兰", "菊竹兰荷", "梅兰荷菊"],answer:0,explanation:"梅兰竹菊因其品格高洁，被文人称为四君子，是国画常见题材。"},{id:"cs-9737",module:"changshi",prompt:"中国画中岁寒三友指的是？",options:["松竹梅", "梅兰竹", "竹菊兰", "松梅兰"],answer:0,explanation:"松竹梅在寒冬中依然挺立，象征坚韧不拔，被称为岁寒三友。"},{id:"cs-9738",module:"changshi",prompt:"京剧中的生旦净丑中，净角指的是？",options:["花脸", "老生", "旦角", "丑角"],answer:0,explanation:"净角又称花脸，以面部脸谱和洪亮唱腔为特点，多演性格鲜明的人物。"},{id:"cs-9739",module:"changshi",prompt:"京剧脸谱中红色代表什么？",options:["忠义", "奸诈", "勇猛", "滑稽"],answer:0,explanation:"京剧脸谱红色代表忠义正直，如关羽；白色代表奸诈，如曹操。"},{id:"cs-9740",module:"changshi",prompt:"中国民族乐器中属于弹拨乐器的是？",options:["琵琶", "二胡", "笛子", "唢呐"],answer:0,explanation:"琵琶是弹拨乐器，二胡是拉弦乐器，笛子和唢呐是吹管乐器。"},{id:"cs-9741",module:"changshi",prompt:"二胡属于哪类民族乐器？",options:["拉弦乐器", "弹拨乐器", "吹管乐器", "打击乐器"],answer:0,explanation:"二胡以弓拉弦发声，属于拉弦乐器，音色柔美，代表曲目有二泉映月。"},{id:"cs-9742",module:"changshi",prompt:"中国古代编钟主要用于什么场合？",options:["宫廷礼乐", "民间娱乐", "军事", "农业"],answer:0,explanation:"编钟是古代宫廷礼乐重器，曾侯乙编钟是最著名的代表，音律完备。"},{id:"cs-9743",module:"changshi",prompt:"中国十大名曲中高山流水与谁有关？",options:["伯牙和钟子期", "嵇康", "孔子", "屈原"],answer:0,explanation:"高山流水讲述伯牙与钟子期知音相遇的故事，是古琴名曲。"},{id:"cs-9744",module:"changshi",prompt:"中国十大名曲中十面埋伏描写的是什么？",options:["垓下之战", "赤壁之战", "长平之战", "淝水之战"],answer:0,explanation:"十面埋伏是琵琶曲，描写楚汉垓下之战，气势磅礴。"},{id:"cs-9745",module:"changshi",prompt:"中国画中的题款和印章的作用是？",options:["补充画面内容和标识作者", "装饰", "遮盖", "无意义"],answer:0,explanation:"题款和印章是中国画的重要组成部分，补充画面内容、标识作者和增添文化韵味。"},{id:"cs-9746",module:"changshi",prompt:"中国画中的留白手法是指什么？",options:["以空白表现意境", "涂白", "留边", "空框"],answer:0,explanation:"留白是中国画的重要手法，以空白表现云水、天空等，营造意境，计白当黑。"},{id:"cs-9747",module:"changshi",prompt:"中国书法中颜体和柳体的特点是？",options:["颜体丰腴雄浑，柳体骨力劲健", "颜体纤细，柳体丰腴", "都纤细", "都丰腴"],answer:0,explanation:"颜真卿楷书丰腴雄浑，柳公权楷书骨力劲健，并称颜筋柳骨。"},{id:"cs-9748",module:"changshi",prompt:"中国书法中被称为天下第一行书的是？",options:["兰亭序", "祭侄文稿", "寒食帖", "伯远帖"],answer:0,explanation:"王羲之的兰亭序被誉为天下第一行书，颜真卿祭侄文稿为第二，苏轼寒食帖为第三。"},{id:"cs-9749",module:"changshi",prompt:"中国篆刻艺术的主要材料是？",options:["印石", "木头", "金属", "竹子"],answer:0,explanation:"篆刻以印石如寿山石、青田石为主要材料，刻制印章，是书法与雕刻的结合。"},{id:"cs-9750",module:"changshi",prompt:"中国画中的白描技法是指什么？",options:["单线勾勒不设色", "浓墨渲染", "重彩", "泼墨"],answer:0,explanation:"白描以单线勾勒物象轮廓，不设色彩，讲究线条的表现力，如八十七神仙卷。"},{id:"cs-9751",module:"changshi",prompt:"中国戏曲中的虚拟性是指什么？",options:["以动作暗示环境和物体", "布景真实", "道具齐全", "写实表演"],answer:0,explanation:"戏曲虚拟性以演员动作暗示环境，如以马鞭代马、以桨代船，是中国戏曲的美学特征。"},{id:"cs-9752",module:"changshi",prompt:"中国戏曲中的程式化是指什么？",options:["表演动作有固定规范", "随意表演", "即兴发挥", "自由创作"],answer:0,explanation:"戏曲程式化指表演动作有固定规范，如起霸、走边、趟马等，是长期艺术积累。"},{id:"cs-9753",module:"changshi",prompt:"中国皮影戏的主要材料是？",options:["兽皮", "纸", "布", "木头"],answer:0,explanation:"皮影戏以兽皮如驴皮、牛皮雕刻人物，灯光照射投影表演，是古老的民间艺术。"},{id:"cs-9754",module:"changshi",prompt:"世界历史中被称为航海家的是哪位葡萄牙人？",options:["亨利王子", "麦哲伦", "达伽马", "哥伦布"],answer:0,explanation:"葡萄牙亨利王子创办航海学校，推动大航海时代开启，被称为航海家。"},{id:"cs-9755",module:"changshi",prompt:"首次完成环球航行的航海家是？",options:["麦哲伦", "哥伦布", "达伽马", "迪亚士"],answer:0,explanation:"麦哲伦船队于一五一九至一五二二年完成首次环球航行，证明地圆说。"},{id:"cs-9756",module:"changshi",prompt:"发现美洲新大陆的航海家是？",options:["哥伦布", "麦哲伦", "达伽马", "库克"],answer:0,explanation:"哥伦布一四九二年横渡大西洋到达美洲，开启了欧洲对美洲的殖民。"},{id:"cs-9757",module:"changshi",prompt:"开辟通往印度新航路的航海家是？",options:["达伽马", "哥伦布", "麦哲伦", "迪亚士"],answer:0,explanation:"达伽马一四九八年绕过好望角到达印度，开辟了欧亚新航路。"},{id:"cs-9758",module:"changshi",prompt:"文艺复兴的发源地是？",options:["意大利", "法国", "英国", "德国"],answer:0,explanation:"文艺复兴十四世纪发源于意大利佛罗伦萨，随后扩展到欧洲各地。"},{id:"cs-9759",module:"changshi",prompt:"文艺复兴的代表人物不包括？",options:["牛顿", "但丁", "达芬奇", "米开朗基罗"],answer:0,explanation:"但丁、达芬奇、米开朗基罗是文艺复兴代表人物，牛顿是科学家但属稍后时期。"},{id:"cs-9760",module:"changshi",prompt:"提出日心说的天文学家是？",options:["哥白尼", "托勒密", "伽利略", "开普勒"],answer:0,explanation:"哥白尼一五四三年发表天体运行论，提出日心说，动摇了地心说。"},{id:"cs-9761",module:"changshi",prompt:"发明蒸汽机的改良者是？",options:["瓦特", "牛顿", "爱迪生", "法拉第"],answer:0,explanation:"瓦特改良蒸汽机，使其广泛应用于工业，推动了第一次工业革命。"},{id:"cs-9762",module:"changshi",prompt:"发现美洲新大陆的航海家哥伦布是哪国人？",options:["意大利", "西班牙", "葡萄牙", "英国"],answer:0,explanation:"哥伦布是意大利热那亚人，在西班牙王室资助下发现美洲。"},{id:"cs-9763",module:"changshi",prompt:"英国工业革命的标志性发明是？",options:["珍妮纺纱机", "蒸汽机车", "电灯", "汽车"],answer:0,explanation:"珍妮纺纱机一七六五年发明，标志着英国工业革命的开始。"},{id:"cs-9764",module:"changshi",prompt:"美国独立战争的领导人是？",options:["华盛顿", "林肯", "罗斯福", "杰斐逊"],answer:0,explanation:"华盛顿领导美国独立战争，成为美国首任总统，被称为国父。"},{id:"cs-9765",module:"changshi",prompt:"法国大革命的爆发时间是？",options:["一七八九年", "一七七六年", "一八四八年", "一八七一年"],answer:0,explanation:"一七八九年七月十四日巴黎民众攻占巴士底狱，法国大革命爆发。"},{id:"cs-9766",module:"changshi",prompt:"拿破仑帝国灭亡的标志是？",options:["滑铁卢战役", "奥斯特里茨战役", "土伦战役", "莫斯科战役"],answer:0,explanation:"一八一五年滑铁卢战役拿破仑战败，被流放圣赫勒拿岛，帝国灭亡。"},{id:"cs-9767",module:"changshi",prompt:"美国南北战争的领导人是？",options:["林肯", "华盛顿", "罗斯福", "杜鲁门"],answer:0,explanation:"林肯领导美国南北战争，废除奴隶制，维护了国家统一。"},{id:"cs-9768",module:"changshi",prompt:"俄国农奴制改革的沙皇是？",options:["亚历山大二世", "彼得一世", "叶卡捷琳娜二世", "尼古拉二世"],answer:0,explanation:"一八六一年亚历山大二世颁布废除农奴制法令，推动俄国近代化。"},{id:"cs-9769",module:"changshi",prompt:"日本明治维新的时间是？",options:["一八六八年", "一八五三年", "一八九四年", "一九零五年"],answer:0,explanation:"一八六八年日本开始明治维新，学习西方，走上资本主义道路。"},{id:"cs-9770",module:"changshi",prompt:"第二次世界大战的交战双方是？",options:["轴心国和同盟国", "同盟国和协约国", "北约和华约", "欧盟和非盟"],answer:0,explanation:"第二次世界大战中德意日组成轴心国，中美英苏等组成同盟国。"},{id:"cs-9771",module:"changshi",prompt:"古巴革命的领导人是？",options:["卡斯特罗", "切格瓦拉", "庇隆", "皮诺切特"],answer:0,explanation:"卡斯特罗领导古巴革命，一九五九年推翻巴蒂斯塔政权，建立社会主义国家。"},{id:"cs-9772",module:"changshi",prompt:"印度独立的领导人是？",options:["甘地", "尼赫鲁", "真纳", "鲍斯"],answer:0,explanation:"甘地领导非暴力不合作运动，尼赫鲁成为印度首任总理。"},{id:"cs-9773",module:"changshi",prompt:"南非种族隔离制度的废除者是？",options:["曼德拉", "图图", "姆贝基", "祖马"],answer:0,explanation:"曼德拉领导反种族隔离斗争，一九九四年当选南非首位黑人总统。"},{id:"cs-9774",module:"changshi",prompt:"联合国首任秘书长是？",options:["赖伊", "吴丹", "安南", "加利"],answer:0,explanation:"挪威人特里格韦赖伊是联合国首任秘书长，任期为1946至1952年。"},{id:"cs-9775",module:"changshi",prompt:"万隆会议的发起国包括印度和？",options:["印度尼西亚", "埃及", "南斯拉夫", "中国"],answer:0,explanation:"万隆会议由印度、印度尼西亚、缅甸、锡兰和巴基斯坦五国发起。"},{id:"cs-9776",module:"changshi",prompt:"不结盟运动的创始人是？",options:["尼赫鲁、铁托、纳赛尔", "卡斯特罗、曼德拉、甘地", "毛泽东、胡志明、金日成", "戴高乐、阿登纳、艾登"],answer:0,explanation:"不结盟运动由印度尼赫鲁、南斯拉夫铁托和埃及纳赛尔等发起。"},{id:"cs-9777",module:"changshi",prompt:"去除衣服上的口香糖的有效方法是？",options:["用冰块冷冻后剥离", "用热水泡", "用吹风机吹", "用醋泡"],answer:0,explanation:"口香糖遇冷变硬易剥离，用冰块冷冻后轻轻剥离即可，再用酒精清除残留。"},{id:"cs-9778",module:"changshi",prompt:"去除冰箱异味的天然方法是？",options:["放柚子皮或活性炭", "放洋葱", "放香水", "放肥皂"],answer:0,explanation:"柚子皮和活性炭能吸附异味，是冰箱除味的天然方法，需定期更换。"},{id:"cs-9779",module:"changshi",prompt:"防止切洋葱流泪的方法是？",options:["先冷藏再切", "戴墨镜", "闭眼切", "用热水泡"],answer:0,explanation:"洋葱冷藏后刺激性物质挥发减少，切时不易流泪，也可用锋利刀具减少细胞破坏。"},{id:"cs-9780",module:"changshi",prompt:"快速剥鸡蛋壳的方法是？",options:["煮后冷水浸泡", "趁热剥", "冷冻后剥", "用醋泡"],answer:0,explanation:"煮好的鸡蛋放入冷水浸泡，蛋壳膜收缩，更容易剥壳。"},{id:"cs-9781",module:"changshi",prompt:"去除水壶水垢的方法是？",options:["用白醋煮洗", "用洗洁精", "用钢丝球", "用盐水"],answer:0,explanation:"白醋中的醋酸能溶解水垢，煮洗后冲洗干净即可，安全有效。"},{id:"cs-9782",module:"changshi",prompt:"防止米饭粘锅的方法是？",options:["煮前浸泡米并加少许油", "多加水", "少加水", "不盖盖"],answer:0,explanation:"米浸泡后吸水均匀，加少许油可防粘锅，米饭更松软。"},{id:"cs-9783",module:"changshi",prompt:"去除鞋子异味的简单方法是？",options:["放茶包或小苏打", "喷香水", "晒太阳", "放报纸"],answer:0,explanation:"茶包和小苏打能吸附鞋内湿气和异味，是简单有效的除臭方法。"},{id:"cs-9784",module:"changshi",prompt:"清洁键盘缝隙灰尘的方法是？",options:["用软毛刷或压缩空气", "用水冲", "用湿布擦", "用吸尘器大功率"],answer:0,explanation:"键盘缝隙灰尘可用软毛刷或压缩空气清理，避免液体进入损坏电路。"},{id:"cs-9785",module:"changshi",prompt:"去除衣服褶皱的应急方法是？",options:["用吹风机吹或挂浴室蒸汽", "用水洗", "用熨斗直接烫", "用手拉"],answer:0,explanation:"吹风机热风或浴室蒸汽可使纤维松弛，减少褶皱，是应急的好方法。"},{id:"cs-9786",module:"changshi",prompt:"防止银饰变黑的方法是？",options:["密封保存并远离硫化物", "泡水", "暴晒", "与橡胶放一起"],answer:0,explanation:"银与硫化物反应变黑，密封保存可减缓氧化，已变黑可用擦银布处理。"},{id:"cs-9787",module:"changshi",prompt:"清洁毛绒玩具的方法是？",options:["用洗衣袋装好轻柔机洗或干洗", "直接水洗", "暴晒", "用酒精擦"],answer:0,explanation:"毛绒玩具应装入洗衣袋轻柔机洗或干洗，避免变形和掉毛。"},{id:"cs-9788",module:"changshi",prompt:"去除砧板异味的方法是？",options:["用柠檬或盐搓洗", "用洗洁精泡", "用热水烫", "用醋泡"],answer:0,explanation:"柠檬酸和盐粒能去除砧板异味和污渍，洗后晾干防霉。"},{id:"cs-9789",module:"changshi",prompt:"防止镜子起雾的方法是？",options:["涂抹肥皂水再擦干", "贴保鲜膜", "用热水冲", "用吹风机吹"],answer:0,explanation:"镜面涂抹肥皂水后擦干，形成保护膜，洗澡时不易起雾。"},{id:"cs-9790",module:"changshi",prompt:"去除地毯毛发的方法是？",options:["用橡胶手套或静电刷", "用吸尘器", "用水冲", "用胶带"],answer:0,explanation:"橡胶手套摩擦产生静电，聚拢地毯毛发，配合静电刷效果更好。"},{id:"cs-9791",module:"changshi",prompt:"去除衣物静电的方法是？",options:["使用柔顺剂或喷水", "多穿化纤", "干燥环境", "摩擦"],answer:0,explanation:"柔顺剂减少纤维摩擦，喷水增加湿度，可有效减少静电。"},{id:"cs-9792",module:"changshi",prompt:"清洁百叶窗的方法是？",options:["用旧袜子或手套套手擦拭", "用水冲", "用吸尘器", "用湿布逐片擦"],answer:0,explanation:"旧袜子或手套套手，一次擦拭多片百叶窗，高效省力。"},{id:"cs-9793",module:"changshi",prompt:"去除微波炉异味的方法是？",options:["放柠檬水加热", "放咖啡渣", "放茶叶", "放橘子皮"],answer:0,explanation:"柠檬水加热产生蒸汽，去除微波炉异味并软化油污，一举两得。"},{id:"cs-9794",module:"changshi",prompt:"防止衣物褪色的方法是？",options:["翻面洗涤并避免暴晒", "热水洗", "暴晒", "用漂白剂"],answer:0,explanation:"翻面洗涤、冷水洗和阴干可减少褪色，深色衣物应避免暴晒。"},{id:"cs-9795",module:"changshi",prompt:"去除地板划痕的方法是？",options:["用核桃仁擦拭或专用修复笔", "用砂纸磨", "用蜡笔涂", "不处理"],answer:0,explanation:"核桃仁油脂能填充浅划痕，专用修复笔可遮盖较深划痕。"},{id:"cs-9796",module:"changshi",prompt:"清洁沙发缝隙的方法是？",options:["用胶带粘或吸尘器小吸头", "用水冲", "用湿布", "用刷子"],answer:0,explanation:"胶带可粘出沙发缝隙的碎屑，吸尘器小吸头能深入清理。"},{id:"cs-9797",module:"changshi",prompt:"去除茶杯茶渍的方法是？",options:["用小苏打或牙膏", "用洗洁精", "用钢丝球", "用醋泡"],answer:0,explanation:"小苏打和牙膏的微粒能去除茶渍，不损伤杯面，安全有效。"},{id:"cs-9798",module:"changshi",prompt:"防止菜板发霉的方法是？",options:["洗后立放晾干并定期盐搓", "泡水", "盖布", "不洗"],answer:0,explanation:"菜板洗后立放晾干，定期用盐搓洗，可防止霉菌滋生。"},{id:"cs-9799",module:"changshi",prompt:"清洁窗户玻璃的方法是？",options:["用报纸或玻璃刮", "用干布", "用湿布", "用纸巾"],answer:0,explanation:"报纸纤维细腻，配合玻璃刮使用，玻璃透亮无水痕。"},{id:"cs-9800",module:"changshi",prompt:"去除冰箱结冰的方法是？",options:["断电自然融化", "用刀撬", "用热水浇", "用吹风机吹"],answer:0,explanation:"冰箱结冰应断电自然融化，避免用尖锐工具损伤内壁。"},{id:"cs-9801",module:"changshi",prompt:"清洁油烟机滤网的方法是？",options:["用碱性清洁剂浸泡", "用冷水冲", "用干布擦", "用醋喷"],answer:0,explanation:"碱性清洁剂能皂化油污，热水浸泡后刷洗，效果显著。"},{id:"cs-9802",module:"changshi",prompt:"防止衣物起球的方法是？",options:["翻面装袋轻柔洗", "与粗糙衣物混洗", "高温机洗", "用力搓"],answer:0,explanation:"翻面和洗衣袋减少摩擦，轻柔洗涤降低纤维纠缠，可减缓起球。"},{id:"cs-9803",module:"changshi",prompt:"清洁手机屏幕的方法是？",options:["用超细纤维布轻擦", "用酒精大量喷", "用纸巾干擦", "用水冲"],answer:0,explanation:"超细纤维布能去除指纹油污且不划伤屏幕，避免液体渗入损坏元件。"},{id:"cs-9804",module:"changshi",prompt:"现代奥林匹克运动会的创始人是？",options:["顾拜旦", "萨马兰奇", "罗格", "巴赫"],answer:0,explanation:"法国教育家顾拜旦倡导复兴奥运会，一八九六年首届现代奥运会在雅典举行。"},{id:"cs-9805",module:"changshi",prompt:"奥运会五环的颜色是？",options:["蓝黄黑绿红", "红黄蓝绿黑", "蓝白黑绿红", "黄绿蓝黑红"],answer:0,explanation:"五环为蓝黄黑绿红五色，象征五大洲团结，白色背景为底。"},{id:"cs-9806",module:"changshi",prompt:"中国首枚奥运金牌获得者是？",options:["许海峰", "李宁", "刘翔", "姚明"],answer:0,explanation:"许海峰一九八四年洛杉矶奥运会夺得男子手枪慢射金牌，实现中国奥运金牌零的突破。"},{id:"cs-9807",module:"changshi",prompt:"世界杯足球赛每几年举办一次？",options:["四年", "两年", "三年", "五年"],answer:0,explanation:"世界杯足球赛每四年举办一次，由国际足联主办，是全球最受关注的赛事。"},{id:"cs-9808",module:"changshi",prompt:"NBA的中文全称是？",options:["美国职业篮球联赛", "美国足球联赛", "国际篮联", "世界篮球联赛"],answer:0,explanation:"NBA是美国职业篮球联赛的缩写，是全球最高水平的篮球联赛。"},{id:"cs-9809",module:"changshi",prompt:"足球比赛中每队上场人数为？",options:["十一人", "十人", "十二人", "九人"],answer:0,explanation:"足球比赛每队上场十一人，包括一名守门员，比赛分上下半场各四十五分钟。"},{id:"cs-9810",module:"changshi",prompt:"篮球比赛中每队上场人数为？",options:["五人", "六人", "七人", "四人"],answer:0,explanation:"篮球比赛每队上场五人，比赛分四节，每节十分钟。"},{id:"cs-9811",module:"changshi",prompt:"排球比赛中每队上场人数为？",options:["六人", "五人", "七人", "四人"],answer:0,explanation:"排球比赛每队上场六人，分前排和后排，轮转换位。"},{id:"cs-9812",module:"changshi",prompt:"乒乓球比赛每局多少分？",options:["十一分", "二十一分", "十五分", "二十五分"],answer:0,explanation:"乒乓球每局十一分，需领先两分获胜，五局三胜或七局四胜。"},{id:"cs-9813",module:"changshi",prompt:"羽毛球比赛每局多少分？",options:["二十一分", "十一分", "十五分", "二十五分"],answer:0,explanation:"羽毛球每局二十一分，需领先两分获胜，三局两胜制。"},{id:"cs-9814",module:"changshi",prompt:"网球大满贯包括哪四项赛事？",options:["澳网、法网、温网、美网", "中网、法网、温网、美网", "澳网、中网、温网、美网", "澳网、法网、中网、美网"],answer:0,explanation:"网球大满贯为澳大利亚公开赛、法国公开赛、温布尔登和美国公开赛。"},{id:"cs-9815",module:"changshi",prompt:"马拉松比赛的全长是？",options:["四十二点一九五公里", "四十公里", "四十五公里", "五十公里"],answer:0,explanation:"马拉松全长四十二点一九五公里，源于古希腊传令兵的故事。"},{id:"cs-9816",module:"changshi",prompt:"体操比赛中平衡木的长度是？",options:["五米", "三米", "七米", "十米"],answer:0,explanation:"平衡木长五米、宽十厘米，高一点二五米，是女子体操项目。"},{id:"cs-9817",module:"changshi",prompt:"举重比赛中抓举和挺举的区别是？",options:["抓举一次完成，挺举分两步", "抓举分两步，挺举一次", "无区别", "抓举更重"],answer:0,explanation:"抓举要求一次连续动作将杠铃举过头顶，挺举分提铃和上挺两步。"},{id:"cs-9818",module:"changshi",prompt:"击剑比赛的三种剑是？",options:["花剑、重剑、佩剑", "长剑、短剑、弯刀", "军刀、刺剑、弯刀", "花剑、长剑、佩剑"],answer:0,explanation:"击剑分为花剑、重剑和佩剑三种，规则和有效部位各不相同。"},{id:"cs-9819",module:"changshi",prompt:"跆拳道比赛中的得分部位是？",options:["躯干和头部", "四肢", "背部", "全身"],answer:0,explanation:"跆拳道得分部位为躯干护具和头部，踢击准确有力才能得分。"},{id:"cs-9820",module:"changshi",prompt:"柔道比赛中获胜的最高等级是？",options:["一本", "技有", "效果", "得分"],answer:0,explanation:"柔道中一本为最高获胜等级，获得一本即获胜，技有和效果次之。"},{id:"cs-9821",module:"changshi",prompt:"自行车公路赛中最著名的赛事是？",options:["环法自行车赛", "环意大利赛", "环西班牙赛", "环中国赛"],answer:0,explanation:"环法自行车赛创办于一九零三年，是世界上最著名的自行车赛事。"},{id:"cs-9822",module:"changshi",prompt:"F1赛车比赛中，最快圈速的奖励是？",options:["积分奖励", "奖金", "奖杯", "荣誉"],answer:0,explanation:"F1比赛中创造最快圈速且排名前十的车手可获得额外积分奖励。"},{id:"cs-9823",module:"changshi",prompt:"围棋比赛的规则中，先手方是？",options:["黑方", "白方", "猜先", "轮流"],answer:0,explanation:"围棋规则中黑方先行，为平衡先手优势，黑方需贴目给白方。"},{id:"cs-9824",module:"changshi",prompt:"国际象棋中威力最大的棋子是？",options:["后", "车", "象", "马"],answer:0,explanation:"国际象棋中后是最强的棋子，可横竖斜任意方向移动。"},{id:"cs-9825",module:"changshi",prompt:"桥牌比赛中，定约由谁确定？",options:["叫牌最高者", "发牌者", "庄家", "裁判"],answer:0,explanation:"桥牌通过叫牌确定定约，叫牌最高者成为庄家，需完成定约才能得分。"},{id:"cs-9826",module:"changshi",prompt:"电子竞技中，英雄联盟的开发商是？",options:["拳头游戏", "暴雪", "Valve", "腾讯"],answer:0,explanation:"英雄联盟由美国拳头游戏开发，是全球最受欢迎的MOBA游戏之一。"},{id:"cs-9827",module:"changshi",prompt:"冬季奥运会举办地首次在中国的是？",options:["北京", "哈尔滨", "长春", "张家口"],answer:0,explanation:"二零二二年北京冬奥会是中国首次举办冬季奥运会，北京成为双奥之城。"},{id:"cs-9828",module:"changshi",prompt:"亚运会每几年举办一次？",options:["四年", "两年", "三年", "五年"],answer:0,explanation:"亚运会每四年举办一次，由亚洲奥林匹克理事会主办。"},{id:"cs-9829",module:"changshi",prompt:"全运会是中国什么性质的运动会？",options:["全国综合性运动会", "国际赛事", "青少年赛事", "单项赛事"],answer:0,explanation:"全运会是中国国内水平最高的综合性运动会，每四年举办一次。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9830",module:"changshi",prompt:"中国传统艺术知识：京剧的发源地是？",options:["北京", "安徽", "湖北", "上海"],answer:0,explanation:"京剧形成于清代北京，由徽班进京后融合徽调、汉调等演变而成。"},{id:"cs-9831",module:"changshi",prompt:"中国传统艺术知识：越剧的发源地是？",options:["浙江", "江苏", "上海", "安徽"],answer:0,explanation:"越剧发源于浙江嵊州，以柔美唱腔和女性演员著称，代表剧目有梁山伯与祝英台。"},{id:"cs-9832",module:"changshi",prompt:"文化艺术常识：黄梅戏的发源地是？",options:["安徽", "湖北", "江西", "湖南"],answer:0,explanation:"黄梅戏发源于湖北黄梅，发展壮大于安徽安庆，代表剧目有天仙配。"},{id:"cs-9833",module:"changshi",prompt:"下列说法正确的是：豫剧的发源地是？",options:["河南", "山东", "河北", "山西"],answer:0,explanation:"豫剧发源于河南，又称河南梆子，唱腔高亢激昂，代表剧目有花木兰。"},{id:"cs-9834",module:"changshi",prompt:"中国传统艺术知识：评剧的发源地是？",options:["河北", "辽宁", "天津", "山东"],answer:0,explanation:"评剧发源于河北唐山，流行于华北和东北，代表剧目有刘巧儿。"},{id:"cs-9835",module:"changshi",prompt:"下列说法正确的是：古琴有几根弦？",options:["七根", "五根", "六根", "四根"],answer:0,explanation:"古琴有七根弦，又称七弦琴，是中国最古老的弹拨乐器之一。"},{id:"cs-9836",module:"changshi",prompt:"中国传统艺术知识：进化论的提出者是？",options:["达尔文", "牛顿", "孟德尔", "巴斯德"],answer:0,explanation:"达尔文一八五九年发表物种起源，提出进化论，改变了人类对生命的认识。"},{id:"cs-9837",module:"changshi",prompt:"中国传统艺术知识：苏联的缔造者是？",options:["列宁", "斯大林", "赫鲁晓夫", "戈尔巴乔夫"],answer:0,explanation:"列宁领导十月革命，建立苏维埃政权，是苏联的缔造者。"},{id:"cs-9838",module:"changshi",prompt:"文化艺术常识：欧洲联盟的前身是？",options:["欧洲共同体", "北约", "华约", "联合国"],answer:0,explanation:"欧盟的前身是欧洲共同体，由欧洲煤钢共同体等发展而来，一九九三年成立。"},{id:"cs-9839",module:"changshi",prompt:"下列说法正确的是：清洁纱窗的方法是？",options:["用旧报纸或海绵蘸水擦", "拆下来洗", "用水冲", "用吸尘器"],answer:0,explanation:"旧报纸或海绵蘸水擦拭纱窗，去除灰尘，无需拆卸。"},{id:"cs-9840",module:"changshi",prompt:"文化艺术常识：奥林匹克格言是？",options:["更快更高更强更团结", "友谊第一", "超越自我", "团结拼搏"],answer:0,explanation:"奥林匹克格言为更快更高更强更团结，二零二一年加入更团结。"},{id:"cs-9841",module:"changshi",prompt:"中国传统节日中七夕节的主要习俗是？",options:["乞巧和观星", "赛龙舟", "赏月", "登高"],answer:0,explanation:"七夕节女子穿针乞巧、观星祈愿，源于牛郎织女的传说，被称为中国情人节。"},{id:"cs-9842",module:"changshi",prompt:"中国传统节日中重阳节的主要习俗是？",options:["登高和赏菊", "赛龙舟", "吃月饼", "放鞭炮"],answer:0,explanation:"重阳节九月初九，人们登高、赏菊、插茱萸，现也是老年节。"},{id:"cs-9843",module:"changshi",prompt:"中国传统节日中清明节的习俗是？",options:["扫墓和踏青", "赏月", "登高", "乞巧"],answer:0,explanation:"清明节人们扫墓祭祖、踏青郊游，兼具自然和人文两大内涵。"},{id:"cs-9844",module:"changshi",prompt:"中国传统节日中元宵节的习俗是？",options:["赏花灯和吃元宵", "赛龙舟", "登高", "乞巧"],answer:0,explanation:"元宵节正月十五，人们赏花灯、猜灯谜、吃元宵，是春节后的重要节日。"},{id:"cs-9845",module:"changshi",prompt:"中国传统节日中腊八节的习俗是？",options:["喝腊八粥", "赏月", "登高", "赛龙舟"],answer:0,explanation:"腊八节十二月初八，人们喝腊八粥、泡腊八蒜，标志着春节序幕拉开。"},{id:"cs-9846",module:"changshi",prompt:"中国传统节日中除夕的习俗是？",options:["守岁和吃年夜饭", "赏月", "登高", "乞巧"],answer:0,explanation:"除夕是农历年最后一天，家人团聚吃年夜饭、守岁，辞旧迎新。"},{id:"cs-9847",module:"changshi",prompt:"中国传统节日中春节的习俗是？",options:["贴春联、放鞭炮、拜年", "赏月", "登高", "乞巧"],answer:0,explanation:"春节是中国最重要的传统节日，贴春联、放鞭炮、拜年、发红包等习俗丰富。"},{id:"cs-9848",module:"changshi",prompt:"中国传统节日中端午节的习俗是？",options:["赛龙舟和吃粽子", "赏月", "登高", "乞巧"],answer:0,explanation:"端午节五月初五，人们赛龙舟、吃粽子、挂艾草，纪念屈原。"},{id:"cs-9849",module:"changshi",prompt:"中国传统节日中中秋节的习俗是？",options:["赏月和吃月饼", "赛龙舟", "登高", "乞巧"],answer:0,explanation:"中秋节八月十五，人们赏月、吃月饼，寓意团圆美满。"},{id:"cs-9850",module:"changshi",prompt:"二十四节气中立春的含义是？",options:["春季开始", "夏季开始", "秋季开始", "冬季开始"],answer:0,explanation:"立春是二十四节气之首，标志着春季开始，万物复苏。"},{id:"cs-9851",module:"changshi",prompt:"二十四节气中夏至的含义是？",options:["白昼最长", "白昼最短", "昼夜平分", "气温最高"],answer:0,explanation:"夏至日太阳直射北回归线，北半球白昼最长，但气温最高在之后。"},{id:"cs-9852",module:"changshi",prompt:"二十四节气中秋分的含义是？",options:["昼夜平分", "白昼最长", "白昼最短", "气温最高"],answer:0,explanation:"秋分日太阳直射赤道，全球昼夜平分，此后北半球昼短夜长。"},{id:"cs-9853",module:"changshi",prompt:"二十四节气中冬至的含义是？",options:["白昼最短", "白昼最长", "昼夜平分", "气温最低"],answer:0,explanation:"冬至日太阳直射南回归线，北半球白昼最短，民间有冬至大如年的说法。"},{id:"cs-9854",module:"changshi",prompt:"二十四节气中惊蛰的含义是？",options:["春雷惊醒蛰伏昆虫", "降雨增多", "气温最高", "降雪"],answer:0,explanation:"惊蛰时春雷始鸣，惊醒蛰伏的昆虫，标志着仲春开始。"},{id:"cs-9855",module:"changshi",prompt:"二十四节气中芒种的含义是？",options:["有芒作物成熟", "降雨最多", "气温最高", "降雪"],answer:0,explanation:"芒种时麦类等有芒作物成熟，是农业生产的重要节气。"},{id:"cs-9856",module:"changshi",prompt:"二十四节气中霜降的含义是？",options:["初霜出现", "降雨最多", "气温最高", "降雪"],answer:0,explanation:"霜降是秋季最后一个节气，初霜出现，天气渐冷。"},{id:"cs-9857",module:"changshi",prompt:"二十四节气中小寒和大寒的含义是？",options:["一年中最冷的时段", "最热", "降雨最多", "降雪最多"],answer:0,explanation:"小寒和大寒是二十四节气中最冷的时段，民间有数九寒天的说法。"},{id:"cs-9858",module:"changshi",prompt:"二十四节气中谷雨的含义是？",options:["雨生百谷", "降雪", "气温最高", "白昼最长"],answer:0,explanation:"谷雨时降雨增多，利于谷物生长，是春季最后一个节气。"},{id:"cs-9859",module:"changshi",prompt:"二十四节气中小满的含义是？",options:["麦类作物籽粒开始饱满", "降雨最多", "气温最高", "降雪"],answer:0,explanation:"小满时北方麦类作物籽粒开始饱满但未成熟，故称小满。"},{id:"cs-9860",module:"changshi",prompt:"二十四节气中处暑的含义是？",options:["暑热渐退", "暑热最盛", "降雨最多", "降雪"],answer:0,explanation:"处暑意为暑热渐退，是秋季的第二个节气，天气转凉。"},{id:"cs-9861",module:"changshi",prompt:"中国传统民俗中贴春联的寓意是？",options:["迎祥纳福", "驱邪", "装饰", "纪念"],answer:0,explanation:"春联以工整对仗的文字表达美好祝愿，迎祥纳福，是春节的重要习俗。"},{id:"cs-9862",module:"changshi",prompt:"中国传统民俗中压岁钱的寓意是？",options:["压祟驱邪", "奖励", "储蓄", "装饰"],answer:0,explanation:"压岁钱谐音压祟，寓意驱邪保平安，是长辈对晚辈的祝福。"},{id:"cs-9863",module:"changshi",prompt:"中国传统民俗中舞龙舞狮的寓意是？",options:["祈求风调雨顺", "娱乐", "竞技", "纪念"],answer:0,explanation:"龙和狮是祥瑞象征，舞龙舞狮祈求风调雨顺、国泰民安。"},{id:"cs-9864",module:"changshi",prompt:"中国传统民俗中放风筝的寓意是？",options:["放走晦气", "娱乐", "竞技", "纪念"],answer:0,explanation:"古人认为放风筝可放走晦气，剪断风筝线寓意去除疾病和灾祸。"},{id:"cs-9865",module:"changshi",prompt:"中国传统民俗中挂艾草的寓意是？",options:["驱邪避瘟", "装饰", "食用", "药用"],answer:0,explanation:"端午节挂艾草和菖蒲，寓意驱邪避瘟，保佑家人健康。"},{id:"cs-9866",module:"changshi",prompt:"中国传统民俗中吃年夜饭的寓意是？",options:["团圆和辞旧迎新", "庆祝丰收", "纪念祖先", "驱邪"],answer:0,explanation:"年夜饭是除夕家人团聚的重要仪式，寓意团圆和辞旧迎新。"},{id:"cs-9867",module:"changshi",prompt:"中国传统民俗中守岁的寓意是？",options:["辞旧迎新", "娱乐", "守财", "纪念"],answer:0,explanation:"守岁是除夕夜不睡觉迎接新年，寓意辞旧迎新、祈求长寿。"},{id:"cs-9868",module:"changshi",prompt:"中国传统民俗中拜年的寓意是？",options:["祝贺新年", "娱乐", "竞技", "纪念"],answer:0,explanation:"拜年是春节向长辈和亲友祝贺新年的礼仪，表达美好祝愿。"},{id:"cs-9869",module:"changshi",prompt:"心肺复苏的按压频率是多少？",options:["每分钟一百至一百二十次", "每分钟六十次", "每分钟一百五十次", "每分钟四十次"],answer:0,explanation:"心肺复苏胸外按压频率为每分钟一百至一百二十次，深度五至六厘米。"},{id:"cs-9870",module:"changshi",prompt:"心肺复苏与人工呼吸的比例是多少？",options:["三十比二", "十五比一", "十比一", "二十比三"],answer:0,explanation:"单人施救时胸外按压与人工呼吸比例为三十比二，循环进行。"},{id:"cs-9871",module:"changshi",prompt:"海姆立克急救法适用于什么情况？",options:["气道异物梗阻", "心脏骤停", "骨折", "烧伤"],answer:0,explanation:"海姆立克法通过冲击腹部产生气流，排出气道异物，是窒息急救的关键方法。"},{id:"cs-9872",module:"changshi",prompt:"烫伤后的正确处理方法是？",options:["冷水冲洗降温", "涂牙膏", "涂酱油", "挑破水泡"],answer:0,explanation:"烫伤应立即用冷水冲洗十五分钟以上降温，切勿涂牙膏酱油或挑破水泡。"},{id:"cs-9873",module:"changshi",prompt:"流鼻血的正确处理方法是？",options:["低头捏鼻翼止血", "仰头", "塞纸团", "抬手"],answer:0,explanation:"流鼻血应低头捏住鼻翼十分钟止血，仰头会使血液流入咽喉，应避免。"},{id:"cs-9874",module:"changshi",prompt:"触电急救的第一步是？",options:["切断电源", "直接拉拽", "浇水", "人工呼吸"],answer:0,explanation:"触电急救应先切断电源或用干燥木棍挑开电线，切勿直接拉拽伤者。"},{id:"cs-9875",module:"changshi",prompt:"溺水者救上岸后的首要措施是？",options:["清理口鼻异物并判断呼吸", "控水", "人工呼吸", "胸外按压"],answer:0,explanation:"溺水者救上岸应先清理口鼻异物、判断呼吸脉搏，无呼吸立即心肺复苏。"},{id:"cs-9876",module:"changshi",prompt:"骨折后的正确处理方法是？",options:["固定制动并就医", "揉搓", "热敷", "随意搬动"],answer:0,explanation:"骨折应用夹板或木板固定制动，避免随意搬动加重损伤，尽快就医。"},{id:"cs-9877",module:"changshi",prompt:"被犬咬伤后的处理方法是？",options:["肥皂水冲洗并接种疫苗", "包扎", "涂药", "观察"],answer:0,explanation:"被犬咬伤应用肥皂水和流动清水冲洗十五分钟，尽快接种狂犬疫苗。"},{id:"cs-9878",module:"changshi",prompt:"异物入眼的正确处理方法是？",options:["眨眼或用清水冲洗", "揉眼", "用纸擦", "闭眼"],answer:0,explanation:"异物入眼应眨眼让泪水冲出或用清水冲洗，切勿揉眼以免损伤角膜。"},{id:"cs-9879",module:"changshi",prompt:"煤气中毒的急救措施是？",options:["移至通风处并保持呼吸畅通", "喂水", "保暖", "人工呼吸"],answer:0,explanation:"煤气中毒应立即移至通风处，解开衣领保持呼吸畅通，严重者及时就医。"},{id:"cs-9880",module:"changshi",prompt:"蛇咬伤的处理方法是？",options:["保持冷静并尽快就医", "奔跑", "用嘴吸毒", "扎紧不放松"],answer:0,explanation:"蛇咬伤应保持冷静减少活动，用宽布条适度绑扎并尽快就医，切勿奔跑。"},{id:"cs-9881",module:"changshi",prompt:"心脏骤停的黄金抢救时间是？",options:["四分钟内", "十分钟内", "半小时内", "一小时内"],answer:0,explanation:"心脏骤停后四分钟内进行心肺复苏，存活率最高，称为黄金四分钟。"},{id:"cs-9882",module:"changshi",prompt:"癫痫发作时的正确处理是？",options:["移开危险物并侧卧", "按住肢体", "塞东西入口", "掐人中"],answer:0,explanation:"癫痫发作应移开周围危险物、头侧向一边防窒息，切勿按住肢体或塞东西入口。"},{id:"cs-9883",module:"changshi",prompt:"低血糖的处理方法是？",options:["补充糖分", "喝水", "休息", "运动"],answer:0,explanation:"低血糖应立即补充糖水、糖果或果汁，症状缓解后进食，糖尿病患者应监测血糖。"},{id:"cs-9884",module:"changshi",prompt:"高血压急症的表现是？",options:["剧烈头痛、呕吐、视物模糊", "轻微头晕", "偶尔心慌", "轻度疲劳"],answer:0,explanation:"高血压急症表现为剧烈头痛、呕吐、视物模糊等，应立即就医。"},{id:"cs-9885",module:"changshi",prompt:"脑卒中的识别方法是？",options:["看脸、查胳膊、听说话", "测体温", "量血压", "数脉搏"],answer:0,explanation:"脑卒中识别口诀为看脸是否对称、查胳膊是否无力、听说话是否清晰，发现异常立即就医。"},{id:"cs-9886",module:"changshi",prompt:"糖尿病的典型症状是？",options:["多饮、多食、多尿、体重下降", "发热", "咳嗽", "腹泻"],answer:0,explanation:"糖尿病典型症状为三多一少，即多饮、多食、多尿和体重下降。"},{id:"cs-9887",module:"changshi",prompt:"哮喘发作时的处理方法是？",options:["使用支气管扩张剂并保持坐位", "平躺", "喝水", "运动"],answer:0,explanation:"哮喘发作应使用支气管扩张剂吸入，保持坐位放松，严重时立即就医。"},{id:"cs-9888",module:"changshi",prompt:"过敏反应的处理方法是？",options:["远离过敏原并服用抗过敏药", "继续接触", "热敷", "运动"],answer:0,explanation:"过敏反应应立即远离过敏原，服用抗过敏药，出现呼吸困难立即就医。"},{id:"cs-9889",module:"changshi",prompt:"食物中毒的处理方法是？",options:["催吐并就医", "继续进食", "剧烈运动", "大量饮水后不管"],answer:0,explanation:"食物中毒应立即停止进食、催吐并就医，保留样本以便检验。"},{id:"cs-9890",module:"changshi",prompt:"外伤出血的止血方法是？",options:["直接压迫止血", "用绳扎紧不放松", "涂药", "不处理"],answer:0,explanation:"外伤出血应用干净纱布直接压迫止血，四肢大出血可用止血带并记录时间。"},{id:"cs-9891",module:"changshi",prompt:"烧烫伤后水泡的处理方法是？",options:["不挑破，让其自然吸收", "立即挑破", "涂牙膏", "包紧"],answer:0,explanation:"烧烫伤水泡不应急于挑破，以免感染，应让其自然吸收或由医生处理。"},{id:"cs-9892",module:"changshi",prompt:"智能手机的操作系统主要包括？",options:["安卓和iOS", "Windows和Linux", "DOS和Unix", "Symbian"],answer:0,explanation:"目前主流智能手机操作系统为谷歌的安卓和苹果的iOS，鸿蒙等国产系统也在发展。"},{id:"cs-9893",module:"changshi",prompt:"手机电池的正确充电方式是？",options:["随用随充，避免过充过放", "完全放电再充", "整夜充电", "边玩边充"],answer:0,explanation:"锂电池随用随充即可，避免过度放电和长时间过充，有利于延长电池寿命。"},{id:"cs-9894",module:"changshi",prompt:"手机屏幕碎裂后的正确处理是？",options:["贴膜保护并尽快更换", "继续使用", "用水冲洗", "用胶带粘"],answer:0,explanation:"屏幕碎裂后应贴膜防止碎片划伤，并尽快更换，避免影响触控和进灰。"},{id:"cs-9895",module:"changshi",prompt:"手机进水后的正确处理是？",options:["立即关机并干燥处理", "开机检查", "充电", "甩干"],answer:0,explanation:"手机进水应立即关机、擦干表面、放入干燥剂或米缸，切勿开机或充电。"},{id:"cs-9896",module:"changshi",prompt:"手机辐射的强度与什么有关？",options:["信号强弱", "屏幕大小", "电池容量", "颜色"],answer:0,explanation:"手机信号弱时辐射增强，因为需要更大功率搜索信号，建议信号弱时少用手机。"},{id:"cs-9897",module:"changshi",prompt:"手机丢失后的正确做法是？",options:["挂失SIM卡并冻结支付账户", "不管它", "换手机", "报警后等待"],answer:0,explanation:"手机丢失应立即挂失SIM卡、冻结支付宝微信等支付账户，防止资金损失。"},{id:"cs-9898",module:"changshi",prompt:"手机支付的安全措施是？",options:["设置支付密码和指纹", "共享密码", "关闭支付验证", "借给他人"],answer:0,explanation:"手机支付应设置支付密码、指纹或面容识别，开启支付验证，保障资金安全。"},{id:"cs-9899",module:"changshi",prompt:"智能手表的主要功能不包括？",options:["做饭", "健康监测", "消息提醒", "运动记录"],answer:0,explanation:"智能手表具有健康监测、消息提醒、运动记录等功能，做饭不属于其功能。"},{id:"cs-9900",module:"changshi",prompt:"蓝牙技术的传输距离一般为？",options:["十米左右", "一百米", "一公里", "十公里"],answer:0,explanation:"蓝牙传输距离一般为十米左右，适合短距离设备连接，如耳机和音箱。"},{id:"cs-9901",module:"changshi",prompt:"WiFi的传输原理是？",options:["无线电波", "红外线", "激光", "声波"],answer:0,explanation:"WiFi通过无线电波传输数据，频率多为二点四吉赫和五吉赫频段。"},{id:"cs-9902",module:"changshi",prompt:"5G网络的主要特点是？",options:["高速率、低时延、大连接", "更耗电", "覆盖更差", "速度更慢"],answer:0,explanation:"5G网络具有高速率、低时延和大连接特点，支持自动驾驶和物联网等应用。"},{id:"cs-9903",module:"changshi",prompt:"云计算的核心优势是？",options:["按需使用、弹性扩展", "更贵", "更慢", "更安全"],answer:0,explanation:"云计算按需使用计算资源、弹性扩展，降低企业IT成本，是数字化基础。"},{id:"cs-9904",module:"changshi",prompt:"大数据的核心价值是？",options:["从数据中发现规律和价值", "存储", "传输", "加密"],answer:0,explanation:"大数据通过分析海量数据发现规律和价值，支持决策和创新。"},{id:"cs-9905",module:"changshi",prompt:"区块链的核心特点是？",options:["去中心化和不可篡改", "中心化", "可修改", "匿名"],answer:0,explanation:"区块链通过分布式账本实现去中心化和不可篡改，应用于数字货币和溯源等领域。"},{id:"cs-9906",module:"changshi",prompt:"手机导航的定位技术主要依靠？",options:["卫星定位", "基站", "WiFi", "蓝牙"],answer:0,explanation:"手机导航主要依靠GPS、北斗等卫星定位系统，结合基站和网络辅助定位。"},{id:"cs-9907",module:"changshi",prompt:"中国自主研发的卫星导航系统是？",options:["北斗", "GPS", "格洛纳斯", "伽利略"],answer:0,explanation:"北斗卫星导航系统是中国自主研发的全球卫星导航系统，已服务全球。"},{id:"cs-9908",module:"changshi",prompt:"手机拍照的像素越高越好吗？",options:["不一定，还取决于传感器和算法", "是", "否", "无关"],answer:0,explanation:"拍照质量取决于传感器尺寸、镜头质量和算法优化，像素只是因素之一。"},{id:"cs-9909",module:"changshi",prompt:"手机存储空间不足的解决方法是？",options:["清理缓存和卸载不用的应用", "删除系统文件", "降低分辨率", "换电池"],answer:0,explanation:"清理缓存、卸载不用的应用和转移文件可释放存储空间，不应删除系统文件。"},{id:"cs-9910",module:"changshi",prompt:"手机电池健康度下降的表现是？",options:["续航明显缩短", "充电更快", "信号更好", "屏幕更亮"],answer:0,explanation:"电池健康度下降表现为续航缩短、充电变慢，可查看电池健康度并考虑更换。"},{id:"cs-9911",module:"changshi",prompt:"手机发热的正确处理是？",options:["停止使用并散热", "放冰箱", "继续使用", "充电"],answer:0,explanation:"手机发热应停止使用、关闭后台应用并自然散热，避免损坏电池和元件。"},{id:"cs-9912",module:"changshi",prompt:"手机屏幕的刷新率是指？",options:["每秒刷新的次数", "分辨率", "亮度", "色彩数"],answer:0,explanation:"刷新率指屏幕每秒刷新的次数，如九十赫兹、一百二十赫兹，越高越流畅。"},{id:"cs-9913",module:"changshi",prompt:"手机NFC功能的主要用途是？",options:["近场支付和门禁", "充电", "拍照", "导航"],answer:0,explanation:"NFC近场通信用于移动支付、门禁卡和公交卡等，距离近、安全性高。"},{id:"cs-9914",module:"changshi",prompt:"手机语音助手的代表产品是？",options:["Siri和小爱同学", "微信", "支付宝", "淘宝"],answer:0,explanation:"Siri、小爱同学、小艺等是手机语音助手，通过语音完成操作和查询。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-9915",module:"changshi",prompt:"中国最大的淡水湖是？",options:["鄱阳湖", "洞庭湖", "太湖", "洪泽湖"],answer:0,explanation:"鄱阳湖位于江西省北部，是中国最大的淡水湖，面积随季节变化明显。"},{id:"cs-9916",module:"changshi",prompt:"中国最大的咸水湖是？",options:["青海湖", "纳木错", "察尔汗盐湖", "博斯腾湖"],answer:0,explanation:"青海湖位于青海省，面积约四千五百平方公里，是中国最大的咸水湖和内陆湖。"},{id:"cs-9917",module:"changshi",prompt:"中国最长的内流河是？",options:["塔里木河", "黑河", "疏勒河", "伊犁河"],answer:0,explanation:"塔里木河位于新疆塔里木盆地，全长约二千一百公里，是中国最长的内流河。"},{id:"cs-9918",module:"changshi",prompt:"中国海拔最高的湖泊是？",options:["纳木错", "青海湖", "喀纳斯湖", "长白山天池"],answer:0,explanation:"纳木错位于西藏，湖面海拔约四千七百一十八米，是世界上海拔最高的大型湖泊之一。"},{id:"cs-9919",module:"changshi",prompt:"中国最南端的城市是？",options:["三沙市", "三亚市", "湛江市", "海口市"],answer:0,explanation:"三沙市管辖西沙、中沙、南沙群岛，是中国最南端的城市。"},{id:"cs-9920",module:"changshi",prompt:"中国最大的自然保护区是？",options:["三江源自然保护区", "可可西里", "羌塘", "阿尔金山"],answer:0,explanation:"三江源自然保护区位于青海，面积约十五万平方公里，是中国最大的自然保护区。"},{id:"cs-9921",module:"changshi",prompt:"中国最大的淡水鱼产地是？",options:["长江", "黄河", "珠江", "黑龙江"],answer:0,explanation:"长江是中国最大的淡水鱼产地，有中华鲟、白鲟等珍稀物种。"},{id:"cs-9922",module:"changshi",prompt:"中国最大的煤炭产地是？",options:["山西", "内蒙古", "陕西", "新疆"],answer:0,explanation:"山西是中国最大的煤炭产地，储量丰富，有煤海之称。"},{id:"cs-9923",module:"changshi",prompt:"中国最大的钢铁基地是？",options:["鞍山", "上海", "武汉", "攀枝花"],answer:0,explanation:"鞍山位于辽宁，是中国最大的钢铁基地，有钢都之称。"},{id:"cs-9924",module:"changshi",prompt:"中国最大的造船基地是？",options:["上海", "大连", "广州", "南通"],answer:0,explanation:"上海是中国最大的造船基地，江南造船厂和沪东中华造船厂均位于此。"},{id:"cs-9925",module:"changshi",prompt:"中国最大的汽车生产基地是？",options:["长春", "上海", "武汉", "重庆"],answer:0,explanation:"长春是中国最大的汽车生产基地，一汽集团总部所在地。"},{id:"cs-9926",module:"changshi",prompt:"中国最大的航天发射基地是？",options:["酒泉", "西昌", "太原", "文昌"],answer:0,explanation:"酒泉卫星发射中心位于甘肃，是中国最早的航天发射基地，神舟飞船在此发射。"},{id:"cs-9927",module:"changshi",prompt:"中国最大的水电站是？",options:["三峡水电站", "白鹤滩水电站", "溪洛渡水电站", "向家坝水电站"],answer:0,explanation:"三峡水电站位于湖北宜昌，是世界上装机容量最大的水电站。"},{id:"cs-9928",module:"changshi",prompt:"中国最大的核电站是？",options:["秦山核电站", "大亚湾核电站", "田湾核电站", "红沿河核电站"],answer:0,explanation:"秦山核电站位于浙江海盐，是中国自行设计建造的第一座核电站，装机容量最大。"},{id:"cs-9929",module:"changshi",prompt:"中国最大的风电基地是？",options:["内蒙古", "新疆", "甘肃", "河北"],answer:0,explanation:"内蒙古是中国最大的风电基地，风能资源丰富，装机容量居全国首位。"},{id:"cs-9930",module:"changshi",prompt:"中国最大的光伏发电基地是？",options:["青海", "新疆", "甘肃", "宁夏"],answer:0,explanation:"青海是中国最大的光伏发电基地，太阳能资源丰富，龙羊峡水光互补项目著名。"},{id:"cs-9931",module:"changshi",prompt:"中国最大的高铁站是？",options:["北京南站", "上海虹桥站", "广州南站", "南京南站"],answer:0,explanation:"北京南站和上海虹桥站是中国最大的高铁站，规模和客流量均居前列。"},{id:"cs-9932",module:"changshi",prompt:"世界文化遗产雅典卫城位于哪个国家？",options:["希腊", "意大利", "土耳其", "埃及"],answer:0,explanation:"雅典卫城位于希腊雅典，是古希腊文明的象征，帕特农神庙是其核心建筑。"},{id:"cs-9933",module:"changshi",prompt:"世界文化遗产吴哥窟位于哪个国家？",options:["柬埔寨", "泰国", "越南", "老挝"],answer:0,explanation:"吴哥窟位于柬埔寨暹粒，是世界上最大的宗教建筑群之一。"},{id:"cs-9934",module:"changshi",prompt:"世界文化遗产马丘比丘位于哪个国家？",options:["秘鲁", "墨西哥", "巴西", "智利"],answer:0,explanation:"马丘比丘位于秘鲁安第斯山脉，是印加帝国的古城遗址，被称为失落之城。"},{id:"cs-9935",module:"changshi",prompt:"世界文化遗产佩特拉古城位于哪个国家？",options:["约旦", "埃及", "叙利亚", "黎巴嫩"],answer:0,explanation:"佩特拉古城位于约旦，是纳巴泰王国的都城，以玫瑰色岩石建筑著称。"},{id:"cs-9936",module:"changshi",prompt:"世界文化遗产泰姬陵位于哪个国家？",options:["印度", "巴基斯坦", "孟加拉国", "尼泊尔"],answer:0,explanation:"泰姬陵位于印度阿格拉，是莫卧儿皇帝沙贾汗为爱妻建造的白色大理石陵墓。"},{id:"cs-9937",module:"changshi",prompt:"世界文化遗产吴哥窟的建筑风格属于？",options:["高棉式", "泰式", "印度式", "缅式"],answer:0,explanation:"吴哥窟是高棉帝国建筑代表，以须弥山布局和精美浮雕著称。"},{id:"cs-9938",module:"changshi",prompt:"世界文化遗产圣托里尼岛位于哪个国家？",options:["希腊", "意大利", "西班牙", "葡萄牙"],answer:0,explanation:"圣托里尼岛位于希腊爱琴海，以蓝顶白墙建筑和火山景观著称。"},{id:"cs-9939",module:"changshi",prompt:"世界文化遗产圣彼得大教堂位于哪个国家？",options:["梵蒂冈", "意大利", "法国", "西班牙"],answer:0,explanation:"圣彼得大教堂位于梵蒂冈，是天主教最重要的教堂，米开朗基罗参与设计。"},{id:"cs-9940",module:"changshi",prompt:"世界文化遗产凡尔赛宫位于哪个国家？",options:["法国", "英国", "德国", "奥地利"],answer:0,explanation:"凡尔赛宫位于法国巴黎郊外，是法国王室的宫殿，以园林和镜厅著称。"},{id:"cs-9941",module:"changshi",prompt:"世界文化遗产白金汉宫位于哪个国家？",options:["英国", "法国", "德国", "荷兰"],answer:0,explanation:"白金汉宫位于英国伦敦，是英国君主的官邸，卫兵换岗仪式著名。"},{id:"cs-9942",module:"changshi",prompt:"世界文化遗产新天鹅堡位于哪个国家？",options:["德国", "奥地利", "瑞士", "法国"],answer:0,explanation:"新天鹅堡位于德国巴伐利亚，是迪士尼城堡的原型，由路德维希二世建造。"},{id:"cs-9943",module:"changshi",prompt:"世界文化遗产美泉宫位于哪个国家？",options:["奥地利", "德国", "法国", "捷克"],answer:0,explanation:"美泉宫位于奥地利维也纳，是哈布斯堡王朝的夏宫，以巴洛克园林著称。"},{id:"cs-9944",module:"changshi",prompt:"世界文化遗产克里姆林宫位于哪个国家？",options:["俄罗斯", "乌克兰", "白俄罗斯", "波兰"],answer:0,explanation:"克里姆林宫位于俄罗斯莫斯科，是俄罗斯总统府和历史建筑群。"},{id:"cs-9945",module:"changshi",prompt:"世界文化遗产圣瓦西里大教堂位于哪个城市？",options:["莫斯科", "圣彼得堡", "基辅", "明斯克"],answer:0,explanation:"圣瓦西里大教堂位于莫斯科红场，以色彩斑斓的洋葱头穹顶闻名。"},{id:"cs-9946",module:"changshi",prompt:"世界文化遗产圣索菲亚大教堂位于哪个城市？",options:["伊斯坦布尔", "雅典", "罗马", "开罗"],answer:0,explanation:"圣索菲亚大教堂位于土耳其伊斯坦布尔，是拜占庭建筑的巅峰之作。"},{id:"cs-9947",module:"changshi",prompt:"世界文化遗产蓝色清真寺位于哪个城市？",options:["伊斯坦布尔", "安卡拉", "开罗", "德黑兰"],answer:0,explanation:"蓝色清真寺位于土耳其伊斯坦布尔，以蓝色瓷砖装饰著称。"},{id:"cs-9948",module:"changshi",prompt:"世界文化遗产吉萨金字塔位于哪个国家？",options:["埃及", "苏丹", "墨西哥", "伊拉克"],answer:0,explanation:"吉萨金字塔位于埃及开罗郊外，是古埃及文明的象征，胡夫金字塔最大。"},{id:"cs-9949",module:"changshi",prompt:"世界文化遗产卢克索神庙位于哪个国家？",options:["埃及", "苏丹", "希腊", "土耳其"],answer:0,explanation:"卢克索神庙位于埃及卢克索，是古埃及新王国时期的神庙。"},{id:"cs-9950",module:"changshi",prompt:"世界文化遗产阿布辛贝神庙位于哪个国家？",options:["埃及", "苏丹", "埃塞俄比亚", "利比亚"],answer:0,explanation:"阿布辛贝神庙位于埃及阿斯旺，是拉美西斯二世建造的岩窟神庙。"},{id:"cs-9951",module:"changshi",prompt:"世界文化遗产奇琴伊察位于哪个国家？",options:["墨西哥", "秘鲁", "危地马拉", "巴西"],answer:0,explanation:"奇琴伊察位于墨西哥尤卡坦半岛，是玛雅文明的重要遗址。"},{id:"cs-9952",module:"changshi",prompt:"世界文化遗产蒂卡尔位于哪个国家？",options:["危地马拉", "墨西哥", "洪都拉斯", "萨尔瓦多"],answer:0,explanation:"蒂卡尔位于危地马拉，是玛雅文明的重要城市遗址。"},{id:"cs-9953",module:"changshi",prompt:"世界文化遗产复活节岛石像位于哪个国家？",options:["智利", "秘鲁", "阿根廷", "玻利维亚"],answer:0,explanation:"复活节岛石像位于智利复活节岛，是波利尼西亚文化的神秘遗产。"},{id:"cs-9954",module:"changshi",prompt:"世界文化遗产马丘比丘的建造者是？",options:["印加帝国", "阿兹特克", "玛雅", "托尔特克"],answer:0,explanation:"马丘比丘由印加帝国建造于十五世纪，是印加文化的杰出代表。"},{id:"cs-9955",module:"changshi",prompt:"世界文化遗产特奥蒂瓦坎位于哪个国家？",options:["墨西哥", "秘鲁", "危地马拉", "巴西"],answer:0,explanation:"特奥蒂瓦坎位于墨西哥，以太阳金字塔和月亮金字塔著称。"},{id:"cs-9956",module:"changshi",prompt:"世界文化遗产帕伦克位于哪个国家？",options:["墨西哥", "秘鲁", "危地马拉", "洪都拉斯"],answer:0,explanation:"帕伦克位于墨西哥恰帕斯州，是玛雅文明的重要遗址。"},{id:"cs-9957",module:"changshi",prompt:"世界文化遗产科潘位于哪个国家？",options:["洪都拉斯", "危地马拉", "墨西哥", "萨尔瓦多"],answer:0,explanation:"科潘位于洪都拉斯西部，是玛雅文明的重要城市遗址。"},{id:"cs-9958",module:"changshi",prompt:"世界文化遗产蒂亚瓦纳科位于哪个国家？",options:["玻利维亚", "秘鲁", "智利", "阿根廷"],answer:0,explanation:"蒂亚瓦纳科位于玻利维亚，是前印加文明的重要遗址。"},{id:"cs-9959",module:"changshi",prompt:"世界文化遗产昌昌古城位于哪个国家？",options:["秘鲁", "墨西哥", "智利", "厄瓜多尔"],answer:0,explanation:"昌昌古城位于秘鲁，是奇穆王国的都城，以土坯建筑著称。"},{id:"cs-9960",module:"changshi",prompt:"成年人每天建议饮水量是多少？",options:["一千五百至一千七百毫升", "五百毫升", "三升以上", "一升以下"],answer:0,explanation:"成年人每天建议饮水一千五百至一千七百毫升，约七至八杯，少量多次饮用。"},{id:"cs-9961",module:"changshi",prompt:"成年人每天建议睡眠时间是多少？",options:["七至九小时", "五小时", "十一小时", "四小时"],answer:0,explanation:"成年人每天建议睡眠七至九小时，充足睡眠有助于身体恢复和免疫力提升。"},{id:"cs-9962",module:"changshi",prompt:"成年人每天建议食盐摄入量是多少？",options:["不超过五克", "不超过十克", "不超过十五克", "不超过二十克"],answer:0,explanation:"世界卫生组织建议成年人每天食盐摄入量不超过五克，过量增加高血压风险。"},{id:"cs-9963",module:"changshi",prompt:"成年人每天建议食用油摄入量是多少？",options:["二十五至三十克", "五十克", "十克", "四十克"],answer:0,explanation:"成年人每天食用油摄入量建议二十五至三十克，过量增加肥胖和心血管疾病风险。"},{id:"cs-9964",module:"changshi",prompt:"成年人每天建议添加糖摄入量是多少？",options:["不超过二十五克", "不超过五十克", "不超过十克", "不超过一百克"],answer:0,explanation:"成年人每天添加糖摄入量建议不超过二十五克，过量增加肥胖和糖尿病风险。"},{id:"cs-9965",module:"changshi",prompt:"成年人每周建议运动时间是多少？",options:["一百五十分钟中等强度", "三十分钟", "五小时", "十分钟"],answer:0,explanation:"世界卫生组织建议成年人每周至少一百五十分钟中等强度有氧运动。"},{id:"cs-9966",module:"changshi",prompt:"成年人正常体质指数范围是？",options:["十八点五至二十三点九", "二十五以上", "十七以下", "三十以上"],answer:0,explanation:"体质指数BMI正常范围为十八点五至二十三点九，超过二十四为超重。"},{id:"cs-9967",module:"changshi",prompt:"成年人正常腰围男性应不超过？",options:["九十厘米", "一百厘米", "八十厘米", "一百一十厘米"],answer:0,explanation:"男性腰围应不超过九十厘米，女性不超过八十五厘米，超标增加代谢疾病风险。"},{id:"cs-9968",module:"changshi",prompt:"成年人正常体温范围是？",options:["三十六至三十七点二度", "三十八度以上", "三十五度以下", "三十九度以上"],answer:0,explanation:"成年人正常体温范围为三十六至三十七点二度，超过三十七点三度为发热。"},{id:"cs-9969",module:"changshi",prompt:"成年人正常呼吸频率是？",options:["十六至二十次每分钟", "三十次每分钟", "十次每分钟", "四十次每分钟"],answer:0,explanation:"成年人安静时呼吸频率正常范围为每分钟十六至二十次。"},{id:"cs-9970",module:"changshi",prompt:"成年人正常血压范围是？",options:["收缩压九十至一百三十九，舒张压六十至八十九毫米汞柱", "收缩压一百五十以上", "舒张压一百以上", "收缩压六十以下"],answer:0,explanation:"成年人正常血压为收缩压九十至一百三十九、舒张压六十至八十九毫米汞柱。"},{id:"cs-9971",module:"changshi",prompt:"成年人正常空腹血糖范围是？",options:["三点九至六点一毫摩尔每升", "七毫摩尔每升以上", "二毫摩尔每升", "十毫摩尔每升"],answer:0,explanation:"成年人空腹血糖正常范围为三点九至六点一毫摩尔每升，超过七点零提示糖尿病。"},{id:"cs-9972",module:"changshi",prompt:"成年人正常血脂中低密度脂蛋白应？",options:["低于三点四毫摩尔每升", "高于五毫摩尔每升", "高于八毫摩尔每升", "低于一毫摩尔每升"],answer:0,explanation:"低密度脂蛋白胆固醇俗称坏胆固醇，应低于三点四毫摩尔每升，过高增加动脉硬化风险。"},{id:"cs-9973",module:"changshi",prompt:"成年人正常尿酸男性应不超过？",options:["四百二十微摩尔每升", "五百微摩尔每升", "三百微摩尔每升", "六百微摩尔每升"],answer:0,explanation:"男性血尿酸应不超过四百二十微摩尔每升，女性不超过三百六十，过高增加痛风风险。"},{id:"cs-9974",module:"changshi",prompt:"成年人正常转氨酶ALT应不超过？",options:["四十单位每升", "一百单位每升", "十单位每升", "二百单位每升"],answer:0,explanation:"谷丙转氨酶ALT正常值不超过四十单位每升，升高提示肝细胞损伤。"},{id:"cs-9975",module:"changshi",prompt:"成年人正常肌酐男性应不超过？",options:["一百零六微摩尔每升", "二百微摩尔每升", "五十微摩尔每升", "三百微摩尔每升"],answer:0,explanation:"男性血肌酐应不超过一百零六微摩尔每升，升高提示肾功能减退。"},{id:"cs-9976",module:"changshi",prompt:"成年人正常视力标准是？",options:["一点零及以上", "零点八", "零点五", "零点三"],answer:0,explanation:"成年人正常视力标准为一点零及以上，低于一点零可能存在屈光不正。"},{id:"cs-9977",module:"changshi",prompt:"成年人正常听力标准是？",options:["二十五分贝以内", "四十分贝", "六十分贝", "八十分贝"],answer:0,explanation:"成年人正常听力为二十五分贝以内，超过四十分贝为中度听力损失。"},{id:"cs-9978",module:"changshi",prompt:"成年人正常肺活量男性应不低于？",options:["三千五百毫升", "二千毫升", "五千毫升", "一千毫升"],answer:0,explanation:"成年男性肺活量应不低于三千五百毫升，女性不低于二千五百毫升。"},{id:"cs-9979",module:"changshi",prompt:"成年人正常骨密度T值应不低于？",options:["负一点零", "负二点五", "负三点五", "正一点零"],answer:0,explanation:"骨密度T值不低于负一点零为正常，低于负二点五为骨质疏松。"},{id:"cs-9980",module:"changshi",prompt:"成年人正常牙齿数量是？",options:["二十八至三十二颗", "二十颗", "四十颗", "十六颗"],answer:0,explanation:"成年人正常牙齿为二十八至三十二颗，包括智齿，乳牙为二十颗。"},{id:"cs-9981",module:"changshi",prompt:"成年人正常脊柱有几个生理弯曲？",options:["四个", "两个", "三个", "五个"],answer:0,explanation:"成年人脊柱有颈曲、胸曲、腰曲和骶曲四个生理弯曲，维持身体平衡。"},{id:"cs-9982",module:"changshi",prompt:"成年人正常体脂率男性应不超过？",options:["百分之二十", "百分之三十", "百分之十", "百分之四十"],answer:0,explanation:"成年男性体脂率应不超过百分之二十，女性不超过百分之三十，过高增加健康风险。"},{id:"cs-9983",module:"changshi",prompt:"成年人正常握力男性应不低于？",options:["二十六千克", "十五千克", "四十千克", "十千克"],answer:0,explanation:"成年男性握力应不低于二十六千克，女性不低于十八千克，反映肌肉力量。"},{id:"cs-9984",module:"changshi",prompt:"发现青霉素的科学家是？",options:["弗莱明", "巴斯德", "科赫", "达尔文"],answer:0,explanation:"弗莱明一九二八年发现青霉素，开创了抗生素时代，获一九四五年诺贝尔奖。"},{id:"cs-9985",module:"changshi",prompt:"发现X射线的科学家是？",options:["伦琴", "居里夫人", "贝克勒尔", "卢瑟福"],answer:0,explanation:"伦琴一八九五年发现X射线，为医学影像学奠定基础，获首届诺贝尔物理学奖。"},{id:"cs-9986",module:"changshi",prompt:"发现镭元素的科学家是？",options:["居里夫人", "伦琴", "贝克勒尔", "卢瑟福"],answer:0,explanation:"居里夫人与丈夫皮埃尔发现镭和钋，两次获诺贝尔奖，是放射性研究的先驱。"},{id:"cs-9987",module:"changshi",prompt:"提出相对论的科学家是？",options:["爱因斯坦", "牛顿", "霍金", "普朗克"],answer:0,explanation:"爱因斯坦提出狭义相对论和广义相对论，改变了人类对时空的认识。"},{id:"cs-9988",module:"changshi",prompt:"提出量子概念的科学家是？",options:["普朗克", "爱因斯坦", "玻尔", "海森堡"],answer:0,explanation:"普朗克一九零零年提出量子概念，开创了量子力学时代。"},{id:"cs-9989",module:"changshi",prompt:"发现电磁感应现象的科学家是？",options:["法拉第", "安培", "欧姆", "伏特"],answer:0,explanation:"法拉第一八三一年发现电磁感应现象，为发电机和电动机的发明奠定基础。"},{id:"cs-9990",module:"changshi",prompt:"发明电灯的发明家是？",options:["爱迪生", "法拉第", "特斯拉", "富兰克林"],answer:0,explanation:"爱迪生改进白炽灯并实现商业化，改变了人类的照明方式。"},{id:"cs-9991",module:"changshi",prompt:"发明电话的发明家是？",options:["贝尔", "爱迪生", "马可尼", "莫尔斯"],answer:0,explanation:"贝尔一八七六年发明电话，开创了远程通信时代。"},{id:"cs-9992",module:"changshi",prompt:"发明无线电的发明家是？",options:["马可尼", "贝尔", "爱迪生", "莫尔斯"],answer:0,explanation:"马可尼发明无线电报，获一九零九年诺贝尔物理学奖。"},{id:"cs-9993",module:"changshi",prompt:"发明电报的发明家是？",options:["莫尔斯", "贝尔", "爱迪生", "马可尼"],answer:0,explanation:"莫尔斯发明电报和莫尔斯电码，是远程通信的开端。"},{id:"cs-9994",module:"changshi",prompt:"发明汽车的发明家是？",options:["卡尔本茨", "福特", "戴姆勒", "迈巴赫"],answer:0,explanation:"卡尔本茨一八八五年发明世界上第一辆内燃机汽车，被誉为汽车之父。"},{id:"cs-9995",module:"changshi",prompt:"发明飞机的发明家是？",options:["莱特兄弟", "冯如", "达芬奇", "齐柏林"],answer:0,explanation:"莱特兄弟一九零三年发明并试飞世界上第一架动力飞机。"},{id:"cs-9996",module:"changshi",prompt:"发明电视的发明家是？",options:["贝尔德", "爱迪生", "马可尼", "贝尔"],answer:0,explanation:"贝尔德一九二五年发明机械扫描电视，开创了电视时代。"},{id:"cs-9997",module:"changshi",prompt:"发明计算机的先驱是？",options:["图灵和冯诺依曼", "爱迪生", "贝尔", "莫尔斯"],answer:0,explanation:"图灵提出图灵机理论，冯诺依曼提出存储程序计算机架构，是计算机科学的奠基人。"},{id:"cs-9998",module:"changshi",prompt:"发明互联网的先驱是？",options:["伯纳斯李", "图灵", "冯诺依曼", "比尔盖茨"],answer:0,explanation:"伯纳斯李发明万维网WWW，使互联网走向大众化。"},{id:"cs-9999",module:"changshi",prompt:"发明印刷机的发明家是？",options:["古腾堡", "毕昇", "王祯", "蔡伦"],answer:0,explanation:"古腾堡十五世纪发明活字印刷机，推动了欧洲文艺复兴和宗教改革。"},{id:"cs-10000",module:"changshi",prompt:"发明望远镜的发明家是？",options:["伽利略", "牛顿", "开普勒", "胡克"],answer:0,explanation:"伽利略改进望远镜并用于天文观测，发现了木星卫星等。"},{id:"cs-10001",module:"changshi",prompt:"发明显微镜的发明家是？",options:["列文虎克", "伽利略", "牛顿", "胡克"],answer:0,explanation:"列文虎克改进显微镜并首次观察到微生物，开创了微生物学。"},{id:"cs-10002",module:"changshi",prompt:"发明温度计的发明家是？",options:["伽利略", "牛顿", "开尔文", "摄氏"],answer:0,explanation:"伽利略发明了早期温度计，摄氏提出摄氏温标，华氏提出华氏温标。"},{id:"cs-10003",module:"changshi",prompt:"发明气压计的发明家是？",options:["托里拆利", "伽利略", "帕斯卡", "波义耳"],answer:0,explanation:"托里拆利发明水银气压计，证明大气压的存在。"},{id:"cs-10004",module:"changshi",prompt:"发明蒸汽机车的发明家是？",options:["史蒂芬孙", "瓦特", "富尔顿", "特里维西克"],answer:0,explanation:"史蒂芬孙发明蒸汽机车并修建第一条铁路，是铁路之父。"},{id:"cs-10005",module:"changshi",prompt:"发明轮船的发明家是？",options:["富尔顿", "史蒂芬孙", "瓦特", "卡文迪什"],answer:0,explanation:"富尔顿发明蒸汽轮船，开创了水上运输的新时代。"},{id:"cs-10006",module:"changshi",prompt:"发明照相术的发明家是？",options:["达盖尔", "爱迪生", "贝尔", "莫尔斯"],answer:0,explanation:"达盖尔发明银版照相法，是现代摄影术的开端。"},{id:"cs-10007",module:"changshi",prompt:"发明复印机的发明家是？",options:["卡尔森", "爱迪生", "贝尔", "莫尔斯"],answer:0,explanation:"卡尔森发明静电复印技术，是现代复印机的发明者。"},{id:"cs-10008",module:"changshi",prompt:"发明空调的发明家是？",options:["开利", "爱迪生", "贝尔", "莫尔斯"],answer:0,explanation:"开利发明现代空调系统，改变了人类的生活和工作环境。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-10009",module:"changshi",prompt:"健康体检常识：中国最大的岛屿是？",options:["台湾岛", "海南岛", "崇明岛", "舟山岛"],answer:0,explanation:"台湾岛面积约三点六万平方公里，是中国最大的岛屿，海南岛次之。"},{id:"cs-10010",module:"changshi",prompt:"科技史常识：中国最大的平原是？",options:["东北平原", "华北平原", "长江中下游平原", "成都平原"],answer:0,explanation:"东北平原面积约三十五万平方公里，是中国最大的平原，土壤肥沃。"},{id:"cs-10011",module:"changshi",prompt:"中国地理常识：中国最大的盆地是？",options:["塔里木盆地", "准噶尔盆地", "柴达木盆地", "四川盆地"],answer:0,explanation:"塔里木盆地位于新疆南部，面积约五十三万平方公里，是中国最大的盆地。"},{id:"cs-10012",module:"changshi",prompt:"世界文化遗产知识：中国最大的瀑布是？",options:["黄果树瀑布", "壶口瀑布", "庐山瀑布", "德天瀑布"],answer:0,explanation:"黄果树瀑布位于贵州安顺，高约七十七米，是中国最大的瀑布。"},{id:"cs-10013",module:"changshi",prompt:"健康体检常识：中国最大的沙漠是？",options:["塔克拉玛干沙漠", "古尔班通古特沙漠", "巴丹吉林沙漠", "腾格里沙漠"],answer:0,explanation:"塔克拉玛干沙漠位于新疆塔里木盆地，面积约三十三万平方公里，是中国最大的沙漠。"},{id:"cs-10014",module:"changshi",prompt:"科技史常识：中国最深的湖泊是？",options:["长白山天池", "喀纳斯湖", "抚仙湖", "青海湖"],answer:0,explanation:"长白山天池最深处约三百七十三米，是中国最深的湖泊，位于吉林长白山。"},{id:"cs-10015",module:"changshi",prompt:"中国地理常识：中国最热的地区是？",options:["吐鲁番", "重庆", "武汉", "南京"],answer:0,explanation:"吐鲁番盆地夏季气温常超过四十度，是中国最热的地区，有火洲之称。"},{id:"cs-10016",module:"changshi",prompt:"世界文化遗产知识：中国最冷的地区是？",options:["漠河", "哈尔滨", "长春", "呼和浩特"],answer:0,explanation:"黑龙江漠河冬季最低气温可达零下五十度，是中国最冷的地区。"},{id:"cs-10017",module:"changshi",prompt:"中国地理常识：中国最大的油田是？",options:["大庆油田", "胜利油田", "辽河油田", "克拉玛依油田"],answer:0,explanation:"大庆油田位于黑龙江，是中国最大的油田，年产量长期居全国首位。"},{id:"cs-10018",module:"changshi",prompt:"健康体检常识：中国最大的港口是？",options:["上海港", "宁波舟山港", "深圳港", "青岛港"],answer:0,explanation:"上海港是中国最大的港口，货物吞吐量和集装箱吞吐量均居世界前列。"},{id:"cs-10019",module:"changshi",prompt:"科技史常识：中国最大的机场是？",options:["北京大兴国际机场", "上海浦东国际机场", "广州白云国际机场", "成都天府国际机场"],answer:0,explanation:"北京大兴国际机场是世界上最大的单体航站楼机场之一，设计先进。"},{id:"cs-10020",module:"changshi",prompt:"健康体检常识：发明火箭的先驱是？",options:["戈达德", "冯布劳恩", "齐奥尔科夫斯基", "科罗廖夫"],answer:0,explanation:"戈达德一九二六年发射世界上第一枚液体燃料火箭，是现代火箭技术的先驱。"});
